def _dash_by_word(tok):
    """``(row name or None, name as typed, has parentheses, argument)`` of
    one by() sub-option token under ``_DASH_BY_GRAMMAR`` (WP-30 P1.15b):
    case-sensitive, the first declared row of which the word is a
    spelling.  Never raises; linear in the token."""
    tok = str(tok)
    paren = "(" in tok
    typed = tok.split("(", 1)[0].strip()
    arg = ""
    if paren:
        arg = tok[tok.index("(") + 1:]
        arg = arg[:-1] if arg.endswith(")") else arg
    table = getattr(_dash_by_word, "_table", None)
    if table is None:
        # {(spelling, takes parentheses): row}, the first declared row
        # of each spelling kept; built once.
        table = {}
        for row, (mn, takes, _stage, _rep) in _DASH_BY_GRAMMAR.items():
            for k in range(len(mn), len(row) + 1):
                table.setdefault((row[:k], bool(takes)), row)
        _dash_by_word._table = table
    return table.get((typed, paren)), typed, paren, arg

#: by()'s text sub-options and every spelling twoway takes (WP-30 P1.15a),
#: matched case-sensitively: probes a06 (ti, sub, cap), a14 (``t("X")`` is
#: accepted by twoway and draws nothing, so it is not a spelling here), a15
#: (``no("X")`` is refused: note has no shorter form) and a12 (``TITLE()``
#: is refused, r(198), and stays named until by()'s refusals land).
_DASH_BY_TEXT_SPELLINGS = {
    "title": ("ti", "tit", "titl", "title"),
    "subtitle": ("sub", "subt", "subti", "subtit", "subtitl", "subtitle"),
    "note": ("note",),
    "caption": ("cap", "capt", "capti", "captio", "caption"),
    # WP-41 BY-12: the eight edge titles, each from the grammar's shortest
    # spelling to the full word, drawn by _dash_by_chrome (t1, t2, b2) and
    # _dash_by_side (l1, b1, l2, r1, r2).
    "l1title": ("l1", "l1t", "l1ti", "l1tit", "l1titl", "l1title"),
    "l2title": ("l2", "l2t", "l2ti", "l2tit", "l2titl", "l2title"),
    "r1title": ("r1", "r1t", "r1ti", "r1tit", "r1titl", "r1title"),
    "r2title": ("r2", "r2t", "r2ti", "r2tit", "r2titl", "r2title"),
    "t1title": ("t1", "t1t", "t1ti", "t1tit", "t1titl", "t1title"),
    "t2title": ("t2", "t2t", "t2ti", "t2tit", "t2titl", "t2title"),
    "b1title": ("b1", "b1t", "b1ti", "b1tit", "b1titl", "b1title"),
    "b2title": ("b2", "b2t", "b2ti", "b2tit", "b2titl", "b2title"),
}


def _dash_by_tokens(subopts):
    """Split a by() sub-option string into its options.

    ``rows(2) title("By origin") compact`` is three options, not five words:
    a parenthesised argument may hold spaces and quotes.  Splitting on
    whitespace alone is how ``holes(1 3)`` would be reported as two.

    Inside an argument a string is read as Stata reads one: ``"..."``, or
    the compound ```"..."'``, which nests.  A single quote is a character,
    not a quote -- this read it as one, so an apostrophe took every
    sub-option after it into its token: ``by(foreign, title(Bob's cars)
    cols(2))`` lost cols(2), and an unimplemented sub-option after one, in
    legend() or any option split here, was dropped without a word.  One
    pass over the text, whatever quotes and parentheses it holds or leaves
    open.
    """
    text = str(subopts)
    out, buf, depth = [], [], 0
    simple = False          # inside "..."
    compound = 0            # how deep inside `"..."'
    i, n = 0, len(text)
    while i < n:
        ch = text[i]
        two = text[i:i + 2]
        if compound:
            if two in ('`"', '"\''):
                compound += 1 if two == '`"' else -1
                buf.append(two)
                i += 2
            else:
                buf.append(ch)
                i += 1
            continue
        if simple:
            buf.append(ch)
            simple = ch != '"'
            i += 1
            continue
        if depth and two == '`"':
            compound = 1
            buf.append(two)
            i += 2
            continue
        if depth and ch == '"':
            simple = True
            buf.append(ch)
            i += 1
            continue
        if ch == "(":
            depth += 1
        elif ch == ")":
            depth = max(0, depth - 1)
        if ch.isspace() and depth == 0:
            if buf:
                out.append("".join(buf))
                buf = []
            i += 1
            continue
        buf.append(ch)
        i += 1
    if buf:
        out.append("".join(buf))
    return out


def _dash_parse_by(by_raw, warn=True):
    """Parse ``by(varlist [, subopts])`` the same way in both render modes.

    Returns ``(varlist, by_cols, by_total, by_missing, unsupported)``.  The
    varlist is "" when the string carries an injection pattern, and callers
    treat an empty varlist as "no faceting", which is what both renderers
    did with their own copies of the check.

    Stata's by() takes some thirty sub-options; dash implements cols(),
    total, missing, the rescale words, rows(), holes(), colfirst,
    compact, style(compact), iscale() and imargin() (laid out by
    ``_dash_layout_cell``, WP-30 P1.15b), drawn by ``_dash_by_chrome``
    (WP-30 P1.15a), title(), subtitle(), note() and caption(), and, drawn
    by ``_dash_by_side`` (WP-30 P1.15c), the i*/noi* axis and title
    words, edgelabel, individual, ilegends, legend() and clegend(), and
    (WP-31 D10) graphregion(), plotregion(), subtitleformat() and the
    shrink words noshrink, noishrink, nooverallshrink and ishrink, each
    in twoway's lower-case spellings (``_DASH_BY_GRAMMAR``).  The
    rest used to be matched by nothing and discarded by everything --
    ``by(foreign, rows(2) compact)`` faceted as though the user had typed
    ``by(foreign)``, and nothing said so.  They are named here, once, in
    one warning, because a sub-option that is not implemented must be
    NAMED rather than silently dropped (ROADMAP BR-11.2).  Implementing
    them is other work.

    ``warn=False`` parses without reporting.  The saved renderer parses a
    graph's by() twice -- once to group the frame and once, in the layout,
    for its cols(#) -- and reported the same sub-options twice per render.
    The grouping parse reports; the layout parse does not.

    Only the variable list -- the text before the first comma, which no
    variable name contains -- is held to ``_DASH_UNSAFE_BY`` and must be
    Stata names.  The sub-options are the user's text: a title() there may
    hold anything, and is named below as not implemented, as typed.  A
    variable list that is refused is said to be refused (never echoed:
    it is what failed the check), and the graph is drawn without panels.
    """
    by_raw = (by_raw or "").strip()
    if not by_raw:
        return "", 0, False, False, []
    varlist_part, _, subopts = by_raw.partition(",")
    varlist = varlist_part.strip()
    names = varlist.split()
    if (not names or _DASH_UNSAFE_BY.search(varlist)
            or not all(_dash_is_stata_name(v) for v in names)):
        if warn:
            warnings.warn(
                "dash: by() variable list is not a list of variable names;"
                " the graph is drawn without panels.",
                UserWarning, stacklevel=2,
            )
        return "", 0, False, False, []
    varlist = " ".join(names)
    by_cols, by_total, by_missing = 0, False, False
    unsupported = []
    for tok in _dash_by_tokens(subopts.strip()):
        # Case-sensitive (WP-30 P1.15b): twoway refuses YRESCALE and
        # TOTAL, so a capitalised word is no spelling and is named.
        name = tok.split("(", 1)[0].strip()
        arg = tok[len(name) + 1:-1] if "(" in tok and tok.endswith(")") else ""
        _row = _dash_by_word(tok)[0]
        if _row in ("rows", "colfirst", "holes", "compact", "iscale",
                    "imargin") or (_row == "style" and arg.strip() in
                                   ("compact", "default")):
            # laid out by `_dash_layout_cell` (WP-30 P1.15b).
            pass
        elif name in _DASH_BY_SUPPORTED["cols"] and "(" in tok:
            try:
                by_cols = int(arg.strip())
            except ValueError:
                unsupported.append(tok)
        elif name in _DASH_BY_SUPPORTED["total"] and "(" not in tok:
            by_total = True
        elif name in _DASH_BY_SUPPORTED["missing"] and "(" not in tok:
            by_missing = True
        elif "(" not in tok and any(name in _DASH_BY_SUPPORTED[k]
                                    for k in _DASH_BY_RESCALE_KEYS):
            # yrescale, xrescale, rescale and their no forms: honoured by
            # _dash_by_rescale (WP-29 P0.2), never named.
            pass
        elif _dash_by_text_key(tok) is not None:
            # title(), subtitle(), note(), caption(): drawn by
            # _dash_by_chrome (WP-30 P1.15a).
            pass
        elif (_row in _DASH_BY_AXES_SPELLINGS and "(" not in tok) or (
                _row in ("legend", "clegend", "legloc", "clegloc",
                         "plegend", "plegloc") and "(" in tok):
            # The i*/no* axis and title words, edgelabel, individual,
            # ilegends, legend() and clegend(): drawn by `_dash_by_side`
            # (WP-30 P1.15c); legloc(), clegloc(), plegend() and
            # plegloc() too (WP-41 BY-13, BY-14).
            pass
        elif (_row in ("graphregion", "plotregion", "subtitleformat")
              and "(" in tok) or (
                _row in ("noshrink", "noishrink", "nooverallshrink",
                         "ishrink", "shrink", "overallshrink")
                and "(" not in tok):
            # WP-31 D10: by()'s regions are drawn on the array
            # (_dash_by_apply_regions, which names their margin()),
            # subtitleformat() formats the panel labels
            # (_dash_by_subtitle_format), and these four shrink words
            # change nothing twoway draws under any shipped scheme
            # (measured: by_remainder_truth.json shrink_*); shrink and
            # overallshrink draw the contents smaller (WP-31 D10b,
            # _dash_by_shrink_factor).
            pass
        elif name == "style" and arg.strip() == "altleg":
            # style(altleg) draws as style(default) (WP-31 D10b, measured:
            # bystyle_altleg).
            pass
        elif name == "style" and arg.strip() in ("rescale", "combine"):
            # style(rescale|combine): written as the options they draw by
            # _dash_bystyle_route (WP-31 D10c) before the graph is drawn;
            # a direct parse still draws their separate scales
            # (_dash_by_rescale), in silence.
            pass
        elif _row == "bgcolor" and "(" in tok:
            # WP-41 BY-7: the by() grid's background
            # (_dash_by_array_styles), under every shipped scheme covered
            # by the cells' own fill, as twoway's graph region covers its
            # canvas.
            pass
        elif _row == "scale" and "(" in tok and \
                _dash_by_scale_arg(arg) is not None:
            # WP-41 BY-2: a positive number scales the whole by() graph
            # (_dash_by_scale_mult); anything else is named.
            pass
        else:
            unsupported.append(tok)
    if unsupported and warn:
        # Names ONLY what was dropped.  Naming the three that work beside
        # them read as though those had been dropped too.
        warnings.warn(
            "dash: by() sub-option(s) not implemented and ignored: "
            + " ".join(unsupported),
            UserWarning, stacklevel=2,
        )
    return varlist, by_cols, by_total, by_missing, unsupported


#: WP-31 D10c: the bystyles whose bygraphstyle-<name>.style twoway draws
#: exactly as by() words plus graph options (bystyle_truth.json: the
#: exported SVGs are line for line the same, s2color).  combine's graph
#: regions do not reduce to options and stay named.
_DASH_BYSTYLE_EXPAND = {
    "econ": ((), {"subtitle": ", margin(small)",
                  "plotregion": "color(edkbg) margin(t=5)"}, ""),
    "stata7": (("edgelabel", "ixaxes", "iyaxes", "imargin(small)"),
               {"ylabel": "#2, labsize(small)",
                "xlabel": "#2, labsize(small)",
                "xmtick": "##4, style(major_horiz_nolabel)",
                "ymtick": "##4, style(major_vert_nolabel)",
                "subtitle": ", nobox size(small) position(11)",
                "plotregion": "style(none)"}, ""),
    "rescale": (("rescale", "individual", "imargin(medsmall)"),
                {"subtitle": ", box astextbox blstyle(foreground)",
                 "ylabel": "#3", "xlabel": "#3"}, ""),
    # combine (bystyle_truth.json: 600 SVG lines differ from these): its
    # words and its unboxed labels; twoway lays its panels in graph
    # combine's regions, by()'s grid here (M17), named once.
    "combine": (("rescale", "individual", "ixtitle", "iytitle",
                 "imargin(medsmall)"), {"subtitle": ", nobox"},
                "its panels are laid out on by()'s grid, not in graph "
                "combine's regions."),
}


def _dash_bystyle_rescale_words(words, toks):
    """*words* (a style's expansion) with its ``rescale`` narrowed to the
    axes no word of *toks* (the by() sub-options) keeps shared:
    ``noxrescale``/``noyrescale`` drop one axis, ``norescale`` both
    (``_DASH_BY_SUPPORTED``'s spellings).  twoway reads the style's
    rescale as the default an explicit no-word overrides (measured
    18oct2026: ``style(rescale) noyrescale`` shares y)."""
    if "rescale" not in words:
        return tuple(words)
    kept = {"x", "y"}
    for tok in toks:
        name = tok.split("(", 1)[0].strip().lower()
        if name in _DASH_BY_SUPPORTED["norescale"]:
            kept.clear()
        elif name in _DASH_BY_SUPPORTED["noxrescale"]:
            kept.discard("x")
        elif name in _DASH_BY_SUPPORTED["noyrescale"]:
            kept.discard("y")
    with_ = ("rescale",) if kept == {"x", "y"} else tuple(
        d + "rescale" for d in ("x", "y") if d in kept)
    out = []
    for w in words:
        out.extend(with_ if w == "rescale" else (w,))
    return tuple(out)


def _dash_bystyle_route(spec):
    """The spec with each graph's ``by(..., style(econ|stata7|rescale))``
    written as the by() words and graph options it draws as (WP-31 D10c,
    ``_DASH_BYSTYLE_EXPAND``): the style() word is replaced by the words,
    and each option is added where the graph does not give it itself (its
    own wins).  Any other style, and a spec that is not one, unchanged.
    Both renderers call it before the spec is drawn or embedded; never
    raises."""
    try:
        graphs = spec.get("graphs") if isinstance(spec, dict) else None
        if not isinstance(graphs, list):
            return spec
        for g in graphs:
            if not isinstance(g, dict):
                continue
            go = g.get("graph_options")
            if not isinstance(go, dict):
                continue
            by = go.get("by")
            if not isinstance(by, str) or "," not in by:
                continue
            head, _c, subs = by.partition(",")
            toks = _dash_by_tokens(subs.strip())
            hit = None
            for i, tok in enumerate(toks):
                if tok.split("(", 1)[0].strip() == "style" and "(" in tok:
                    arg = tok[tok.index("(") + 1:]
                    arg = (arg[:-1] if arg.endswith(")") else arg).strip()
                    hit = (i, arg)
                    break
            if hit is None or hit[1] not in _DASH_BYSTYLE_EXPAND:
                continue
            words, opts, left = _DASH_BYSTYLE_EXPAND[hit[1]]
            if left:
                _dash_warn_once(("bystyle", hit[1]),
                                "dash: by() sub-option style(%s): %s"
                                % (hit[1], left))
            # The style's rescale is its default: a no-word the user gives
            # beside it still keeps that axis shared, as twoway draws
            # style(rescale) noyrescale (WP-32; the word rescale would beat
            # it in _dash_by_rescale).
            words = _dash_bystyle_rescale_words(words, toks)
            rest = toks[:hit[0]] + list(words) + toks[hit[0] + 1:]
            new_by = head.rstrip() + ((", " + " ".join(rest)) if rest else "")
            targets = [go] + ([g["options"]] if isinstance(
                g.get("options"), dict) else [])
            for t in targets:
                t["by"] = new_by
                for k, v in opts.items():
                    if not str(t.get(k, "") or "").strip():
                        t[k] = v
        return spec
    except Exception:   # noqa: BLE001 -- the spec is drawn either way
        return spec


def _dash_by_rescale(by_raw):
    """The letters (``"x"``, ``"y"``) a by() graph draws on each panel's own
    scale, as twoway decides them (bygraph_g.class:292-385, WP-29 P0.2).

    ``rescale`` rescales both axes and, failing it, ``norescale`` neither;
    ``xrescale``/``yrescale`` and ``noxrescale``/``noyrescale`` decide one
    axis, a yes winning over a no; with neither, the last ``style()``
    decides -- exactly ``style(rescale)`` or ``style(combine)`` rescales
    both, any other style (``style(resc)``, ``style(compact)``) neither.
    ``compact`` never matters.  Only the text after the first comma is
    read, through the quote-aware ``_dash_by_tokens``, so ``title("yrescale")``
    is text; a word in capitals is read as its lower-case spelling (twoway
    refuses it; a by() validation item).  Never raises on any input and is
    linear.  Returns a frozenset.
    """
    try:
        text = by_raw if isinstance(by_raw, str) else str(by_raw)
    except Exception:  # noqa: BLE001 -- any object at all
        return frozenset()
    _, comma, subs = text.partition(",")
    if not comma:
        return frozenset()
    yes, no, base = set(), set(), False
    for tok in _dash_by_tokens(subs.strip()):
        name = tok.split("(", 1)[0].strip().lower()
        if "(" in tok:
            if name == "style":
                arg = tok[tok.index("(") + 1:]
                arg = arg[:-1] if arg.endswith(")") else arg
                base = arg.strip() in ("rescale", "combine")
            continue
        if name in _DASH_BY_SUPPORTED["rescale"]:
            yes |= {"x", "y"}
        elif name in _DASH_BY_SUPPORTED["norescale"]:
            no |= {"x", "y"}
        elif name in _DASH_BY_SUPPORTED["xrescale"]:
            yes.add("x")
        elif name in _DASH_BY_SUPPORTED["yrescale"]:
            yes.add("y")
        elif name in _DASH_BY_SUPPORTED["noxrescale"]:
            no.add("x")
        elif name in _DASH_BY_SUPPORTED["noyrescale"]:
            no.add("y")
    return frozenset(d for d in ("x", "y")
                     if d in yes or (d not in no and base))


def _dash_by_grid_options(by_raw):
    """The grid sub-options of a by() string (WP-30 P1.15b, TR-48.7):
    ``{"rows", "cols", "holes", "colfirst", "compact", "style", "iscale",
    "imargin"}``, each the FIRST copy as twoway's ``syntax`` reads it,
    case-sensitive through ``_DASH_BY_GRAMMAR``.  ``rows``/``cols`` are a
    positive integer or 0, ``holes`` a tuple of distinct positive
    integers (``_dash_expand_numlist``, at most 300); anything else is
    dropped silently -- dash.ado refused it in twoway's words.  Never
    raises; linear in the text."""
    out = {"rows": 0, "cols": 0, "holes": (), "colfirst": False,
           "compact": False, "style": "", "iscale": "", "imargin": ""}
    try:
        text = by_raw if isinstance(by_raw, str) else str(by_raw or "")
    except Exception:  # noqa: BLE001 -- any object at all
        return out
    _, comma, subs = text.partition(",")
    if not comma:
        return out
    seen = set()
    for tok in _dash_by_tokens(subs.strip()):
        row, _typed, _paren, arg = _dash_by_word(tok)
        if row is None or row in seen:
            continue
        seen.add(row)
        if row in ("rows", "cols"):
            a = arg.strip()
            out[row] = (min(int(a), 10 ** 9)
                        if re.fullmatch(r"[0-9]{1,40}", a) else 0)
        elif row == "holes":
            vals, too_many, bad = _dash_expand_numlist(arg.split(),
                                                       limit=300)
            if not too_many and not bad:
                keep = []
                for v in vals:
                    if math.isfinite(v) and v >= 1 and v == int(v) \
                            and int(v) not in keep:
                        keep.append(int(v))
                out["holes"] = tuple(keep)
        elif row in ("colfirst", "compact"):
            out[row] = True
        elif row in ("style", "iscale", "imargin"):
            out[row] = arg.strip()
    return out


def _dash_by_positions(n_panels, opts, legend_at=0, clegend_at=0,
                       limit=None):
    """twoway's by() placement (WP-30 P1.15b, TR-48.8): a port of
    bygraph_g.class ``full_n``, ``set_rows_cols`` and ``set_placement``
    (:794-908).  ``full_n`` is the panels plus the distinct holes plus
    the legend holes; ``cols(#)`` sets the rows to 1 + int((full_n-1)/#),
    ``rows(#)`` the reverse, else cols = int(sqrt(full_n)) + (frac > .01);
    cells are filled from the top left, along the rows (``colfirst``:
    down the columns), a hole's index skipped.

    Returns ``(cells, rows, cols, extra)``: ``cells[i]`` is panel i's
    ``(row_from_top, col)``, 0-based, in twoway's logical grid;
    ``extra["full_n"]`` is full_n, ``extra["legend"]``/``["clegend"]``
    their cells (for S53) and ``extra["drawn"]`` ``(cells, rows, cols)``
    with the rows and columns that hold nothing removed -- twoway draws
    no empty row or column (by_grid_truth.json: ``holes(1 2 3)`` draws
    as ``by(rep78)``, ``cols(5)`` of two panels as ``by(foreign)``).
    ``rows``/``cols`` are bounded at *limit* (the by_groups ceiling).
    Pure; linear in full_n."""
    if limit is None:
        limit = _DASH_LIMITS["by_groups"][1]
    n_p = max(0, int(n_panels or 0))
    opts = opts or {}
    holes = set(int(h) for h in (opts.get("holes") or ()))
    n = n_p + len(holes) + (legend_at > 0) + (clegend_at > 0)
    n = max(1, n)
    set_cols = min(max(0, int(opts.get("cols") or 0)), int(limit))
    set_rows = min(max(0, int(opts.get("rows") or 0)), int(limit))
    if set_cols:
        cols = set_cols
        rows = 1 + (n - 1) // cols
    elif set_rows:
        rows = set_rows
        cols = 1 + (n - 1) // rows
    else:
        r = math.sqrt(n)
        cols = int(r) + ((r - int(r)) > .01)
        rows = 1 + (n - 1) // cols
    colfirst = bool(opts.get("colfirst"))
    cells, extra = [], {"full_n": n}
    r, c, j = rows, 1, 0
    for i in range(1, n + 1):
        if i not in holes:
            if i == legend_at:
                extra["legend"] = (rows - r, c - 1)
            elif i == clegend_at:
                extra["clegend"] = (rows - r, c - 1)
            else:
                j += 1
                if j <= n_p:
                    cells.append((rows - r, c - 1))
        if not colfirst:
            c += 1
            if c > cols:
                c, r = 1, r - 1
        else:
            r -= 1
            if r == 0:
                r, c = rows, c + 1
    used = list(cells) + [extra[k] for k in ("legend", "clegend")
                          if k in extra]
    rmap = {v: k for k, v in enumerate(sorted({p[0] for p in used}))}
    cmap = {v: k for k, v in enumerate(sorted({p[1] for p in used}))}
    extra["drawn"] = ([(rmap[a], cmap[b]) for a, b in cells],
                      max(1, len(rmap)), max(1, len(cmap)))
    return cells, rows, cols, extra


def _dash_by_hole_ats(go, has_colour_key):
    """``(legend_at, clegend_at)``: the grid holes by()'s keys reserve
    (WP-41 BY-3, D-41-04.a), read from the merged legend() and clegend()
    copies of graph options *go*'s by() (``_dash_by_axes_options``).

    twoway's SetLegend and SetClegend set legend_hole/clegend_hole from
    ``at()`` whether or not the key is drawn (bygraph_g.class :612-618,
    :670-676; by_chrome_truth.json K01-K03): a legend hole whenever at()
    is given (every graph has a legend object), a colour-key hole only
    when the graph has a colour key (*has_colour_key*; K04 makes none);
    neither under ``ilegends``, where both exit.  The first ``at(#)``
    copy wins, as twoway reads it (measured: ``legend(at(1) at(3))`` is
    hole 1).  Pure; never raises."""
    by = (go or {}).get("by") if isinstance(go, dict) else None
    try:
        opts = _dash_by_axes_options(by)
    except Exception:  # noqa: BLE001 -- no holes
        return 0, 0
    if (opts.get("flags") or {}).get("indiv_legends"):
        return 0, 0
    ats = []
    for key in ("legend", "clegend"):
        at = 0
        for tok in _dash_by_tokens(str(opts.get(key) or "")):
            m = re.fullmatch(r"at\(\s*([0-9]{1,9})\s*\)", tok.strip())
            if m:
                at = int(m.group(1))
                break
        ats.append(at)
    return ats[0], (ats[1] if has_colour_key else 0)


#: Each shipped scheme's ``margin by_indiv`` (WP-30 P1.15b, D-48e), read
#: through its #include chain by scripts/extract_by_grid_truth.do
#: (by_grid_truth.json ``by_indiv``).  No dash scheme file carries the
#: key yet (S53 adds it), so ``SchemeParser.by_indiv_margin`` reads the
#: scheme's own key first and this table only when it is missing.
_DASH_BY_INDIV_MARGIN = {
    "economist": "medium", "meta": "small", "s1color": "small",
    "s1manual": "small", "s1mono": "small", "s1rcolor": "small",
    "s2color": "small", "s2color8": "small", "s2gcolor": "small",
    "s2gmanual": "small", "s2manual": "small", "s2mono": "small", "sj":
    "small", "stcolor": "allsides-ms", "stcolor_alt": "allsides-ms",
    "stcolor_meta": "allsides-ms", "stcolor_mv": "allsides-ms",
    "stcoloralias": "allsides-ms", "stgcolor": "allsides-ms",
    "stgcolor_alt": "allsides-ms", "stgcolor_meta": "allsides-ms",
    "stgcolor_mv": "allsides-ms", "stmono1": "allsides-ms", "stmono2":
    "allsides-ms", "stsj": "small", "sttrans": "small"
}


def _dash_by_size_mult(by_raw, full_n):
    """The multiplier twoway draws a by() panel's text, markers and lines
    at (WP-30 P1.15b, TR-48.9): f(k), k = ceil(sqrt(full_n)), section
    21's gmetric curve (``_DASH_BY_GMETRIC``: 1, .85, .8, .6, .48, .4,
    2.4/k; by_grid_truth.json ``sizes``: two panels .85, ten .60);
    ``iscale(#)`` is #, ``iscale(*#)`` f times #, unreadable text f (dash
    noted it).  Bounded to [0, 10000]; silent; never raises."""
    try:
        k = max(1, math.ceil(math.sqrt(max(1, int(full_n)))))
    except (TypeError, ValueError, OverflowError):
        k = 1
    k1, b1, b2 = _DASH_BY_GMETRIC
    f = 1.0 - (k - 1.0) / k * b1
    if k > k1:
        f -= (b2 - b1) * (k - k1) / k
    f = max(0.0, f)
    raw = _dash_by_grid_options(by_raw)["iscale"]
    num = r"[+-]?(?:[0-9]+\.?[0-9]*|\.[0-9]+)(?:[eE][+-]?[0-9]{1,4})?"
    m = re.fullmatch(r"\s*(\*)?\s*(" + num + r")\s*", raw or "")
    if m:
        try:
            v = float(m.group(2))
        except (ValueError, OverflowError):
            v = None
        if v is not None and math.isfinite(v):
            f = f * v if m.group(1) else v
    # WP-31 D10b: shrink and overallshrink draw the contents smaller.
    f *= _dash_by_shrink_factor(by_raw)
    # WP-41 BY-2: by(, scale(#)) scales the whole by() graph.
    f *= _dash_by_scale_mult(by_raw)
    return max(0.0, min(10000.0, f))


#: The share of a by() graph's height each of by()'s own texts takes from
#: the panels under shrink/overallshrink (WP-31 D10b), measured under
#: s2color (by_remainder_truth.json shrink_*): the panels keep 0.894 of it
#: with no text; the note takes 0.0393, a title 0.0600, a subtitle 0.0475,
#: a caption 0.0466 and each further line of any of them 0.047.
_DASH_BY_SHRINK_SHARES = {"base": 0.894, "note": 0.0393, "title": 0.0600,
                          "subtitle": 0.0475, "caption": 0.0466,
                          "line": 0.047}


def _dash_by_shrink_factor(by_raw):
    """The factor twoway draws a by() graph's panel contents at under
    ``shrink`` or ``overallshrink`` (WP-31 D10b), 1.0 without either: the
    panels' share of the graph once by()'s own title(), subtitle(),
    note() and caption() lines are set aside (``_DASH_BY_SHRINK_SHARES``;
    the note counts unless ``note("")``).  A no-word does not undo a
    yes-word (measured: shrink noshrink shrinks).  Never raises."""
    try:
        text = by_raw if isinstance(by_raw, str) else str(by_raw or "")
    except Exception:  # noqa: BLE001
        return 1.0
    _, comma, subs = text.partition(",")
    if not comma:
        return 1.0
    shrink, lines = False, {}
    for tok in _dash_by_tokens(subs.strip()):
        row = _dash_by_word(tok)[0]
        if row in ("shrink", "overallshrink") and "(" not in tok:
            shrink = True
        key = _dash_by_text_key(tok)
        if key in ("title", "subtitle", "note", "caption"):
            arg = tok[tok.index("(") + 1:]
            arg = arg[:-1] if arg.endswith(")") else arg
            body, _sub = _parse_textbox_opt(arg)
            lines[key] = sum(len([x for x in ln.split("\n") if x])
                             for ln in _textbox_lines(body) if ln)
            if key == "note" and not str(body).strip() and _sub:
                lines[key] = 1     # note(, size()) restyles the default
    if not shrink:
        return 1.0
    lines.setdefault("note", 1)
    sh = _DASH_BY_SHRINK_SHARES
    f = sh["base"]
    for k in ("title", "subtitle", "note", "caption"):
        n = lines.get(k, 0)
        if n:
            f -= sh[k] + (n - 1) * sh["line"]
    return max(0.05, f)


#: A positive number as by(, scale()) takes it (WP-41 BY-2).
_DASH_BY_SCALE_NUM = (r"\s*([+]?(?:[0-9]+\.?[0-9]*|\.[0-9]+)"
                      r"(?:[eE][+-]?[0-9]{1,4})?)\s*")


def _dash_by_scale_mult(by_raw):
    """by(, scale(#)) of *by_raw* as a multiplier (WP-41 BY-2), 1.0
    without one.  twoway applies by()'s own scale() to the whole by()
    graph -- panels, panel labels, by()'s texts, the outer axis titles
    and the keys (by_scale_range_truth.json S03-S06: every text and the
    marker 1.5 x) -- and ignores a scale() written beside by()
    (``_dash_scale_factor``).  The last copy is read, case-sensitive
    through ``_dash_by_word``; a value that is not a finite number above 0
    is 1.0 (``_dash_parse_by`` names it).  Never raises."""
    try:
        text = by_raw if isinstance(by_raw, str) else str(by_raw or "")
    except Exception:  # noqa: BLE001 -- any object at all
        return 1.0
    _, comma, subs = text.partition(",")
    if not comma:
        return 1.0
    raw = None
    for tok in _dash_by_tokens(subs.strip()):
        row, _typed, paren, arg = _dash_by_word(tok)
        if row == "scale" and paren:
            raw = arg
    v = _dash_by_scale_arg(raw) if raw is not None else None
    return 1.0 if v is None else v


def _dash_by_scale_arg(arg):
    """The number by(, scale(*arg*)) draws at (WP-41 BY-2): a finite
    number above 0, else None (a word, 0, a negative number or an empty
    argument, named by ``_dash_parse_by`` and drawn at 1).  Never
    raises."""
    m = re.fullmatch(_DASH_BY_SCALE_NUM, str(arg or "")[:64])
    if not m:
        return None
    try:
        v = float(m.group(1))
    except (ValueError, OverflowError):
        return None
    return v if math.isfinite(v) and v > 0 else None


def _dash_by_spacing(fig0, opts):
    """``(row_px, col_px)`` between by() panels (WP-30 P1.15b, TR-48.11):
    each panel's adjacent margins in Stata units (1% of min(W, H)), as
    bygraph_g.class places every view inside ``indiv_margin`` -- the
    scheme's ``margin by_indiv`` (``fig._dash_by_indiv``, stamped by
    ``SchemeParser.apply_to_figure``), zero under ``compact`` or
    ``style(compact)``, ``imargin()`` applied over it through section
    47's ``_dash_margin_sides`` (a text twoway cannot read is zero, as it
    draws it; a side below 0 is 0).  Not scaled by ``iscale()``
    (by_grid_truth.json).  Integers out; never raises."""
    opts = opts or {}
    start = getattr(fig0, "_dash_by_indiv", None) or (1.2, 1.2, 1.2, 1.2)
    try:
        sides = [float(v) for v in start]
    except (TypeError, ValueError):
        sides = [1.2] * 4
    if opts.get("compact") or str(opts.get("style") or "") == "compact":
        sides = [0.0] * 4
    if opts.get("imargin"):
        sides, _noted = _dash_margin_sides(opts["imargin"], sides)
    unit = OptionTranslator.PT_PER_RS * OptionTranslator.PX_PER_PT
    out = []
    for a, b in ((sides[2], sides[3]), (sides[0], sides[1])):
        vals = []
        for v in (a, b):
            if isinstance(v, tuple):     # ("pt", n)
                v = float(v[1]) / OptionTranslator.PT_PER_RS
            v = float(v)
            vals.append(v if math.isfinite(v) and v > 0 else 0.0)
        out.append(int(round(min(1e4, vals[0] + vals[1]) * unit)))
    return tuple(out)


#: The size properties ``_dash_by_scale_panel`` multiplies (WP-30 P1.15b,
#: TR-48.12, D-48f), by model kind.
_DASH_BY_SCALED_PROPS = {
    "glyph": ("size", "line_width", "text_font_size", "border_line_width"),
    "text": ("text_font_size", "x_offset", "y_offset", "border_line_width"),
    "line": ("line_width",),
    "head": ("size", "line_width"),
    "axis": ("major_label_text_font_size", "axis_label_text_font_size",
             "axis_line_width", "major_tick_line_width",
             "minor_tick_line_width", "major_tick_in", "major_tick_out",
             "minor_tick_in", "minor_tick_out", "major_label_standoff",
             "axis_label_standoff"),
    "grid": ("grid_line_width",),
}


def _dash_by_scale_value(v, m):
    """*v* times *m* when it is a finite number, a ``{"value": n}`` spec or
    an ``"<n>px"``/``"<n>pt"`` string; else *v* unchanged (a field)."""
    if isinstance(v, bool):
        return v
    if isinstance(v, (int, float)):
        x = float(v) * m
        return x if math.isfinite(x) else v
    if isinstance(v, str):
        mm = re.fullmatch(r"\s*([0-9]*\.?[0-9]+(?:[eE][+-]?[0-9]{1,3})?)"
                          r"\s*(px|pt)\s*", v)
        if mm:
            x = float(mm.group(1)) * m
            if math.isfinite(x):
                return "%g%s" % (x, mm.group(2))
        return v
    if isinstance(v, dict) and "value" in v and len(v) == 1:
        return {"value": _dash_by_scale_value(v["value"], m)}
    return v


def _dash_by_scale_panel(fig, m):
    """Multiply every numeric size a by() panel draws by *m*, once (WP-30
    P1.15b, TR-48.12, D-48f): its glyphs' marker sizes, line widths and
    text, its labels, titles (the panel label too), spans, arrows and
    their heads, axes and grids (``_DASH_BY_SCALED_PROPS``).  A field
    spec (a per-row size or offset), the legend and a colour bar are
    left alone (residual: per-row label offsets are not scaled).  Stamps
    ``fig._dash_by_scaled``, so a panel laid out twice is scaled once.
    Returns *fig*."""
    if fig is None or getattr(fig, "_dash_by_scaled", None) is not None:
        return fig
    try:
        m = float(m)
    except (TypeError, ValueError):
        return fig
    if not math.isfinite(m) or m == 1.0:
        fig._dash_by_scaled = 1.0 if math.isfinite(m) else None
        return fig
    done = set()

    def scale(model, kind):
        if model is None or id(model) in done:
            return
        done.add(id(model))
        for prop in _DASH_BY_SCALED_PROPS[kind]:
            if prop not in model.properties():
                continue
            old = getattr(model, prop)
            new = _dash_by_scale_value(old, m)
            if new is old:
                continue
            try:
                setattr(model, prop, new)
            except (ValueError, TypeError):
                try:
                    setattr(model, prop, int(round(new)))
                except (ValueError, TypeError, OverflowError):
                    pass

    for r in list(getattr(fig, "renderers", []) or []):
        for slot in ("glyph", "selection_glyph", "nonselection_glyph",
                     "hover_glyph", "muted_glyph"):
            g = getattr(r, slot, None)
            if g is not None and not isinstance(g, str):
                scale(g, "glyph")
    models = []
    for place in ("center", "above", "below", "left", "right"):
        models += list(getattr(fig, place, []) or [])
    if getattr(fig, "title", None) is not None:
        models.append(fig.title)
    for a in models:
        kind = type(a).__name__
        if kind in ("LabelSet", "Label", "Title"):
            scale(a, "text")
        elif kind in ("Span",):
            scale(a, "line")
        elif kind == "Arrow":
            scale(a, "line")
            for end in ("start", "end"):
                scale(getattr(a, end, None), "head")
    for ax in list(fig.xaxis) + list(fig.yaxis) + \
            [a for a in models if type(a).__name__.endswith("Axis")]:
        scale(ax, "axis")
    for gr in list(fig.xgrid) + list(fig.ygrid):
        scale(gr, "grid")
    fig._dash_by_scaled = m
    return fig

def _dash_by_text_key(tok):
    """The by() text sub-option (``"title"``, ``"subtitle"``, ``"note"``,
    ``"caption"`` or, WP-41 BY-12, an edge title ``"l1title"`` ..
    ``"b2title"``) one token of :func:`_dash_by_tokens` is, or None.

    Only a token with an argument -- ``ti("X")``, ``note(, size(large))``
    -- counts, and its name is compared case-sensitively with
    ``_DASH_BY_TEXT_SPELLINGS`` (WP-30 P1.15a): twoway refuses
    ``TITLE("X")`` (probe a12) and ``no("X")`` (a15).
    """
    tok = str(tok)
    if "(" not in tok or not tok.endswith(")"):
        return None
    name = tok.split("(", 1)[0].strip()
    for key, spellings in _DASH_BY_TEXT_SPELLINGS.items():
        if name in spellings:
            return key
    return None


def _dash_by_text_options(by_raw):
    """``{"title", "subtitle", "note", "caption", "l1title", ..,
    "b2title"}``: each by() text sub-option's merged raw value, ``""``
    when it is not given (WP-30 P1.15a; the edge titles WP-41 BY-12).

    Repeated forms merge as twoway's text boxes do (probes a07, a08, a13):
    the text is the last occurrence's whose text part is given -- a typed
    ``""`` counts -- and every occurrence's sub-options apply, in order.
    ``by(foreign, note("A") note(, size(large)))`` is ``'"A", size(large)'``.
    Only the text after the first comma of *by_raw* is read, through the
    quote-aware :func:`_dash_by_tokens`.  One pass; never raises.
    """
    out = {k: "" for k in _DASH_BY_TEXT_SPELLINGS}
    try:
        text = by_raw if isinstance(by_raw, str) else str(by_raw or "")
    except Exception:  # noqa: BLE001 -- any object at all
        return out
    _, comma, subs = text.partition(",")
    if not comma:
        return out
    texts = {k: None for k in out}
    opts = {k: [] for k in out}
    for tok in _dash_by_tokens(subs.strip()):
        key = _dash_by_text_key(tok)
        if key is None:
            continue
        arg = tok[tok.index("(") + 1:-1]
        cut = _textbox_split_point(arg)
        part = arg if cut < 0 else arg[:cut]
        sub = "" if cut < 0 else arg[cut + 1:].strip()
        if _textbox_has_text(part):
            texts[key] = part.strip()
        if sub:
            opts[key].append(sub)
    for k in out:
        t = texts[k] or ""
        o = " ".join(opts[k])
        out[k] = t + (", " + o if o else "")
    return out


def _dash_by_note_list(by_vars, var_labels):
    """The list twoway's default by() note names, ``Graphs by <list>``
    (bygraph_g.class SetByList :1421-1456; WP-30 P1.15a).

    One variable is its label, else its name (``_dash_var_label``); two
    are ``"A and B"``; three or more start with the first variable's NAME
    -- a quirk of SetByList, measured (probe p20: ``Graphs by foreign,
    Repair record 1978, and Headroom (in.)``) -- then ``", B"`` for each
    middle one and ``", and C"`` for the last.  Labels are used as given
    (a label of blanks is kept, probe NB).
    """
    vs = list(by_vars or [])
    if not vs:
        return ""
    lab = [_dash_var_label(var_labels, v) for v in vs]
    if len(vs) == 1:
        return lab[0]
    if len(vs) == 2:
        return "%s and %s" % (lab[0], lab[1])
    return (str(vs[0]) + "".join(", " + t for t in lab[1:-1])
            + ", and " + lab[-1])


def _dash_by_range_notes(graph):
    """``[(key, text)]``: one note per rescaled axis of a by() graph whose
    range() is not applied (WP-29 P0.2, SD-8).

    twoway draws a rescaled axis of each panel over that panel's own data
    and does not apply ``yscale(range())`` there (axis(2)'s included);
    dash does the same and says so once, decided from the spec alone so
    both modes raise it at build time (the saved renderer's figure loop,
    ``ServerAppBuilder._plan_graph_notes``).  The key is ``("by-range",
    graph name, letter)``.
    """
    if not isinstance(graph, dict):
        return []
    go = graph.get("graph_options")
    if not isinstance(go, dict):
        return []
    by = str(go.get("by") or "").strip()
    if not by or not _dash_parse_by(by, warn=False)[0]:
        return []
    name = str(go.get("name", "") or "")
    out = []
    resc = _dash_by_rescale(by)
    for d in ("y", "x"):
        if d not in resc:
            continue
        if any(_DASH_SCALE_RANGE_RE.search(str(go.get(k) or ""))
               for k in (d + "scale", d + "scale2")):
            out.append((("by-range", name, d),
                        "dash: graph '%s': by(, %srescale) draws each panel "
                        "on its own %s scale; %sscale(range()) is not "
                        "applied, as in twoway."
                        % (_dash_display(name), d, d, d)))
    return out


def _dash_by_subtitle_format(by_raw):
    """by(, subtitleformat())'s format for the panel labels (WP-31 D10,
    bygraph_g.class parse_settings :390-407): ``"var"``, a numeric format
    as typed, or ``""`` -- not given, or text Stata's ``confirm numeric
    format`` refuses, which twoway ignores in silence (measured:
    ``subtitleformat(size(large) color(red))`` draws the plain labels;
    by_remainder_truth.json ``stf_*``)."""
    try:
        text = by_raw if isinstance(by_raw, str) else str(by_raw or "")
    except Exception:  # noqa: BLE001
        return ""
    _, comma, subs = text.partition(",")
    if not comma:
        return ""
    fmt = ""
    for tok in _dash_by_tokens(subs.strip()):
        row, _typed, paren, arg = _dash_by_word(tok)
        if row == "subtitleformat" and paren:
            fmt = arg.strip()
    if fmt == "var":
        return fmt
    if not fmt or len(fmt) > 64 or _dash_fmt_parse(fmt) is None:
        return ""
    return fmt


def _dash_facet_label(by_vars, key, value_label_names=None, value_labels=None,
                      date_vars=None, numeric_formats=None,
                      date_formatter=None, formats=None,
                      subtitle_format="", dp=None):
    """The title of one by() panel, the same in both render modes.

    twoway's rule, measured 23sep2026 from its SVG export: the value's label
    when it has one, else the value as Stata writes a number into a macro
    -- 3, .25, 1234567 -- whatever the variable's display format (%9.2f and
    %12.0fc change nothing), and a string as it is.  The labels of several
    by() variables are joined ", " (``local sep ", "``) and a missing value
    -- a numeric missing or a string ``""`` -- reads "(missing)"
    (bygraph_g.class RunGraph :427-497; WP-30 P1.15a: dash joined " / " and
    wrote "Missing").  A date variable's panel is titled with its date,
    through *date_formatter* (twoway writes the number, 14610; A53).

    This wrote an unlabelled value as Python writes a float -- "3.0", and
    "Domestic / 3.0" where dash.sthlp's example says "Domestic / 3" -- in
    both modes, and read a %f display format BEFORE the value labels, so a
    labelled variable with a %9.2f format lost its labels on the saved page
    ("3.00" for "Three") while the served app, which passed no formats,
    kept them.

    Args:
        by_vars:            The by() variables, in order.
        key:                The group key -- scalar for one variable, tuple
                            for several.
        value_label_names:  ``{varname: labelset}``.
        value_labels:       ``{labelset: {code: text}}``, or keyed by the
                            variable's own name, as real jsonio writes it.
        date_vars:          ``{varname: kind}`` for date variables.
        numeric_formats:    Accepted from callers and not read: a display
                            format plays no part in a panel title.
        date_formatter:     ``f(value, fmt) -> str``, given the date
                            variable's full format (WP-28 S12).
        formats:            ``{varname: fmt}``, every display format; a
                            date variable's panel is titled in its own
                            picture (``2000m1``, ``02jan2000``).

        subtitle_format:    by(, subtitleformat())'s format
                            (:func:`_dash_by_subtitle_format`, WP-31 D10):
                            an unlabelled number is written in it, or in
                            the variable's own format for ``"var"``; a
                            labelled value keeps its label (measured).

    Returns:
        A display string like ``"Domestic"`` or ``"Domestic, 3"``.
    """
    value_label_names = value_label_names or {}
    value_labels = value_labels or {}
    date_vars = date_vars or {}
    keys = [key] if len(by_vars) == 1 else list(key)
    parts = []
    for var, val in zip(by_vars, keys):
        if _dash_by_value_missing(val) or (
                not isinstance(val, str) and GlyphMapper._mlabel_missing(val)):
            parts.append("(missing)")
            continue
        if isinstance(val, str):
            if (len(val) == 2 and val[0] == "."
                    and val[1] in _DASH_CODE_LETTERS):
                # An extended missing value's panel (WP-31 G1,
                # _dash_by_groups): its value label, else .a.
                parts.append(_dash_code_text(val[1], _dash_value_labels_for(
                    var, value_labels, value_label_names)))
                continue
            parts.append(_dash_quoted_lines(val))
            continue
        _kind = date_vars.get(var)
        if _kind and date_formatter is not None and subtitle_format == "var":
            # subtitleformat(var): the variable's own format, its dates
            # (by_label_truth.json D02).
            parts.append(date_formatter(
                val, _dash_date_fmt((formats or {}).get(var), _kind)))
            continue
        if _kind:
            # WP-41 BY-16: twoway writes a date's Stata number (D01:
            # 14610), from its Stata units; a value label still wins.  A
            # number is already in them (as _dash_stata_date_text reads
            # one); a datetime is converted through its milliseconds, as
            # _dash_stata_date_text reads one (pd.Timestamp's nanoseconds
            # overflow past 2262, and 31dec9999 read "(missing)").
            if not isinstance(val, (int, float, np.integer, np.floating)):
                _ms = _dash_json_value(val)
                val = (float(_dash_stata_value_of(_ms, _kind))
                       if isinstance(_ms, float) else float("nan"))
            if not math.isfinite(float(val)):
                parts.append("(missing)")
                continue
            val = float(val)
        vlabels = _dash_value_labels_for(var, value_labels, value_label_names)
        if subtitle_format:
            _txt = GlyphMapper._mlabel_value_text(val, vlabels)
            _plain = GlyphMapper._mlabel_value_text(val, {})
            if _txt == _plain:
                # No label: written in the format, as twoway's
                # `: display fmt value' (RunGraph :437-446).
                _f = ((formats or {}).get(var) or "%9.0g"
                      if subtitle_format == "var" else subtitle_format)
                parts.append(_dash_fmt(val, _f, strip=True,
                                       dp=_dash_page_dp(dp)))
                continue
        # Raw: a facet label titles a panel (fig.title.text), which Bokeh
        # draws on the canvas, and it also feeds a per-facet KPI card that
        # html-escapes it again -- so escaping here showed the entities on
        # the panel and double-escaped the card.
        parts.append(_dash_quoted_lines(
            GlyphMapper._mlabel_value_text(val, vlabels)))
    return ", ".join(parts)


def _dash_quoted_lines(text):
    """*text* drawn one line per quoted part, as twoway draws a by() panel
    label (WP-41 BY-16; by_label_truth.json Q01: the value label
    ``"Dom" "estic"`` is two lines, Dom over estic): when its stripped
    text is two or more Stata strings -- ``"..."`` or compound-quoted
    ``\x60"..."'`` -- separated by blanks and nothing else, the parts
    unquoted and joined by newlines; otherwise *text* unchanged.  One
    linear scan; never raises."""
    t = "" if text is None else str(text)
    s = t.strip()
    parts, i, n = [], 0, len(s)
    while i < n:
        if s.startswith('\x60"', i):
            # A compound quote nests: count \x60" opens against "' closes.
            depth, j = 1, i + 2
            while j < n and depth:
                if s.startswith('\x60"', j):
                    depth += 1
                    j += 2
                elif s.startswith('"\'', j):
                    depth -= 1
                    j += 2
                else:
                    j += 1
            if depth:
                return t
            parts.append(s[i + 2:j - 2])
        elif s[i] == '"':
            j = s.find('"', i + 1)
            if j < 0:
                return t
            parts.append(s[i + 1:j])
            j += 1
        else:
            return t
        if j < n and s[j] not in " \t":
            return t
        while j < n and s[j] in " \t":
            j += 1
        i = j
    return "\n".join(parts) if len(parts) >= 2 else t


def _dash_stata_date_text(value, fmt):
    """One date as Stata's ``display`` writes it under the variable's full
    date format *fmt* (``%td``, ``%tm``, ``%tdCCYY-NN-DD``...), "." when
    it is missing, from either form a date reaches a caller in: a Stata
    number in the format's own unit, or a datetime (the loaders hold a
    date variable as one, in both modes).  GAPS2 E3 (WP-28 S12): it wrote
    one fixed picture per kind -- ``02 Jan 2001``, ``Jan 2000`` for a %tm
    -- where Stata writes ``02jan2001`` and ``2000m1``.  A bare kind
    (``"td"``) is read as its default format.
    """
    fmt = str(fmt or "")
    if fmt and not fmt.startswith("%"):
        fmt = "%" + fmt
    kind = _stata_date_kind(fmt) or "td"
    if value is None:
        return "."
    if isinstance(value, bool):
        return str(value)
    if GlyphMapper._mlabel_missing(value):
        return "."
    if isinstance(value, (int, float, np.integer, np.floating)):
        return _dash_fmt_text(float(value), fmt)  # no dp: a %t picture
    ms = _dash_json_value(value)
    if not isinstance(ms, float):
        return str(value)
    return _dash_fmt_text(_dash_stata_value_of(ms, kind), fmt)  # no dp: a %t picture


# ===========================================================================
# One implementation, two callers
#
# Everything below runs in BOTH render modes: the saved renderer calls it
# directly and the generated server app copies it in by name (see
# ServerAppBuilder._glyph_layer_lines).  Each helper closes a place where
# test/test_mode_parity.py measured the two renderers drawing the same
# spec two ways.
# ===========================================================================

# ===========================================================================
# The Stata display-format writer (WP-28 S04, E1/E3/G6 foundation).
#
# One writer, in Python, with a byte-identical JavaScript twin
# (_DASH_FMT_JS, further below).  Both reproduce Stata's `display %fmt
# (value)' text -- decimal places, comma grouping, the width-driven
# fixed/scientific choice, and every %t picture -- against
# test/fixtures/format_truth.json, which holds what a real `display'
# actually printed for about 1,500 numeric rows and 220 date rows.  The
# rule below is the plan's hypothesis, corrected wherever a measured row
# disagreed with it (each such correction is called out where it applies).
# %x, %H and %L (hexadecimal and IEEE dumps) are refused: a variable
# carrying one is drawn in %9.0g with one note (BR-04.5).
# ===========================================================================

_DASH_FMT_NUM_RE = re.compile(
    r"^%(-)?(0)?(\d{1,4})([.,])(\d{1,4})(f|g|e)(c)?$")
_DASH_FMT_DATE_RE = re.compile(r"^%(-)?t([cCdhmqwy])(.*)$")
_DASH_FMT_X_RE = re.compile(r"^%-?\d*x$")
#: %tb<cal>[:picture], a business-calendar format (WP-31 G7): written as
#: the calendar's %td date with the picture (help datetime business).
_DASH_FMT_TB_RE = re.compile(r"^%tb([A-Za-z_][A-Za-z0-9_]{0,31})(?::(.*))?$")
_DASH_FMT_H_RE = re.compile(r"^%-?\d*[HL]$")


def _dash_fmt_parse(fmt):
    """Split a Stata display format into its pieces, or ``None``.

    Numeric grammar: ``%[-][0]w[.,]d(f|g|e)[c]``, ``1 <= w <= 2045``,
    ``d < w``, each digit string at most four characters (WP-20's bounds,
    kept exactly).  Date grammar: ``%[-]t[cCdhmqwy]`` then an optional
    custom picture.  ``%[-]NNx`` is the hexadecimal dump, ``%[-]NN[HL]``
    the IEEE byte dump -- both refused, never written (DISCOVERY Q6).

    Args:
        fmt: A Stata format string, as ``st_varformat`` or a user's
             ``fmt()`` supplies it.

    Returns:
        A dict with keys ``kind`` (``"f"|"g"|"e"|"t"|"x"|"H"``), ``width``,
        ``dec``, ``left``, ``zero``, ``group``, ``comma_dec``, ``tkind``,
        ``picture``; or ``None`` when *fmt* is not a format this module
        recognises at all (still written, in %9.0g, by the caller).
    """
    if not fmt or not isinstance(fmt, str):
        return None
    fmt = fmt.strip()
    if not fmt.isascii() or len(fmt) > 60:
        return None
    m = _DASH_FMT_NUM_RE.fullmatch(fmt)
    if m:
        if len(m.group(3)) > 4 or len(m.group(5)) > 4:
            return None
        width, dec = int(m.group(3)), int(m.group(5))
        if not 1 <= width <= 2045 or dec >= width:
            return None
        return {"kind": m.group(6), "width": width, "dec": dec,
                "left": bool(m.group(1)), "zero": bool(m.group(2)),
                "group": bool(m.group(7)), "comma_dec": m.group(4) == ",",
                "tkind": None, "picture": None}
    # %d is %td's old name (help datetime; WP-31 G7, measured: display %d
    # 20000 is 04oct2014, %dCCYY-NN-DD 2014-10-04).
    m = _DASH_FMT_DATE_RE.fullmatch(re.sub(r"^%(-?)d", r"%\1td", fmt,
                                           count=1))
    if m:
        return {"kind": "t", "width": None, "dec": None,
                "left": bool(m.group(1)), "zero": False, "group": False,
                "comma_dec": False, "tkind": m.group(2),
                "picture": m.group(3)}
    m = _DASH_FMT_TB_RE.fullmatch(fmt)
    if m:
        return {"kind": "t", "width": None, "dec": None, "left": False,
                "zero": False, "group": False, "comma_dec": False,
                "tkind": "b", "picture": m.group(2) or "",
                "bcal": m.group(1)}
    if _DASH_FMT_X_RE.fullmatch(fmt):
        return {"kind": "x", "width": None, "dec": None, "left": False,
                "zero": False, "group": False, "comma_dec": False,
                "tkind": None, "picture": None}
    if _DASH_FMT_H_RE.fullmatch(fmt):
        return {"kind": "H", "width": None, "dec": None, "left": False,
                "zero": False, "group": False, "comma_dec": False,
                "tkind": None, "picture": None}
    return None


def _dash_fmt_kind(fmt):
    """``"f"|"g"|"e"|"t"|"x"|"H"``, or ``None`` for a format this module
    does not recognise at all."""
    parsed = _dash_fmt_parse(fmt)
    return parsed["kind"] if parsed else None


def _dash_fmt_refusal(fmt):
    """Why the dashboard cannot write *fmt*, or ``None`` when it can
    (kinds f, g, e, t).  The text names the format so a caller can echo
    it (dash.ado's TR-04.7, and BR-04.5's one-per-variable note)."""
    kind = _dash_fmt_kind(fmt)
    if kind == "x":
        return f"{fmt} is a hexadecimal display format the dashboard cannot write"
    if kind == "H":
        return (f"{fmt} is an IEEE byte-dump display format the dashboard "
                f"cannot write")
    if kind is None:
        return f"{fmt} is not a display format dash writes"
    return None


#: A double's magnitude needs at most about 309 integer digits plus up to
#: 2044 decimals (WP-20's bound); the default Decimal context (28 digits)
#: raises InvalidOperation quantizing that, so each rounding builds a
#: Context(prec=2400) of its own (built in place, not a module constant:
#: the served app copies constants by repr, which a Context has not got).


def _dash_stata_round(a, ndigits, half_even=True):
    """*a* (a non-negative float) rounded to *ndigits* decimal places the
    way Stata's ``display`` rounds.

    ``f`` and ``g``'s own auto (``%w.0g``) mode round half TO EVEN, on
    the value's exact double bits (measured: ``%9.0f`` of both 20.5 and
    -0.5 rounds to the even neighbour, 20 and 0, not 21 and -1; ``%9.0g``
    of 1234567.5 is 1234568, also even) -- the same rule Python's own
    ``round()`` uses.  ``g`` with an EXPLICIT decimal count rounds half
    AWAY FROM ZERO instead (measured: ``%9.2g``/``%12,2gc`` of 20.5 is
    21, the odd neighbour); a caller in that one case passes
    ``half_even=False``.  *a* may already be a :class:`~decimal.Decimal`
    (an exact-arithmetic intermediate, e.g. a scientific mantissa
    computed by :func:`_dash_sci_text`) -- it is used as is, never
    round-tripped through ``float()`` and back.  Returns a
    :class:`~decimal.Decimal`.
    """
    d = a if isinstance(a, Decimal) else Decimal(float(a))
    if ndigits < 0:
        ndigits = 0
    quant = Decimal(1).scaleb(-ndigits)
    rounding = ROUND_HALF_EVEN if half_even else ROUND_HALF_UP
    return d.quantize(quant, rounding=rounding,
                       context=Context(prec=2400))


def _dash_int_digit_count(a):
    """The digit count of ``floor(a)`` for ``a >= 1``, else ``0``
    (``a`` is a non-negative float; ``a == 0`` also gives ``0``)."""
    if a < 1:
        return 0
    return len(str(int(math.floor(a))))


def _dash_group_thousands(digits):
    """*digits* (a plain digit string, no sign) with ',' inserted every
    three digits from the right."""
    out = []
    for i, c in enumerate(reversed(digits)):
        if i and i % 3 == 0:
            out.append(",")
        out.append(c)
    return "".join(reversed(out))


def _dash_decimal_text(value, decimals):
    """*value* (a non-negative :class:`~decimal.Decimal`, already rounded
    to *decimals* places) as plain fixed text, always showing exactly
    *decimals* digits after the point (``decimals == 0`` omits the
    point)."""
    s = format(value, "f")
    if "." in s:
        intpart, frac = s.split(".", 1)
    else:
        intpart, frac = s, ""
    frac = (frac + "0" * decimals)[:decimals]
    return intpart + ("." + frac if decimals else "")


def _dash_swap_decimal_comma(text):
    """Swap ``.`` and ``,`` in *text* in one pass (the European comma
    decimal), never as two separate ``str.replace`` calls (which would
    swap twice)."""
    return text.translate(str.maketrans(".,", ",."))


def _dash_sci_decimals(width, exp_digits, dec, sig_digits=False):
    """How many mantissa decimals a scientific rendering gets at *width*,
    given the exponent needs *exp_digits* characters (2 or 3) and the
    format's own requested decimal count *dec* (0 means "Stata chooses").

    Measured (report W; ``format_truth.json``): the baseline is
    ``width - 7`` (two-digit exponent) or ``width - 8`` (three-digit), with
    a floor of 1 (two-digit) or 0 (three-digit) so a very narrow width
    never goes negative (``%1.0f`` of 1e7 is ``1.0e+07``, one decimal, not
    minus five).  An explicit *dec* caps it further -- but ``e`` and ``g``
    read *dec* differently: ``%9.3e``'s ``3`` is mantissa DECIMAL PLACES
    (``sig_digits=False``, cap is ``dec`` itself: width 10 gives all
    three, ``6.165e+03``), while ``%12,2gc``'s ``2`` is SIGNIFICANT
    DIGITS, one of which is the mantissa's leading integer digit, so the
    cap is ``dec - 1`` (``sig_digits=True``: 5.23e+10 becomes ``5,2e+10``,
    one decimal, not two).

    The floor holds with an explicit *dec* too, and ``g`` reads a digit
    count below 2 as 2 (WP-30 P1.5.7; measured 03oct2026 over
    ``format_truth.json``'s ``narrow_formats``): ``%6.2e`` of 12345 is
    ``1.2e+04``, ``%3.1f`` of 1234567 is ``1.2e+06`` and ``%6.4g`` of
    .0001 is ``1.0e-04`` -- one decimal at a width whose baseline is
    below it, never the bare ``1.e+04``.
    """
    base = width - (7 if exp_digits == 2 else 8)
    floor = 1 if exp_digits == 2 else 0
    if dec == 0:
        return max(base, floor)
    cap = (max(dec, 2) - 1) if sig_digits else dec
    return max(min(cap, base), floor)


def _dash_fmt_number(parsed, value):
    """*value* (a finite float) written the way Stata's ``display``
    writes it under *parsed* (a numeric ``_dash_fmt_parse`` result).  No
    ``str(x)``, no ``format(x, "g")``, no locale: every digit is placed by
    hand (TR-04.2)."""
    width, dec, kind, comma = (parsed["width"], parsed["dec"],
                                parsed["kind"], parsed["comma_dec"])
    group, zero, left = parsed["group"], parsed["zero"], parsed["left"]
    sign = "-" if value < 0 else ""
    a = abs(value)

    signlen = len(sign)
    if kind == "e":
        exp = math.floor(math.log10(a)) if a else 0
        exp_digits = 3 if abs(exp) >= 100 else 2
        decimals = _dash_sci_decimals(width, exp_digits, dec)
        text = _dash_sci_text(a, exp, decimals)
    elif kind == "f":
        text = _dash_f_text(a, dec, width, group, signlen)
    else:  # g
        text = _dash_g_text(a, dec, width, group, signlen)

    if comma:
        text = _dash_swap_decimal_comma(text)

    body = sign + text
    # A scientific fallback pads to a floor of 8, not the (possibly much
    # narrower) requested width -- measured: %1.0f of 123456789 is
    # " 1.2e+08" (one leading space, width 8), not the unpadded 7
    # characters width 1 alone would give.
    pad_width = max(width, 8) if "e" in text else width
    if kind == "g" and dec > 0 and "e" not in text:
        # WP-30 P1.5.7: an explicit-digit g's fixed text sits in at least
        # four columns (%3.1g of .123 is " .12", %3.2g of 0 is "   0").
        pad_width = max(width, 4)
    if left:
        # Left-aligned text is padded to the width only, never to the
        # scientific floor (measured: %-6.4g of .00001 is "1.0e-05").
        pad_width = max(width, 4) if kind == "g" and dec > 0 else width
    if zero and kind == "f" and "e" not in text and len(body) < width:
        # The 0 flag is honoured only with f (format.sthlp:84-88): zeros
        # are inserted between the sign and the digits, never before it,
        # and never when the value fell back to scientific (measured:
        # %09.2f of 1e7 is " 1.00e+07", space-padded, not zero-padded).
        body = sign + "0" * (width - len(body)) + text
        return body if left else body.rjust(width)
    return body.ljust(pad_width) if left else body.rjust(pad_width)


def _dash_sci_text(a, exp, decimals, half_even=False):
    """The mantissa+exponent text for *a* (positive) at *exp* (its base-10
    exponent) and *decimals* mantissa decimals, e.g. ``"1.23e+06"``.  The
    decimal point is always shown, even at zero decimals (``"1.e+100"``,
    measured).  *half_even* is ``False`` (Stata's ``e``/``g`` round ties
    away from zero) unless the caller is ``f``'s scientific fallback,
    which keeps ``f``'s own half-to-even rule.

    The mantissa is computed in exact decimal arithmetic
    (``Decimal(a) / Decimal(10) ** exp``), never float division: ``20.5
    / 10.0`` is not exactly 2.05 in binary (it rounds down to
    2.0499999999999998), and rounding THAT to one decimal gives 2.0,
    not Stata's 2.1 (measured: %3.0g of 20.5 is 2.1e+01)."""
    mant = (Decimal(a) / (Decimal(10) ** exp)).quantize(
        Decimal(1).scaleb(-40), context=Context(prec=2400))
    r = _dash_stata_round(mant, decimals, half_even=half_even)
    if r >= 10:
        r = r / 10
        exp += 1
    mant_text = _dash_decimal_text(r, decimals)
    if decimals == 0 and "." not in mant_text:
        mant_text += "."
    exp_digits = 3 if abs(exp) >= 100 else 2
    return f"{mant_text}e{'+' if exp >= 0 else '-'}{abs(exp):0{exp_digits}d}"


def _dash_f_sci_fallback(a, width, dec):
    """The scientific text an ``f``-kind value falls back to when even
    its plain digits do not fit *width*: the same width-driven decimals
    rule as ``e``'s own (``_dash_sci_decimals`` with ``sig_digits=False``,
    since ``f``'s *dec* is decimal PLACES, not significant digits) --
    measured: ``%1.0f`` of 123456789 is ``1.2e+08`` (dec 0, width-driven,
    one decimal); ``%12.2fc`` of 52313712223 is ``5.23e+10`` (dec 2, its
    own two decimals, not the width-driven five).  Its mantissa rounds
    ties away from zero, as ``e`` does (WP-30 P1.5.7, measured:
    ``%10.4f`` of -12345 is ``-1.235e+04``)."""
    exp = math.floor(math.log10(a))
    exp_digits = 3 if abs(exp) >= 100 else 2
    decimals = _dash_sci_decimals(width, exp_digits, dec)
    return _dash_sci_text(a, exp, decimals, half_even=False)


def _dash_f_text(a, dec, width, group, signlen=0):
    """The ``f``/``fc`` text for non-negative *a* (TR-04.2): exactly *dec*
    decimals, comma-grouped when *group* and it fits, plain when it does
    not, scientific when even the plain digits overflow.  ``f`` never
    strips trailing zeros (unlike ``g``).  *signlen* (0 or 1) is added to
    every "does it fit" check: a negative value's sign counts against the
    width too (measured: %1.0f of -12345678 is -1.2e+07, scientific,
    while the same 8 digits positive print in full)."""
    r = _dash_stata_round(a, dec)
    plain = _dash_decimal_text(r, dec)
    if group:
        intpart, _, frac = plain.partition(".")
        grouped = _dash_group_thousands(intpart) + (("." + frac) if frac else "")
        if len(grouped) + signlen <= width:
            return grouped
    # Measured: `%9.0fc' of -1234567.891 drops the commas rather than
    # overflowing to scientific (report B); the effective cap widens to
    # accommodate a narrow requested width (measured floor 8: %1.0f and
    # %2.0f of an 8-digit integer still print it in full).
    if len(plain) + signlen <= max(width, 8):
        return plain
    return _dash_f_sci_fallback(a, width, dec)


def _dash_g_text_explicit(a, dec, width, group, signlen=0):
    """``_dash_g_text``'s explicit-digit path (``dec > 0``; WP-30
    P1.5.7): the rule its docstring states, measured over
    ``format_truth.json``'s ``narrow_formats``.  Rounds the exact binary
    value half away from zero (``%10.4g`` of 0.000012345 is
    ``.00001234``)."""
    if a == 0:
        return "0"
    exp = math.floor(math.log10(a))
    # log10 can land one off at an exact power of ten's neighbour.
    if Decimal(a) < Decimal(10) ** exp:
        exp -= 1
    elif Decimal(a) >= Decimal(10) ** (exp + 1):
        exp += 1
    exp_digits = 3 if abs(exp) >= 100 else 2
    p = max(dec, 2)
    pu = max(width, 4) - 2

    sci_dec = _dash_sci_decimals(width, exp_digits, dec, sig_digits=True)
    if a >= 1:
        n_int = exp + 1
        if n_int > pu:
            return _dash_sci_text(a, exp, sci_dec)
        top = max(p, n_int)
        decimals = min(top - n_int, pu - n_int)
        r = _dash_stata_round(a, decimals, half_even=False)
        n_int2 = _dash_int_digit_count(float(r))
        if n_int2 > n_int and (n_int2 > top or n_int2 > pu):
            exp_carry = n_int2 - 1
            ed2 = 3 if abs(exp_carry) >= 100 else 2
            return _dash_sci_text(a, exp, 1 if ed2 == 2 else 0)
        text = _dash_decimal_text(r, decimals)
        if "." in text:
            text = text.rstrip("0").rstrip(".")
        if group and _dash_int_digit_count(float(r)) < pu:
            # Grouped only when the digits leave the width budget a
            # column (measured: %7.1gc of 12345 is 12345, %8.1gc of
            # -12345 is -12,345, %10.1gc of 1234567 is 1,234,567).
            intpart, _, frac = text.partition(".")
            grouped = (_dash_group_thousands(intpart)
                       + (("." + frac) if frac else ""))
            if len(grouped) + signlen <= width:
                text = grouped
        return text
    lz = -exp - 1
    fs = min(p, pu - lz)
    if exp < -5 or fs < 1 + sci_dec:
        return _dash_sci_text(a, exp, sci_dec)
    r = _dash_stata_round(a, lz + fs, half_even=False)
    text = _dash_decimal_text(r, lz + fs)
    if "." in text:
        text = text.rstrip("0").rstrip(".")
    if text.startswith("0."):
        text = text[1:]
    return text or "0"


def _dash_g_text(a, dec, width, group, signlen=0):
    """The ``g``/``gc`` text for positive *a* (TR-04.2): Stata's own
    default format.  ``dec == 0`` is "Stata chooses" (format.sthlp:
    292-325): up to ``width - 2`` significant digits, trailing zeros and
    a value's leading ``0`` before the point stripped.  ``dec > 0`` shows
    ``max(dec, integer digits)`` significant digits.  ``g`` rounds ties
    away from zero (measured: ``%9.2g``, ``%4.0g`` and ``%12,2gc`` of
    20.5 are all 21, never the even-rounded 20 that ``%9.0f`` gives the
    same tie -- ``f`` is the one kind that rounds half to even).

    Scientific when the integer part alone needs more than ``width - 2``
    digits.  Below 1, auto (``dec == 0``) and explicit *dec* disagree on
    WHEN: auto compares how many significant digits each form would
    actually show -- fixed's shrink as leading zeros eat the ``width - 2``
    decimal budget, scientific's stay width-driven -- and switches when
    fixed would show fewer (measured: at ``%6.0g``, 0.000123456's fixed
    form keeps 1 digit against scientific's 2, so it goes scientific,
    while ``%9.0g``'s wider budget keeps 4 against scientific's 3 and
    stays fixed).  An explicit *dec* instead uses the plain, width-
    independent ``%g`` threshold, exponent under -4 (measured:
    0.0000029394 goes scientific under ``%12,2gc``, 0.000123456 does
    not, at the SAME width).

    An explicit *dec* follows Stata's measured rule instead (WP-30
    P1.5.7; every row of ``format_truth.json``'s ``narrow_formats``):
    ``P = max(dec, 2)`` digits, an effective width ``we = max(width, 4)``
    and ``pu = we - 2``.  At or above 1, with ``I`` integer digits,
    scientific when ``I > pu``, else ``min(max(P, I) - I, pu - I)``
    decimals, and a rounding carry past ``max(P, I)`` or ``pu`` digits
    goes scientific with the floor's decimals (``%10.3g`` of 999.96 is
    ``1.0e+03``).  Below 1, ``fs = min(P, pu - leading zeros)`` digits,
    scientific when the exponent is under -5 or ``fs`` falls short of
    scientific's own digits (``%6.4g`` of .0001 is ``1.0e-04``,
    ``%12.2g`` of .00001 is ``.00001``, ``%10.1g`` of 1.23 is ``1.2``).
    Zero writes ``0``."""
    if dec > 0:
        return _dash_g_text_explicit(a, dec, width, group, signlen)
    exp = 0 if a == 0 else math.floor(math.log10(a))
    # Zero has no digits of its own; treated as needing exactly one (as
    # if it were any other single-digit number) so the same narrow-width
    # scientific check applies to it (measured: %3.0g of 0 is 0.0e+00).
    int_digits = 1 if a == 0 else max(exp + 1, 0)
    p_upper = width - 2

    use_sci = int_digits > p_upper
    if not use_sci and int_digits == 0:
        if dec == 0:
            leading_zeros = -exp - 1
            sig_fixed = max(p_upper - leading_zeros, 0)
            sci_sig = 1 + _dash_sci_decimals(
                width, 3 if abs(exp) >= 100 else 2, 0)
            use_sci = sig_fixed < sci_sig
        else:
            use_sci = exp < -4
    if not use_sci:
        if int_digits >= 1:
            sig = (p_upper if dec == 0 else max(dec, int_digits))
            if sig > p_upper:
                use_sci = True
            else:
                decimals = sig - int_digits
                if dec == 0 and decimals == 0:
                    # The integer part alone used up the whole budget:
                    # the same sig-fig-vs-scientific comparison as the
                    # below-1 case, since fixed form would show exactly
                    # int_digits digits and nothing more (measured:
                    # %3.0g of 3.14159 is 3.1e+00, not "3" -- one digit
                    # loses to scientific's two).
                    sci_sig = 1 + _dash_sci_decimals(
                        width, 3 if abs(exp) >= 100 else 2, 0)
                    use_sci = int_digits < sci_sig
        else:
            decimals = p_upper if dec == 0 else dec + (-exp - 1)
        if not use_sci:
            r = _dash_stata_round(a, decimals, half_even=False)
            # A rounding carry can grow the integer part (999.6 at 0
            # decimals becomes 1000): one correction pass.
            new_digits = _dash_int_digit_count(float(r))
            if new_digits > int_digits and int_digits >= 1:
                int_digits = new_digits
                sig = (p_upper if dec == 0 else max(dec, int_digits))
                decimals = max(sig - int_digits, 0)
                r = _dash_stata_round(a, decimals, half_even=False)
            text = _dash_decimal_text(r, decimals)
            if group and int_digits >= 1:
                n_commas = (int_digits - 1) // 3
                if dec == 0:
                    # Auto: the comma reduces the sig-fig budget by the
                    # commas it will insert (measured: %8.0gc of
                    # 6165.2567 is 6,165.3, one decimal, not two -- the
                    # comma "costs" a digit); if there is not enough
                    # budget to spare even one, grouping is skipped
                    # entirely, not clamped to zero decimals (measured:
                    # %10.0gc of 1e7 stays "10000000", ungrouped, while
                    # %12.0gc of the same value groups it -- width 10's
                    # decimals is already 0 and needs 2 commas' worth of
                    # spare budget it does not have; width 12's decimals
                    # is 2, exactly covering both).
                    decimals_c = decimals - n_commas
                    grouping_ok = decimals_c >= 0
                else:
                    # An explicit *dec* does not shrink its own decimals
                    # for the comma: the grouped text is tried as is and
                    # kept only if it fits the width (measured: %12,2gc
                    # of 6165.2567 is 6.165 -- decimals stayed 0, not
                    # negative -- and of 1e7 is 10.000.000, both fitting
                    # width 12 without any reduction).
                    decimals_c = decimals
                    grouping_ok = True
                if grouping_ok:
                    r2 = _dash_stata_round(a, decimals_c, half_even=False)
                    text2 = _dash_decimal_text(r2, decimals_c)
                    intpart2, _, frac2 = text2.partition(".")
                    grouped = (_dash_group_thousands(intpart2)
                               + (("." + frac2) if frac2 else ""))
                    if len(grouped) + signlen <= width:
                        text = grouped
            # g strips trailing zeros (and the point they leave bare);
            # e and f never do.
            if "." in text:
                text = text.rstrip("0").rstrip(".")
            if int_digits == 0 and text.startswith("0."):
                text = text[1:]
    if use_sci:
        exp_digits = 3 if abs(exp) >= 100 else 2
        decimals = _dash_sci_decimals(width, exp_digits, dec, sig_digits=True)
        text = _dash_sci_text(a, exp, decimals)
    return text


def _dash_float32_text(value):
    """The shortest decimal text that reads back as the same float32 as
    *value*, JavaScript-style exponent (``1e-7``, not ``1.0e-07``).  Used
    only for the twin-agreement tests (report W §2): dash never writes a
    variable's raw stored value to the page, only its display-formatted
    text."""
    v = float(np.float32(value))
    if v == 0:
        return "-0" if math.copysign(1.0, v) < 0 else "0"
    for prec in range(1, 18):
        s = repr(float(f"%.{prec}g" % v))
        if float(np.float32(float(s))) == v:
            break
    else:
        s = repr(v)
    text = f"%.{prec}g" % v
    if "e" in text:
        mant, exp = text.split("e")
        if "." in mant:
            mant = mant.rstrip("0").rstrip(".")
        exp_i = int(exp)
        text = f"{mant}e{'+' if exp_i >= 0 else '-'}{abs(exp_i)}"
    elif "." in text:
        text = text.rstrip("0").rstrip(".")
    return text


# ---- The date writer -------------------------------------------------------

#: Full and three-letter month names, 1-indexed (index 0 unused).
_DASH_FMT_MONTHS = (
    None,
    ("January", "Jan"), ("February", "Feb"), ("March", "Mar"),
    ("April", "Apr"), ("May", "May"), ("June", "Jun"),
    ("July", "Jul"), ("August", "Aug"), ("September", "Sep"),
    ("October", "Oct"), ("November", "Nov"), ("December", "Dec"),
)

#: Full, three-letter and two-letter weekday names, Monday-first (Python's
#: ``date.weekday()`` order).
_DASH_FMT_DAYS = (
    ("Monday", "Mon", "Mo"), ("Tuesday", "Tue", "Tu"),
    ("Wednesday", "Wed", "We"), ("Thursday", "Thu", "Th"),
    ("Friday", "Fri", "Fr"), ("Saturday", "Sat", "Sa"),
    ("Sunday", "Sun", "Su"),
)

#: Every code token dash's date picture parser recognises, LONGEST first
#: so e.g. "Dayname" is not read as "Day" + "name".  Paired with its
#: reserved column width in _DASH_FMT_WIDTHS.  "Day"/"day" (the 3-letter
#: weekday abbreviation) reserve 4 columns, one more than their own text
#: -- measured (format_truth.json, %tdDayname_Day_Da_day_da): every row of
#: that picture carries two spare columns no code individually accounts
#: for at 3; the fixture, not the grammar, sets the reserved width.
_DASH_FMT_CODES = (
    "DAYNAME", "Dayname", "Month", "month", "a.m.", "A.M.", ".sss",
    "JJJ", "jjj", "Mon", "mon", "Day", "day", ".ss",
    "CC", "cc", "YY", "yy", "NN", "nn", "DD", "dd", "Da", "da",
    "WW", "ww", "HH", "Hh", "hH", "hh", "MM", "mm", "SS", "ss",
    "am", "AM", ".s",
    "h", "q",
)

_DASH_FMT_WIDTHS = {
    "DAYNAME": 9, "Dayname": 9, "Month": 9, "month": 9,
    "a.m.": 4, "A.M.": 4, ".sss": 4,
    "JJJ": 3, "jjj": 3, "Mon": 3, "mon": 3, "Day": 4, "day": 4, ".ss": 3,
    "CC": 2, "cc": 2, "YY": 2, "yy": 2, "NN": 2, "nn": 2, "DD": 2, "dd": 2,
    "Da": 2, "da": 2, "WW": 2, "ww": 2, "HH": 2, "Hh": 2, "hH": 2, "hh": 2,
    "MM": 2, "mm": 2, "SS": 2, "ss": 2, "am": 2, "AM": 2, ".s": 2,
    "h": 1, "q": 1,
    ".": 1, ",": 1, ":": 1, "-": 1, "_": 1, "/": 1, "\\": 1, "+": 0,
}

#: Stata's own range, one day/period/year count per kind (dash_render.py's
#: header comment, measured 24sep2026); a value outside it prints the
#: bare number, in the format's own default width (below), never a date.
_DASH_FMT_RANGE = {
    "d": (-679350, 2936549), "w": (-96720, 418079), "m": (-22320, 96479),
    "q": (-7440, 32159), "h": (-3720, 16079), "y": (100, 9999),
}
_DASH_FMT_FALLBACK_WIDTH = {
    "d": 9, "c": 18, "C": 18, "w": 7, "m": 7, "q": 6, "h": 6, "y": 4,
}
#: A kind's own default picture (DISCOVERY Q6, datetime_display_formats.sthlp).
_DASH_FMT_DEFAULT_PICTURE = {
    "d": "DDmonCCYY", "c": "DDmonCCYY_HH:MM:SS", "C": "DDmonCCYY_HH:MM:SS",
    "w": "CCYY!www", "m": "CCYY!mnn", "q": "CCYY!qq", "h": "CCYY!hh",
    "y": "CCYY",
}


def _dash_fmt_calendar(value, tkind):
    """*value* (a Stata date/period number of kind *tkind*, one of
    ``c C d h m q t w y``) as a calendar context dict: ``year, month,
    day, hour, minute, second, ms, weekday`` (0=Monday), ``doy``
    (day-of-year), ``quarter``, ``half``, ``week`` (this kind's own week
    number, tw's rule).  ``None`` when *value* is not finite or lies
    outside Stata's range for *tkind* (01jan0100 to 31dec9999).

    The calendar comes from :mod:`datetime`, not ``pandas.Timestamp``:
    Stata's range runs to year 9999 and down to year 100, both outside
    pandas' nanosecond datetime64 (1677-2262), but inside Python's own
    ``date``/``datetime`` (year 1-9999), which use the same proleptic
    Gregorian calendar Stata does.
    """
    try:
        v = float(value)
    except (TypeError, ValueError):
        return None
    if not math.isfinite(v):
        return None
    epoch = _dt.date(1960, 1, 1)

    if tkind in ("c", "C"):
        lo, hi = _STATA_MS_MIN, _STATA_MS_MAX
        if not lo <= v <= hi:
            return None
        ms = int(math.floor(v))
        base = _dt.datetime(1960, 1, 1)
        delta = _dt.timedelta(milliseconds=ms)
        dt_ = base + delta
        # Milliseconds within the second, always 0-999: Python's modulo
        # (never negative for a positive divisor) truncates toward the
        # correct value even for a negative ms (measured: tc -120 is
        # 23:59:59.880, and -120 % 1000 == 880).
        ms_frac = ms % 1000
        return {"year": dt_.year, "month": dt_.month, "day": dt_.day,
                "hour": dt_.hour, "minute": dt_.minute,
                "second": dt_.second, "ms": ms_frac,
                "weekday": dt_.weekday(),
                "doy": dt_.timetuple().tm_yday,
                "quarter": (dt_.month - 1) // 3 + 1,
                "half": (dt_.month - 1) // 6 + 1, "week": None}

    if tkind == "d":
        lo, hi = _DASH_FMT_RANGE["d"]
        if not lo <= v <= hi:
            return None
        day_n = int(math.floor(v))
        d = epoch + _dt.timedelta(days=day_n)
        return {"year": d.year, "month": d.month, "day": d.day,
                "hour": 0, "minute": 0, "second": 0, "ms": 0,
                "weekday": d.weekday(), "doy": d.timetuple().tm_yday,
                "quarter": (d.month - 1) // 3 + 1,
                "half": (d.month - 1) // 6 + 1,
                "week": (day_n // 7) % 52 + 1}

    if tkind == "w":
        lo, hi = _DASH_FMT_RANGE["w"]
        if not lo <= v <= hi:
            return None
        wk = int(math.floor(v))
        year = 1960 + wk // 52
        week = wk % 52 + 1
        d = epoch + _dt.timedelta(days=wk * 7)
        return {"year": year, "month": d.month, "day": d.day,
                "hour": 0, "minute": 0, "second": 0, "ms": 0,
                "weekday": d.weekday(), "doy": d.timetuple().tm_yday,
                "quarter": (d.month - 1) // 3 + 1,
                "half": (d.month - 1) // 6 + 1, "week": week}

    if tkind == "m":
        lo, hi = _DASH_FMT_RANGE["m"]
        if not lo <= v <= hi:
            return None
        mo = int(math.floor(v))
        year = 1960 + mo // 12
        month = mo % 12 + 1
        return {"year": year, "month": month, "day": 1,
                "hour": 0, "minute": 0, "second": 0, "ms": 0,
                "weekday": _dt.date(year, month, 1).weekday(), "doy": None,
                "quarter": (month - 1) // 3 + 1,
                "half": (month - 1) // 6 + 1, "week": None}

    if tkind == "q":
        lo, hi = _DASH_FMT_RANGE["q"]
        if not lo <= v <= hi:
            return None
        qn = int(math.floor(v))
        year = 1960 + qn // 4
        quarter = qn % 4 + 1
        month = (quarter - 1) * 3 + 1
        return {"year": year, "month": month, "day": 1,
                "hour": 0, "minute": 0, "second": 0, "ms": 0,
                "weekday": _dt.date(year, month, 1).weekday(), "doy": None,
                "quarter": quarter, "half": (month - 1) // 6 + 1,
                "week": None}

    if tkind == "h":
        lo, hi = _DASH_FMT_RANGE["h"]
        if not lo <= v <= hi:
            return None
        hn = int(math.floor(v))
        year = 1960 + hn // 2
        half = hn % 2 + 1
        month = (half - 1) * 6 + 1
        return {"year": year, "month": month, "day": 1,
                "hour": 0, "minute": 0, "second": 0, "ms": 0,
                "weekday": _dt.date(year, month, 1).weekday(), "doy": None,
                "quarter": (month - 1) // 3 + 1, "half": half, "week": None}

    if tkind == "y":
        lo, hi = _DASH_FMT_RANGE["y"]
        if not lo <= v <= hi:
            return None
        year = int(math.floor(v))
        return {"year": year, "month": 1, "day": 1,
                "hour": 0, "minute": 0, "second": 0, "ms": 0,
                "weekday": _dt.date(year, 1, 1).weekday(), "doy": 1,
                "quarter": 1, "half": 1, "week": None}
    return None


def _dash_fmt_render_code(code, ctx):
    """One picture code's text, from a calendar context dict (padding is
    the caller's job, via _DASH_FMT_WIDTHS)."""
    y, mo, d = ctx["year"], ctx["month"], ctx["day"]
    if code == "CC":
        return f"{(y // 100) % 100:02d}"
    if code == "cc":
        return str(y // 100)
    if code == "YY":
        return f"{y % 100:02d}"
    if code == "yy":
        return str(y % 100)
    if code == "NN":
        return f"{mo:02d}"
    if code == "nn":
        return str(mo)
    if code == "DD":
        return f"{d:02d}"
    if code == "dd":
        return str(d)
    if code in ("Month", "month"):
        name = _DASH_FMT_MONTHS[mo][0]
        return name if code == "Month" else name.lower()
    if code in ("Mon", "mon"):
        name = _DASH_FMT_MONTHS[mo][1]
        return name if code == "Mon" else name.lower()
    if code in ("Dayname", "DAYNAME"):
        # Measured (format_truth.json, %tdDAYNAME): both spell the full
        # weekday name the SAME way, title case -- "DAYNAME" is not
        # upper-cased, despite its own spelling.
        return _DASH_FMT_DAYS[ctx["weekday"]][0]
    if code in ("Day", "day"):
        name = _DASH_FMT_DAYS[ctx["weekday"]][1]
        return name if code == "Day" else name.lower()
    if code in ("Da", "da"):
        name = _DASH_FMT_DAYS[ctx["weekday"]][2]
        return name if code == "Da" else name.lower()
    if code in ("WW", "ww"):
        w = ctx["week"] if ctx["week"] is not None else 0
        return f"{w:02d}" if code == "WW" else str(w)
    if code in ("HH", "hh", "Hh", "hH"):
        h = ctx["hour"]
        twelve = h % 12
        twelve = 12 if twelve == 0 else twelve
        if code == "HH":
            return f"{h:02d}"
        if code == "hH":
            return str(h)
        if code == "hh":
            return f"{twelve:02d}"
        return str(twelve)   # "Hh"
    if code == "MM":
        return f"{ctx['minute']:02d}"
    if code == "mm":
        return str(ctx["minute"])
    if code == "SS":
        return f"{ctx['second']:02d}"
    if code == "ss":
        return str(ctx["second"])
    if code == ".s":
        return "." + str(ctx["ms"] // 100)
    if code == ".ss":
        return f".{ctx['ms'] // 10:02d}"
    if code == ".sss":
        return f".{ctx['ms']:03d}"
    if code in ("am", "AM", "a.m.", "A.M."):
        pm = ctx["hour"] >= 12
        if code == "am":
            return "pm" if pm else "am"
        if code == "AM":
            return "PM" if pm else "AM"
        if code == "a.m.":
            return "p.m." if pm else "a.m."
        return "P.M." if pm else "A.M."
    if code in ("JJJ", "jjj"):
        doy = ctx["doy"] or 1
        return f"{doy:03d}" if code == "JJJ" else str(doy)
    if code == "h":
        return str(ctx["half"])
    if code == "q":
        return str(ctx["quarter"])
    return code


def _dash_fmt_tokenize_picture(picture):
    """*picture* split into a list of tokens: a recognised code name, or a
    one-character literal (``!x`` -> the literal ``x``, ``+`` -> nothing,
    ``_`` -> a space (TR-04.3's own list: "_ a space"), any other
    unrecognised character -> itself)."""
    tokens = []
    i, n = 0, len(picture)
    while i < n:
        if picture[i] == "!" and i + 1 < n:
            tokens.append(("lit", picture[i + 1]))
            i += 2
            continue
        if picture[i] == "+":
            tokens.append(("lit", ""))
            i += 1
            continue
        if picture[i] == "_":
            tokens.append(("lit", " "))
            i += 1
            continue
        matched = None
        for code in _DASH_FMT_CODES:
            if picture.startswith(code, i):
                matched = code
                break
        if matched:
            tokens.append(("code", matched))
            i += len(matched)
        else:
            tokens.append(("lit", picture[i]))
            i += 1
    return tokens


#: Stata's missing threshold: a double at or past 2**1023 (its largest
#: non-missing value is just below) is a missing value (measured, S12).
_DASH_FMT_MISSING_AT = 2.0 ** 1023


def _dash_fmt_date(parsed, value):
    """*value* (a Stata date/period number) written under *parsed* (a
    ``kind == "t"`` ``_dash_fmt_parse`` result): the picture's own default
    when none is given, else the custom one, right-aligned (or left, for
    ``%-t``) to the picture's own maximum width.  A value outside the
    kind's range prints the bare number in the kind's default width
    (%9.0g's own auto rule, TR-04.3)."""
    tkind = parsed["tkind"]
    kind_key = {"c": "c", "C": "C", "d": "d", "w": "w", "m": "m",
                "q": "q", "h": "h", "y": "y"}[tkind]
    ctx = _dash_fmt_calendar(value, tkind)
    picture = parsed["picture"] or _DASH_FMT_DEFAULT_PICTURE[kind_key]
    if ctx is None:
        try:
            v = float(value)
        except (TypeError, ValueError):
            return "."
        if not math.isfinite(v):
            return "."
        w = _DASH_FMT_FALLBACK_WIDTH[kind_key]
        # At or past Stata's largest double, 2**1023, a value is missing:
        # measured in StataMP 19 (30sep2026), `display %td 1e308' is
        # "      .z_" and `display %td -1e308' is "        .", each padded
        # to the picture's width.
        if abs(v) >= _DASH_FMT_MISSING_AT:
            mtext = ".z_" if v > 0 else "."
            mw = _dash_fmt_picture_width(parsed)
            return mtext.ljust(mw) if parsed["left"] else mtext.rjust(mw)
        # Not through _dash_fmt_number: its scientific fallback pads to a
        # floor of 8 (a numeric FORMAT's own %w.0g convention), but a
        # date's own bare-number fallback does not (measured: %th of
        # 2936549 is "2.9e+06", 7 characters, unpadded at width 6).  A
        # clock writes %12.0g's digits in its 18 columns (measured: %tc of
        # 1e15 is "       1.00000e+15").
        gw = 12 if kind_key in ("c", "C") else w
        sign = "-" if v < 0 else ""
        text = _dash_g_text(abs(v), 0, gw, False, len(sign))
        body = sign + text
        return body.rjust(w)
    tokens = _dash_fmt_tokenize_picture(picture)
    parts, width = [], 0
    for kind_, val_ in tokens:
        if kind_ == "code":
            parts.append(_dash_fmt_render_code(val_, ctx))
            width += _DASH_FMT_WIDTHS.get(val_, len(val_))
        else:
            parts.append(val_)
            width += 1 if val_ else 0
    text = "".join(parts)
    return text.ljust(width) if parsed["left"] else text.rjust(width)


def _dash_fmt_picture_width(parsed):
    """The maximum width a date/period ``parsed`` result's picture
    renders to -- value-independent (every token's own reserved column
    count, _DASH_FMT_WIDTHS), so a missing value can be padded to it
    without a real calendar context."""
    tkind = parsed.get("tkind")
    picture = parsed.get("picture") or _DASH_FMT_DEFAULT_PICTURE.get(tkind, "")
    width = 0
    for kind_, val_ in _dash_fmt_tokenize_picture(picture):
        width += (_DASH_FMT_WIDTHS.get(val_, len(val_)) if kind_ == "code"
                   else (1 if val_ else 0))
    return width


def _dash_stata_value_of(column_value, date_kind):
    """*column_value* (epoch milliseconds -- a float, or anything
    ``float()`` accepts, as a rendered page's ColumnDataSource and a
    saved dataframe both hold a date) back to the Stata value of
    *date_kind* (``td tc tC tw tm tq th ty``): the inverse
    ``_dash_unix_ms_to_unit``/the loader's own date conversion take.
    ``None`` for a value that is missing, not finite, or outside Stata's
    range."""
    try:
        ms = float(column_value)
    except (TypeError, ValueError):
        return None
    if not math.isfinite(ms):
        return None
    if date_kind in ("tc", "tC"):
        v = ms - _STATA_EPOCH_UNIX_MS
        lo, hi = _STATA_MS_MIN, _STATA_MS_MAX
        return v if lo <= v <= hi else None
    if date_kind == "td":
        v = (ms - _STATA_EPOCH_UNIX_MS) / 86_400_000.0
        lo, hi = _DASH_FMT_RANGE["d"]
        return v if lo <= v <= hi else None
    unit = {"tw": "w", "tm": "m", "tq": "q", "th": "h",
            "ty": "y"}.get(date_kind)
    if unit is None:
        return None
    u = _dash_unix_ms_to_unit(ms, {"w": "w", "m": "m", "q": "q",
                                    "h": "h", "y": "y"}[unit])
    if u is None:
        return None
    v = math.floor(u)
    lo, hi = _DASH_FMT_RANGE[unit]
    return float(v) if lo <= v <= hi else None


def _dash_fmt(value, fmt, storage=None, strip=False, dp="period",
              bcal=None):
    """*value* (a Stata numeric value -- for a ``%t`` format, the Stata
    date/period NUMBER itself, never epoch milliseconds) written exactly
    as Stata's ``display %fmt (value)`` writes it, right-aligned to the
    format's own width (a date to its picture's maximum width; ``%-``
    left-aligns).  ``None``/``NaN`` is a missing value: ``"."``, padded.

    ``storage="float"`` widens *value* to the double a float actually
    holds (measured, task 04-06: ``%12.0g``/``%20.0g`` of a float 0.1
    show the WIDENED double's digits, e.g. ``.10000000149011612`` at
    ``%20.0g`` -- not the shortest float32 text -- so this is a one-line
    ``float(np.float32(value))`` before writing, never
    :func:`_dash_float32_text`, which exists only for the twin-agreement
    tests).  A format ``_dash_fmt_kind`` cannot place (``None``, ``"x"``,
    ``"H"``) is written in ``%9.0g`` instead -- never raises; naming the
    refusal is the caller's job through :func:`_dash_fmt_refusal`.

    *dp* is the page's ``set dp`` (``build_options["dp"]``, WP-31 G2):
    under ``"comma"`` a numeric format's decimal point is a comma and its
    thousands separator a period, as ``display`` writes them; a date
    picture is unchanged.

    A ``%tb<cal>[:picture]`` format (WP-31 G7) reads *bcal*, the
    calendar's table ``{"min": k0, "td": [%td of k0, ...]}`` dash.ado
    embedded at registration: a value is written as its business day's
    ``%td`` date in the picture (``%tbu46 5.5`` is 08jan2024), and one
    outside the calendar, or with no table, as the bare number in
    ``%9.0g`` (``%tbu46 22`` is ``       22``), as Stata writes them.
    """
    try:
        v = float(value)
    except (TypeError, ValueError):
        v = float("nan")
    if storage == "float" and math.isfinite(v):
        with warnings.catch_warnings():
            # A value beyond float32's range casts to +/-inf (numpy warns);
            # Stata's own float() makes such a value missing, measured
            # (format_truth.json: float(1e100) under %9.0g is ".").  A
            # value below float32's smallest subnormal casts to 0, which
            # is what Stata's float() gives too (float(1e-100) is "0").
            warnings.simplefilter("ignore", RuntimeWarning)
            v = float(np.float32(v))
        if not math.isfinite(v):
            v = float("nan")
    parsed = _dash_fmt_parse(fmt)
    if parsed and parsed.get("tkind") == "b":
        td = _dash_bcal_td(v, bcal)
        if td is None:
            return _dash_fmt(v, "%9.0g", strip=strip, dp=dp)
        return _dash_fmt(td, "%td" + parsed["picture"], strip=strip, dp=dp)
    kind = parsed["kind"] if parsed else None
    if kind in (None, "x", "H"):
        parsed = {"kind": "g", "width": 9, "dec": 0, "left": False,
                  "zero": False, "group": False, "comma_dec": False}
        kind = "g"
    if dp == "comma" and kind in ("f", "g", "e"):
        parsed = dict(parsed, comma_dec=True)
    if not math.isfinite(v):
        width = (_dash_fmt_picture_width(parsed) if kind == "t"
                  else parsed["width"])
        text = "."
        result = text.ljust(width) if parsed["left"] else text.rjust(width)
    elif kind == "t":
        result = _dash_fmt_date(parsed, v)
    else:
        result = _dash_fmt_number(parsed, v)
    return result.strip() if strip else result


def _dash_fmt_writes_number(fmt):
    """True when *fmt* writes a plain number column: a numeric ``%f``,
    ``%g`` or ``%e`` format, or a ``%tb<cal>`` business-calendar format,
    held as its business-day numbers and written through its calendar
    (WP-31 G7)."""
    if not isinstance(fmt, str):
        return False
    return (_dash_fmt_kind(fmt) in ("f", "g", "e")
            or bool(_DASH_FMT_TB_RE.fullmatch(fmt)))


def _dash_bcal_td(v, table):
    """The %td day of business day *v* in a calendar *table*
    (``{"min": k0, "td": [...]}``, WP-31 G7), or None when *v* is missing
    or outside it, or the table is not one; *v*'s fraction is dropped, as
    ``dofb()`` drops it."""
    try:
        k0 = int(table["min"])
        td = table["td"]
        if not (isinstance(td, list) and math.isfinite(v)):
            return None
        i = int(math.floor(v)) - k0
        if 0 <= i < len(td) and td[i] is not None:
            return float(td[i])
    except (TypeError, ValueError, KeyError, OverflowError):
        pass
    return None


def _dash_fmt_text(value, fmt, storage=None, dp="period", bcal=None):
    """:func:`_dash_fmt` with its padding stripped -- the page-facing
    form every card, label, tooltip and axis tick uses.  ``"."`` for a
    missing value; *dp* the page's decimal mark."""
    return _dash_fmt(value, fmt, storage=storage, strip=True, dp=dp,
                     bcal=bcal)


#: The body of every page-side Stata formatter (WP-28 S12, GAPS2 E3/G6):
#: _DASH_FMT_JS's dash_fmt_text under the args fmt, kind and storage.  A
#: date column reaches BokehJS as epoch milliseconds, so *kind* turns it
#: back into Stata's value first.  The format is DATA in args, never code.
_DASH_FMT_MODEL_JS = """
var _dash_v = kind ? dash_stata_value_of(%s, kind) : %s;
if ((_dash_v === null || _dash_v === undefined) && kind) { _dash_v = dash_stata_number_of(%s, kind); }
if (_dash_v === null || _dash_v === undefined) { return "."; }
return dash_fmt_text(_dash_v, fmt, storage, dp, typeof bcal === "undefined" ? null : bcal);
"""


def _dash_fmt_model_args(fmt, kind, storage, dp="period", bcals=None):
    """The args of a page-side formatter: *fmt* (``%9.0g`` when empty),
    the date *kind* (``""`` for a number), the *storage* type and the
    page's decimal mark *dp* (WP-31 G2); for a ``%tb<cal>`` format, the
    calendar's table from *bcals* (``build_options["bcal"]``, WP-31 G7)
    as ``bcal``."""
    args = {"fmt": str(fmt or "%9.0g"), "kind": str(kind or ""),
            "storage": str(storage or ""),
            "dp": "comma" if dp == "comma" else "period"}
    m = _DASH_FMT_TB_RE.fullmatch(args["fmt"])
    if m and isinstance(bcals, dict) and isinstance(bcals.get(m.group(1)),
                                                     dict):
        args["bcal"] = bcals[m.group(1)]
    return args


def _dash_dp_fmt(fmt, dp):
    """*fmt* in the page's decimal mark (WP-31 G2): under ``"comma"`` a
    numeric ``%w.d`` format becomes ``%w,d`` -- what ``display`` writes
    under ``set dp comma`` -- for a writer handed a format, not a mark
    (the saved page's KPI and colour-key rebuilds).  Any other format, and
    any format under ``"period"``, unchanged."""
    fmt = str(fmt or "")
    if dp == "comma" and re.fullmatch(r"%-?0?\d+\.\d+[fge]c?", fmt):
        return fmt.replace(".", ",", 1)
    return fmt


def _dash_page_dp(dp=None):
    """*dp* when given; else the decimal mark of the generated app's one
    page (its ``_DASH_MAPPER``, set by ``_dash_page_settings`` from the
    app's own spec), else ``"period"``.  The saved renderer passes *dp*;
    only a writer the app calls without it reads the app's (WP-31 G2)."""
    if dp:
        return dp
    return getattr(globals().get("_DASH_MAPPER"), "dp", "period") or "period"


def _dash_cache_dp(cache):
    """The page's decimal mark a document's formatter cache carries
    (``_dash_page_settings``), ``"period"`` when it carries none."""
    return (cache.get("dp", "period") if isinstance(cache, dict)
            else "period")


def _dash_page_settings(mapper, cache, build_options):
    """Hand one page's settings from its spec's *build_options* to the
    page's *mapper* and formatter *cache* (WP-31 G2): ``set dp``
    (``mapper.dp``, ``cache["dp"]``) and the faces ``graph set`` gives the
    font tags (``mapper._dash_gt_fonts``).  Both modes call it once per
    document."""
    dp = _dash_build_dp({"build_options": build_options})
    if mapper is not None:
        mapper.dp = dp
        mapper._dash_gt_fonts = _dash_gt_fonts_of(build_options)
        # WP-31 D15: Stata's own ticks for the ranges the export summarized,
        # stamped on each figure before its axes are finished.
        mapper._dash_stata_ticks = _dash_stata_tick_table(build_options) \
            or ([] if _DASH_STATA_ORACLE.get("on") else None)
    if isinstance(cache, dict):
        cache["dp"] = dp
        # WP-31 G7: the business calendars dash.ado embedded, for the
        # %tb formatters' args.
        bc = (build_options or {}).get("bcal")
        cache["bcal"] = bc if isinstance(bc, dict) else {}
    return dp


def _dash_fmt_tick_formatter(fmt, kind, storage, cache):
    """A ``CustomJSTickFormatter`` writing each tick (or slider value) as
    Stata's ``display`` text under *fmt*: section 04's JavaScript writer
    with the format in ``args``, never in ``code`` (TR-12.1).  *kind* is
    the date kind of an epoch-millisecond value (``""`` for a number or a
    period number).  One model per ``(fmt, kind, storage)`` triple in
    *cache* (a dict per rendered document; None builds a fresh one): the
    writer is large, and a Bokeh model belongs to one document."""
    from bokeh.models import CustomJSTickFormatter
    args = _dash_fmt_model_args(fmt, kind, storage, _dash_cache_dp(cache),
                                (cache or {}).get("bcal"))
    key = ("tick", args["fmt"], args["kind"], args["storage"], args["dp"])
    if cache is not None and key in cache:
        return cache[key]
    model = CustomJSTickFormatter(
        args=args, code=_DASH_FMT_JS + _DASH_FMT_MODEL_JS % (("tick",) * 3))
    if cache is not None:
        cache[key] = model
    return model


def _dash_fmt_label_tick_formatter(labels, fmt, kind, storage, cache):
    """A ``CustomJSTickFormatter`` that writes a tick holding a text
    label as that label and every other tick as Stata's ``display`` text
    under *fmt* (WP-30 P1.5, TR-18.6; measured: twoway's ``xlabel(2000
    "two" 3000 4000)`` on weight ``%8.0gc`` reads ``two 3,000 4,000``).
    *labels* is the JSON text of the tick-to-label map; it, the format,
    the date *kind* and the *storage* type travel in ``args``, never in
    ``code``.  One model per ``(labels, fmt, kind, storage)`` in
    *cache*."""
    from bokeh.models import CustomJSTickFormatter
    args = _dash_fmt_model_args(fmt, kind, storage, _dash_cache_dp(cache),
                                (cache or {}).get("bcal"))
    args["labels"] = str(labels)
    key = ("label", args["labels"], args["fmt"], args["kind"],
           args["storage"], args["dp"])
    if cache is not None and key in cache:
        return cache[key]
    code = (_DASH_FMT_JS
            + "var _dash_m = JSON.parse(labels); "
              "var _dash_k = String(tick); "
              "var _dash_h = Object.prototype.hasOwnProperty; "
              "if (!_dash_h.call(_dash_m, _dash_k) && Number.isInteger(tick)) "
              "{ _dash_k = _dash_k + '.0'; } "
              "if (_dash_h.call(_dash_m, _dash_k)) "
              "{ return _dash_m[_dash_k]; }\n"
            + _DASH_FMT_MODEL_JS % (("tick",) * 3))
    model = CustomJSTickFormatter(args=args, code=code)
    if cache is not None:
        cache[key] = model
    return model


def _dash_fmt_hover(fmt, kind, storage, cache):
    """The ``CustomJSHover`` twin of :func:`_dash_fmt_tick_formatter`, for
    a ``@{col}{custom}`` tooltip field: it writes BokehJS's ``value``."""
    from bokeh.models import CustomJSHover
    args = _dash_fmt_model_args(fmt, kind, storage, _dash_cache_dp(cache),
                                (cache or {}).get("bcal"))
    key = ("hover", args["fmt"], args["kind"], args["storage"], args["dp"])
    if cache is not None and key in cache:
        return cache[key]
    model = CustomJSHover(
        args=args,
        code=_DASH_FMT_JS + _DASH_FMT_MODEL_JS % (("value",) * 3))
    if cache is not None:
        cache[key] = model
    return model


def _dash_date_fmt(fmt, kind):
    """*fmt* when it is a date format of *kind*, else the kind's default
    ``%t?`` -- the full picture of a date variable (``%tdCCYY-NN-DD``)
    wherever it is written, and never a numeric format on a date."""
    if kind and _stata_date_kind(fmt) == kind:
        return str(fmt).strip()
    return "%" + str(kind or "td")


def _dash_date_axis_formatter(fmt, storage, cache):
    """A date axis's tick formatter: the variable's full date format,
    written at each tick (epoch milliseconds) as twoway labels it."""
    return _dash_fmt_tick_formatter(fmt, _stata_date_kind(fmt) or "",
                                    storage, cache)


def _dash_period_values(column, unit):
    """A %tw/%tm/%tq/%th/%ty column (datetimes, or epoch milliseconds) as
    Stata's period numbers, NaN for a missing value: the vectorised
    :func:`_dash_stata_value_of`, which a period slider and both filter
    masks compare in."""
    ms = _dash_float_values(column, coerce=True)
    out = np.full(len(ms), np.nan)
    lo = _STATA_MS_MIN + _STATA_EPOCH_UNIX_MS
    hi = _STATA_MS_MAX + _STATA_EPOCH_UNIX_MS
    with np.errstate(invalid="ignore"):
        ok = np.isfinite(ms) & (ms >= lo) & (ms <= hi)
    if not ok.any():
        return out
    day = np.floor(ms[ok] / 86_400_000.0).astype(np.int64)
    d64 = day.astype("datetime64[D]")
    m64 = d64.astype("datetime64[M]")
    y = m64.astype("datetime64[Y]").astype(np.int64) + 1970
    mon = m64.astype(np.int64) - (y - 1970) * 12
    if unit == "tw":
        jan1 = (m64.astype("datetime64[Y]").astype("datetime64[D]")
                .astype(np.int64))
        v = (y - 1960) * 52 + np.minimum(51, (day - jan1) // 7)
    elif unit == "tm":
        v = (y - 1960) * 12 + mon
    elif unit == "tq":
        v = (y - 1960) * 4 + mon // 3
    elif unit == "th":
        v = (y - 1960) * 2 + mon // 6
    elif unit == "ty":
        v = y
    else:
        return out
    out[ok] = v.astype(float)
    return out


# ---- The legend -----------------------------------------------------------

#: Stata's clock positions grouped into Bokeh's four side panels.  12 is
#: straight up, 3 right, 6 down, 9 left; ring(0) keeps the legend inside
#: the plot region at the matching inside location instead.
_DASH_CLOCK_SIDE = {
    11: "above", 12: "above", 1: "above",
    2: "right", 3: "right", 4: "right",
    5: "below", 6: "below", 7: "below",
    8: "left", 9: "left", 10: "left",
}
_DASH_CLOCK_INSIDE = {
    11: "top_left", 12: "top_center", 1: "top_right",
    2: "top_right", 3: "center_right", 4: "bottom_right",
    5: "bottom_right", 6: "bottom_center", 7: "bottom_left",
    8: "bottom_left", 9: "center_left", 10: "top_left",
    # position(0): the centre of the plot region (WP-31 D4; measured,
    # legend_geometry_truth.json clock_0).
    0: "center",
}
#: Where a ring > 0 legend sits inside its side panel (WP-31 D4): twoway
#: puts a corner clock at that end of the side (box_alignment neast,
#: seast, swest, nwest: 1 and 2 at the top right, 4 and 5 at the bottom
#: right, 7 and 8 at the bottom left, 10 and 11 at the top left) and
#: 12/3/6/9 in the middle (legend_geometry_truth.json clock_1..clock_12).
_DASH_CLOCK_PANEL_LOCATION = {
    11: "top_left", 12: "center", 1: "top_right",
    2: "top_right", 3: "center", 4: "bottom_right",
    5: "bottom_right", 6: "center", 7: "bottom_left",
    8: "bottom_left", 9: "center", 10: "top_left",
}
#: legend(bplacement(compass)): the box's place in its panel (WP-31 D4).
_DASH_BPLACEMENT_LOCATION = {
    "n": "top_center", "north": "top_center",
    "ne": "top_right", "neast": "top_right",
    "e": "center_right", "east": "center_right",
    "se": "bottom_right", "seast": "bottom_right",
    "s": "bottom_center", "south": "bottom_center",
    "sw": "bottom_left", "swest": "bottom_left",
    "w": "center_left", "west": "center_left",
    "nw": "top_left", "nwest": "top_left",
    "c": "center", "center": "center",
}
#: legend(top), legend(bottom), legend(left) and legend(right) are not
#: twoway's: it refuses each, "option top not allowed", r(198) (measured
#: 23sep2026), and so does dash.ado (_dash_check_legend).  They were read
#: here as placements INSIDE the plot -- top_center and so on -- where twoway
#: places nothing, and the word was found anywhere in the text, so
#: legend(label(1 "left")) moved the legend too.  A spec that carries one
#: anyway gets it named as a legend() sub-option dash does not implement.


def _dash_legend_parts(legend_opt):
    """``(words, calls)``: legend()'s bare words and its ``name(arg)``
    sub-options, read as sub-options and never out of quoted text.

    The tokens are named as twoway names them (WP-30 P1.19): one copy
    resolved with ``_DASH_LEGEND_SUBOPT_TABLE``, so ``c(2)`` is ``cols``,
    ``posi(6)`` ``position`` and a capitalised ``OFF`` nothing.  ``words``
    is the set of full names of the bare words; ``calls`` is the list of
    ``(full, argument, typed_name)`` triples in the order written.  A token
    with no name is left out (``_dash_legend_unsupported`` names it).
    _dash_apply_legend searched the raw text with regular expressions, so
    a label's own words were read as sub-options: legend(label(1 "Turned
    off")) hid the legend, label(1 "on") forced one onto a one-key graph,
    and label(1 "left"), label(2 "pos(3)") and label(1 "ring(0)") moved it.
    """
    words, calls = set(), []
    toks = _dash_by_tokens(str(legend_opt or "").strip())
    names, _ = _dash_subopt_resolve([toks], _DASH_LEGEND_SUBOPT_TABLE)
    for tok, name in zip(toks, names[0] if names else []):
        if name is None:
            continue
        if "(" in tok:
            arg = tok.split("(", 1)[1]
            arg = arg[:-1] if arg.endswith(")") else arg
            calls.append((name, arg, tok.split("(", 1)[0].strip()))
        else:
            words.add(name)
    return words, calls


def _dash_legend_arg(calls, names, pattern=None):
    """The argument of the FIRST sub-option in *calls* named one of
    *names* -- the one the old whole-text search found -- or None; with
    *pattern*, the match of an argument that matches it whole."""
    for name, arg, *_ in calls:
        if name in names:
            if pattern is None:
                return arg.strip()
            m = re.fullmatch(pattern, arg.strip())
            if m:
                return m
    return None


#: One word of legend(order()): a run up to the next blank or string.
_DASH_ORDER_WORD_RE = re.compile(r'(?:[^\s"`]|`(?!"))+')
_DASH_ORDER_BLANK_RE = re.compile(r"\s+")


def _dash_parse_legend_order(arg):
    """legend(order()) read as twoway's ``orderinfo``: ``{#|-} ["text"
    ["text" ...]]`` repeated (legend_options.sthlp:104-111, 216-275).

    Returns ``[(key, lines), ...]`` in the order written: *key* is the
    key number (an ``int`` of at most six digits, as
    ``_DASH_LEGEND_LABEL_RE`` bounds a label's) or ``"-"`` for a text-only
    row, and *lines* the strings that followed it, each a line (a compound
    string keeps what it holds).  An empty string ends that entry's lines,
    as it ends a textbox's, so ``- ""`` has none and draws nothing.  A
    longer number, or a negative one, starts nothing and closes the entry
    before it; ``+1`` is key 1; any other bare word voids the whole
    order(), returning ``[]``, as twoway ignores it.  One linear pass, no
    regex over the whole text.
    """
    text = str(arg or "")
    out, cur, closed = [], None, False
    i, n = 0, len(text)
    while i < n:
        m = _DASH_ORDER_BLANK_RE.match(text, i)
        if m:
            i = m.end()
            continue
        if text[i] == '"' or text.startswith('`"', i):
            start, end, i = _textbox_string_end(text, i)
            if cur is not None and not closed:
                if end == start:
                    closed = True
                else:
                    cur.append(text[start:end])
            continue
        m = _DASH_ORDER_WORD_RE.match(text, i)
        if m is None:  # a lone backtick: skipped
            i += 1
            continue
        word, i = m.group(), m.end()
        digits = word[1:] if word[:1] in "+-" else word
        is_num = bool(digits) and digits.isdigit() and digits.isascii()
        if word == "-" or (is_num and word[0] != "-" and len(digits) <= 6):
            cur, closed = [], False
            out.append(("-" if word == "-" else int(digits), cur))
        elif is_num:
            cur = None  # a key that never exists: -2, or 7+ digits
        else:
            # twoway: "x not an integer, option order() ignored" -- the
            # whole order() is ignored (WP-30 P1.19; Stata prints the note).
            return []
    return out


def _dash_move_legend(fig, legend, side, location="center", ring=3):
    """Move an attached Legend into one of the figure's side panels, as
    Stata's ring 3: nearest the plot, and centred.

    Bokeh lays a side panel out in list order, the first item nearest the
    plot (``above`` and ``left`` are reversed on the way, to the same
    effect).  ``add_layout`` appends, so the legend went OUTSIDE whatever
    was already there: under s2color ``fig.below`` was ``[axis, note,
    caption, legend]`` and the note and caption sat between the plot and
    the legend; under economist the legend sat between the title and the
    subtitle.  Stata's rings are the other way round -- legend 3, note 4,
    caption 5, subtitle 6, title 7 (scheme-s2color.scheme:1946-1951) --
    so the legend goes in after the panel's axes and before everything
    else.  After the axes, not at index 0: the axis is ring 1-2 and a
    legend between the frame and the tick labels is what no scheme asks
    for.

    A side-panel legend is positioned by its ``location`` within the
    panel, and Bokeh's default ``top_right`` drew it flush right under
    the plot where Stata centres a 6 o'clock legend (and centres a 3
    o'clock one vertically).  Both modes come through here, so they
    cannot disagree.  *location* is the box's place in the panel
    (``_DASH_CLOCK_PANEL_LOCATION``: a corner clock sits at that end of
    its side, WP-31 D4); *side* ``"center"`` puts it inside the plot.
    """
    from bokeh.models import Axis
    for container in (fig.center, fig.above, fig.below, fig.left, fig.right):
        try:
            if legend in container:
                container.remove(legend)
        except (TypeError, ValueError):
            pass
    if side == "center":
        fig.center = list(fig.center) + [legend]
        legend.location = location
        return
    panel = list(getattr(fig, side))
    # After the edge titles too (WP-31 D2): t1title() .. r2title() are
    # rings 1 and 2, inside the legend's ring 3.  And after every text box
    # tagged ``ring=<n>`` with n <= the legend's ring (WP-31 D4, DECISIONS
    # A31): a title placed at ring(1) or ring(2) sits inside a ring 3
    # legend, one at ring(4) outside it.

    def _inside(m):
        if isinstance(m, Axis):
            return True
        tags = [str(t) for t in (getattr(m, "tags", None) or [])]
        if "dash_edge_title" in tags:
            return True
        for t in tags:
            if t.startswith("ring="):
                try:
                    return int(t[5:]) <= ring
                except ValueError:
                    return False
        return False
    at = 1 + max((i for i, m in enumerate(panel) if _inside(m)), default=-1)
    panel.insert(at, legend)
    setattr(fig, side, panel)
    legend.location = location


#: span (WP-32; BUGS.md "Five scheme keys are parsed and read by nothing"):
#: twoway places a spanned legend or title along its side on the whole
#: graph region (measured 19oct2026: centred on its width at 6 and 12, on
#: its height at 3 and 9, at a corner clock against its edge -- the
#: graph's margin in -- by the gap the box keeps from the plot region
#: without span; *sides* are the margin graph sides), where a
#: Bokeh side panel runs only the frame's length.  Where the frame sits in
#: the canvas only BokehJS knows once the axes are laid out, so this runs
#: on the figure's laid-out size (inner_width .. outer_height, which BokehJS
#: sets after every layout: load, a resize, a filter move that changes the
#: tick labels).  Each item is ``[model, kind, side, place, offset]``: a
#: Legend at its panel location *place* is given the numeric location that
#: puts its box at that place on the canvas along the side (BokehJS reads
#: a numeric location as px from the panel's left and bottom, anchored at
#: the box's bottom-left); a Title at its align *place* on a panel above or
#: below is given the align and offset that put it there on the canvas
#: (BokehJS offsets a left or right Title only, so a centred one is drawn
#: from its left edge).
_DASH_SPAN_JS = """
let pv = null;
try { pv = Bokeh.index.find_one(fig); } catch (e) { pv = null; }
if (pv == null || pv.bbox == null) { return; }
const W = pv.bbox.width, H = pv.bbox.height;
if (!(W > 0) || !(H > 0)) { return; }
const sd = (typeof sides !== "undefined" && sides) ? sides : [0, 0, 0, 0];
// The graph: the figure's canvas, or for a by() chrome cell (an item's
// sixth entry "grid") the by() grid's own box, the nearest GridBox above
// the cell, in canvas px.  The graph region is the graph less the margin
// graph sides (l, r, b, t, relative units of min(width, height)), which
// a spanned box is placed against.
// "panels": the by() grid's panels plus their axes (the union of its
// children not named dash_by_*) within that graph region, where twoway
// places by()'s legend and boxes without span.
// "panel": a by() panel's graph, as twoway draws it: from just left of its
// y labels to the graph's right margin (of the by() grid's size) past its
// frame.
const region = (ref) => {
  if (ref === "panel") {
    let b = pv.parent;
    while (b != null && !(b.model != null && b.model.type === "GridBox")) {
      b = b.parent;
    }
    let v = Math.min(W, H) / 100;
    if (b != null && b.el != null) {
      const q = b.el.getBoundingClientRect();
      if (q.width > 0 && q.height > 0) {
        v = Math.min(q.width, q.height) / 100;
      }
    }
    const fb = (pv.frame != null && pv.frame.bbox != null)
      ? pv.frame.bbox : null;
    const fx = fb != null ? fb.x1 : W;
    // Its left: 1.5 units left of its visible left axes' outer edge (the
    // y labels; twoway measured 48.2 of 3240, 42.9 of 2880, whatever the
    // labels' width), or the frame's left on a panel with no y axis.
    let ax = null;
    for (const [am, av] of (pv.renderer_views || [])) {
      if (am == null || !am.visible
          || !(pv.model.left || []).includes(am)
          || !String(am.type || "").endsWith("Axis")) { continue; }
      const ab = av != null ? av.bbox : null;
      if (ab == null || !(ab.width > 0)) { continue; }
      ax = ax == null ? ab.x0 : Math.min(ax, ab.x0);
    }
    const lx = ax != null ? ax - 1.5 * v : (fb != null ? fb.x0 : 0);
    // A first panel whose y labels sit at its canvas's edge has no room
    // for the box twoway starts 1.5 units left of them: the panel's left
    // border grows by what is missing (BUGS.md "A first panel's spanned
    // note started at its canvas's edge, not 1 unit left of its y
    // labels"), and the box is placed on the next layout.
    if (lx < -0.5 && fb != null) {
      const want = Math.ceil(fb.x0 - lx);
      const cur = pv.model.min_border_left != null
        ? pv.model.min_border_left : (pv.model.min_border || 0);
      if (want > cur) {
        pv.model.min_border_left = want;
        try { pv.invalidate_layout(); } catch (e) { /* next layout */ }
      }
    }
    return {L: lx, R: fx + (+sd[1] || 0) * v, T: 0, B: H, u: v};
  }
  let x0 = 0, y0 = 0, gw = W, gh = H, a = null, c = null;
  if (ref === "grid" || ref === "panels") {
    a = pv.parent;
    while (a != null && !(a.model != null && a.model.type === "GridBox")) {
      a = a.parent;
    }
    if (a == null || a.el == null || pv.canvas_view == null) { return null; }
    const g = a.el.getBoundingClientRect();
    c = pv.canvas_view.el.getBoundingClientRect();
    x0 = g.left - c.left; y0 = g.top - c.top; gw = g.width; gh = g.height;
    if (!(gw > 0) || !(gh > 0)) { return null; }
  }
  const u = Math.min(gw, gh) / 100;
  const r = {L: x0 + (+sd[0] || 0) * u, R: x0 + gw - (+sd[1] || 0) * u,
             T: y0 + (+sd[3] || 0) * u, B: y0 + gh - (+sd[2] || 0) * u, u,
             gw, gh};
  if (ref !== "panels") { return r; }
  let p = null;
  for (const k of (a.child_views || [])) {
    const nm = (k.model != null && k.model.name) || "";
    if (nm.startsWith("dash_by_") || k.el == null) { continue; }
    const b = k.el.getBoundingClientRect();
    if (!(b.width > 0) || !(b.height > 0)) { continue; }
    p = p == null ? {L: b.left, R: b.right, T: b.top, B: b.bottom}
      : {L: Math.min(p.L, b.left), R: Math.max(p.R, b.right),
         T: Math.min(p.T, b.top), B: Math.max(p.B, b.bottom)};
  }
  if (p == null) { return null; }
  const q = {L: Math.max(r.L, p.L - c.left), R: Math.min(r.R, p.R - c.left),
             T: Math.max(r.T, p.T - c.top), B: Math.min(r.B, p.B - c.top), u,
             pT: p.T - c.top, pB: p.B - c.top};
  return (q.R > q.L && q.B > q.T) ? q : null;
};
const at = (key, lo, len, size, mg) =>
  (key === "left" || key === "top") ? lo + mg
  : (key === "right" || key === "bottom") ? lo + len - mg - size
  : lo + (len - size) / 2;
for (const it of items) {
  const m = it[0], kind = it[1], side = it[2], place = it[3];
  if (kind === "bylabel") {
    // WP-41 BY-10: a by() panel label's box (dash_by_label_box).  Its one
    // tick sits at 0 and the colour mapper's range moves it along the bar:
    // at the left or right end less the inset it[4] (px), else centred.
    // Mode "span": the bar runs over the panel's graph, from left of its y
    // labels to its right margin (region "panel").
    const fb = (pv.frame != null && pv.frame.bbox != null)
      ? pv.frame.bbox : null;
    if (fb == null || !(fb.width > 0) || m.color_mapper == null) {
      continue;
    }
    const mode = it[7] || "";
    const pad = +m.padding || 0;
    let L = fb.x0, R = fb.x1, moved = false;
    if (mode === "span") {
      const gp = region("panel");
      if (gp != null) { L = Math.min(L, gp.L); R = Math.max(R, gp.R); }
      // Never past the panel's canvas, where it would be cut off.
      L = Math.max(L, 0);
      R = Math.min(R, W);
      const w = Math.max(1, Math.round(R - L - 2 * pad));
      if (m.width !== w) { m.width = w; moved = true; }
      const loc = [Math.round(L - fb.x0), 0];
      const cur = m.location;
      if (!Array.isArray(cur) || cur[0] !== loc[0] || cur[1] !== loc[1]) {
        m.location = loc;
        moved = true;
      }
    }
    const len = R - L - 2 * pad;
    if (!(len > 0)) { continue; }
    // BokehJS centres a horizontal bar's label on its tick whatever its
    // align, so an end-placed text is centred half its widest line in.
    let tw = 0;
    if (place === "left" || place === "right") {
      const ov = m.major_label_overrides;
      const txt = String((ov instanceof Map ? [...ov.values()]
                          : Object.values(ov || {}))[0] || "");
      try {
        const cx = document.createElement("canvas").getContext("2d");
        cx.font = [m.major_label_text_font_style || "normal",
                   m.major_label_text_font_size || "13px",
                   m.major_label_text_font || "helvetica"].join(" ");
        for (const ln of txt.split("\\n")) {
          tw = Math.max(tw, cx.measureText(ln).width);
        }
      } catch (e) { tw = 0; }
    }
    const ins = Math.min(0.5, Math.max(0, ((+it[4] || 0) + tw / 2) / len));
    const f = place === "left" ? ins : place === "right" ? 1 - ins : 0.5;
    const cm = m.color_mapper;
    if (Math.abs((+cm.low) + f) > 1e-6 || Math.abs((+cm.high) - (1 - f)) > 1e-6) {
      cm.low = -f;
      cm.high = 1 - f;
    }
    if (moved) {
      try { pv.invalidate_layout(); } catch (e) { /* next layout */ }
    }
    continue;
  }
  const g = region(it[5] || "");
  if (g == null) { continue; }
  let v = null;
  try { v = Bokeh.index.find_one(m); } catch (e) { v = null; }
  const pb = (v != null && v.layout != null) ? v.layout.bbox : null;
  if (kind !== "key" && (pb == null || !(pb.width > 0) || !(pb.height > 0))) {
    continue;
  }
  if (kind === "key" && v == null) { continue; }
  const across = side === "above" || side === "below";
  if (kind === "legend") {
    if (!m.visible || v.bbox == null || !(v.bbox.width > 0)) { continue; }
    // The keyword's own place first: across the side the box stays
    // where BokehJS puts it without span.
    if (m.location !== place) { m.location = place; }
    const b0 = v.bbox, lw = b0.width, lh = b0.height, mg = m.margin || 0;
    const norm = {top: "top_center", bottom: "bottom_center",
                  left: "center_left", right: "center_right",
                  center: "center_center"}[place] || place;
    const vy = norm.split("_")[0], hx = norm.split("_")[1];
    const left = across ? at(hx, g.L, g.R - g.L, lw, mg) : b0.left;
    const top = across ? b0.top : at(vy, g.T, g.B - g.T, lh, mg);
    // A numeric location is px from the panel's left and bottom, at the
    // box's bottom-left; the browser's own offsets are read back from
    // the box once and taken out.
    let want = [Math.round(left - pb.left), Math.round(pb.bottom - top - lh)];
    m.location = want;
    const b1 = v.bbox;
    if (b1 != null && b1.width > 0) {
      want = [Math.round(want[0] + left - b1.left),
              Math.round(want[1] - (top - b1.top))];
      m.location = want;
    }
  } else if (kind === "key") {
    // by()'s colour key drawn upright (BUGS.md "by(, clegend(pos(6)))
    // drew the colour key across the graph, where twoway draws it
    // upright"; measured 19oct2026).  Its eighth entry: "row" (6 or 12
    // o'clock: as long as the share it[4] of the by() grid's width, half
    // the graph's height less 0.1662 of its smaller side) or "hole" (in
    // an at() hole: from 1.455 units above its row's plot regions to
    // 2.44 below them, at its place across the hole).
    const gg = region("grid");
    if (gg == null) { continue; }
    const un = Math.min(gg.gw, gg.gh) / 100;
    const mode = it[7] || "";
    const pxOf = (fs) => {
      const t = String(fs || ""), n = parseFloat(t);
      return !(n > 0) ? 0 : /pt$/.test(t) ? n * 4 / 3 : n;
    };
    let len = 0, top = 0;
    if (mode === "hole") {
      let fr = null, a = pv.parent;
      while (a != null && !(a.model != null && a.model.type === "GridBox")) {
        a = a.parent;
      }
      const ct = pv.el.getBoundingClientRect().top;
      for (const k of (a != null ? (a.child_views || []) : [])) {
        const nm = (k.model != null && k.model.name) || "";
        if (nm.startsWith("dash_by_") || k.frame == null || k.el == null) {
          continue;
        }
        if (Math.abs(k.el.getBoundingClientRect().top - ct) > 1.5) {
          continue;
        }
        fr = k.frame.bbox;
        break;
      }
      if (fr != null) {
        top = fr.y0 - 1.455 * un;
        len = fr.y1 + 2.44 * un - top;
      } else {
        // No panel beside it (the stacked view): its own cell's height.
        const lp = pxOf(m.major_label_text_font_size);
        top = (+m.padding || 0) + lp;
        len = H - 2 * top;
      }
    } else if (mode === "side") {
      // 3 or 9 o'clock beside the panels: their box less 0.094 of the
      // graph's smaller side, centred on it (BUGS.md "by()'s colour key
      // at 3 o'clock ran the panels' whole height"; measured 19oct2026:
      // 2467.3 of a 2771.9 box at 3240, 2741.4 of 3079.8 at 3600).
      const pp = region("panels");
      if (pp == null) { continue; }
      len = (pp.pB - pp.pT) - 9.4 * un;
    } else {
      len = (+it[4] || 0) * gg.gw;
    }
    len = Math.max(20, Math.round(len));
    if (m.type === "Legend") {
      // A discrete key (BUGS.md "by()'s discrete colour key was as long
      // as its keys, not twoway's key"): its box is the key's length, its
      // keys spread along it by their spacing, read back from the box.
      // One key: its padding takes the length up instead.
      const lb = v.bbox, n = (m.items || []).length;
      if (lb == null || !(lb.height > 0) || n < 1) { continue; }
      let changed = false;
      if (n > 1) {
        const sp0 = +m.spacing || 0;
        const sp = Math.max(0, Math.round(sp0 + (len - lb.height) / (n - 1)));
        if (sp !== sp0) { m.spacing = sp; changed = true; }
      } else {
        const pd0 = +m.padding || 0;
        const pd = Math.max(0, Math.round(pd0 + (len - lb.height) / 2));
        if (pd !== pd0) { m.padding = pd; changed = true; }
      }
      if (changed) {
        try { pv.invalidate_layout(); } catch (e) { /* next layout */ }
      }
      continue;
    }
    // BokehJS lays a colour bar out again only with its plot.
    let moved = false;
    if (m.height !== len) { m.height = len; moved = true; }
    // BokehJS gives a centre-panel colour bar no height of its own to
    // read back (its bbox is the panel's), so its box is its length,
    // padding, title and the half label each end reaches past the bar.
    const pad = +m.padding || 0;
    const extra = 2 * pad + pxOf(m.major_label_text_font_size)
      + (m.title ? 1.3 * pxOf(m.title_text_font_size)
         + (+m.title_standoff || 0) : 0);
    if (mode === "side") {
      if (moved) {
        try { pv.invalidate_layout(); } catch (e) { /* next time */ }
      }
      continue;
    }
    if (mode !== "hole") {
      // The cell's height (a fixed height lays the grid out again, where
      // a frame height does not).
      const fh = Math.ceil(len + extra);
      if (fig.height !== fh) { fig.height = fh; }
      continue;
    }
    const bb = v.bbox;
    if (bb == null || !(bb.width > 0)) { continue; }
    {
      const mg = 5;
      const x = place === "left" ? mg : place === "right"
        ? W - mg - bb.width : (W - bb.width) / 2;
      // Its strip's foot at top + len: read back from the strip once it
      // is laid out (the box's padding and label overhang are below it).
      let foot = pad;
      const fv = v._frame_view;
      const cur0 = m.location;
      if (fv != null && fv.bbox != null && fv.bbox.height > 0
          && Array.isArray(cur0)) {
        foot = H - cur0[1] - fv.bbox.bottom;
      }
      const want = [Math.round(x), Math.round(H - (top + len) - foot)];
      const cur = m.location;
      if (!Array.isArray(cur) || cur[0] !== want[0] || cur[1] !== want[1]) {
        m.location = want;
        moved = true;
      }
    }
    if (moved) {
      try { pv.invalidate_layout(); } catch (e) { /* laid out next time */ }
    }
  } else if (kind === "title" && across) {
    const off = it[4] || 0;
    // An item's seventh entry: its text box's margin (relative units of
    // the graph's smaller side), kept inside the end it is placed at.
    const mg = (+it[6] || 0) * g.u;
    let align = place, offset = off;
    if (place === "left") {
      // Never left of its canvas, where it would be cut off (a panel's
      // box starts left of its y labels, BUGS.md "A spanned note or
      // caption on a by() panel sat at the panel box's end without its
      // margin").
      offset = Math.max(off + g.L - pb.left + mg, -pb.left);
    } else if (place === "right") {
      offset = off + pb.right - g.R + mg;
    } else {
      // The text's box: a Title's own bbox is its whole panel.
      let tw = 0;
      try { tw = v._get_size().width; } catch (e) { tw = 0; }
      if (!(tw > 0)) { continue; }
      align = "left";
      offset = (g.L + g.R - tw) / 2 - pb.left;
    }
    offset = Math.round(offset);
    if (m.align !== align) { m.align = align; }
    if (m.offset !== offset) { m.offset = offset; }
  }
}
"""

#: The laid-out sizes BokehJS sets on a figure after each layout.
_DASH_SPAN_KEYS = ("inner_width", "inner_height", "outer_width",
                   "outer_height")


def _dash_span(fig, model, kind=None, side="", place="", offset=0.0,
               ref="", margin=0.0, mode=""):
    """Place *model* along its side on the whole graph, as twoway's span
    places it (``_DASH_SPAN_JS``), or stop placing it (*kind* None).

    One callback per figure, on its laid-out size, holding ``[model,
    kind, side, place, offset]`` per model; a later call for the same
    model replaces its item.  *kind* is ``"legend"`` (*place* its panel
    location) or ``"title"`` (*place* its align, *offset* its own
    offset); *ref* ``"grid"`` places it on the by() grid that holds
    *fig* (a by() chrome cell) instead of *fig*'s canvas; *margin* (relative units of the graph's smaller
    side) is kept inside the end a left or right title is placed at;
    *kind* ``"key"`` draws by()'s colour key upright at twoway's length
    (*mode* ``"row"``, *offset* its share of the grid's width, or
    ``"hole"``); *model* None drops every item.  Both modes come through
    here."""
    from bokeh.models import CustomJS
    key0 = "change:" + _DASH_SPAN_KEYS[0]
    cb = next((c for c in fig.js_property_callbacks.get(key0, [])
               if getattr(c, "code", None) == _DASH_SPAN_JS), None)
    items = [] if cb is None or model is None else [
        it for it in cb.args.get("items", []) if it[0] is not model]
    if kind is not None:
        items.append([model, kind, side, place, float(offset or 0.0),
                      str(ref or ""), float(margin or 0.0), str(mode or "")])
    if cb is None:
        if items:
            cb = CustomJS(args={"fig": fig, "items": items,
                                "sides": _dash_span_sides(fig)},
                          code=_DASH_SPAN_JS)
            for k in _DASH_SPAN_KEYS:
                fig.js_on_change(k, cb)
        return
    if items:
        cb.args = dict(cb.args, items=items)
        return
    fig.js_property_callbacks = {
        k: [c for c in v if c is not cb]
        for k, v in fig.js_property_callbacks.items()}


def _dash_span_sides(fig, sides=None):
    """The margin graph sides ``[l, r, b, t]`` (relative units of min(W,
    H)) a spanned box on *fig* is placed against: *sides* when given (and
    then kept on the figure and handed to its span hook), else what
    :func:`_dash_graph_margin` kept, else the scheme's own
    (:attr:`SchemeParser.graph_margin_sides`)."""
    if sides is not None:
        fig._dash_graph_sides = [float(v) for v in sides]
        cb = next((c for c in fig.js_property_callbacks.get(
            "change:" + _DASH_SPAN_KEYS[0], [])
            if getattr(c, "code", None) == _DASH_SPAN_JS), None)
        if cb is not None:
            cb.args = dict(cb.args, sides=list(fig._dash_graph_sides))
        return list(fig._dash_graph_sides)
    kept = getattr(fig, "_dash_graph_sides", None)
    if kept is not None:
        return list(kept)
    sch = getattr(fig, "_dash_scheme", None)
    try:
        return [float(v) for v in (sch if sch is not None
                                   else SchemeParser.fallback())
                .graph_margin_sides]
    except (AttributeError, TypeError, ValueError):
        return [0.0, 0.0, 0.0, 0.0]


def _dash_span_keep(fig, kinds=None, ref=None, sides=None):
    """Keep only *fig*'s span items of *kinds* (all when None), placing
    each on *ref* when given (``"grid"``: the by() grid that holds *fig*)
    and against margin graph *sides* when given; the hook goes with its
    last item.  by() calls this on its panels and chrome cells."""
    cb = next((c for c in fig.js_property_callbacks.get(
        "change:" + _DASH_SPAN_KEYS[0], [])
        if getattr(c, "code", None) == _DASH_SPAN_JS), None)
    if cb is None:
        return
    items = [list(it) for it in cb.args.get("items", [])
             if kinds is None or it[1] in kinds]
    if ref is not None:
        for it in items:
            it[5:6] = [str(ref)]
    if not items:
        _dash_span(fig, None)
        return
    cb.args = dict(cb.args, items=items)
    if sides is not None:
        _dash_span_sides(fig, sides)


def _dash_span_move(fig, old, new):
    """Hand *old*'s span item, if it has one, to *new*: the model that
    replaces it in the figure (a title moved into its panel)."""
    cb = next((c for c in fig.js_property_callbacks.get(
        "change:" + _DASH_SPAN_KEYS[0], [])
        if getattr(c, "code", None) == _DASH_SPAN_JS), None)
    if cb is None:
        return
    items = [[new] + list(it[1:]) if it[0] is old else it
             for it in cb.args.get("items", [])]
    cb.args = dict(cb.args, items=items)


def _dash_textbox_span(fig, model, opts, side, clock=12):
    """title(), subtitle(), note() and caption() with span (WP-32): a box
    above or below the plot is placed on the whole graph, as twoway places
    it, through :func:`_dash_span`; without span nothing.  span beside
    nospan spans, in either order (measured 19oct2026).
    A box twoway draws beside the plot (*clock* 2-4 or 8-10), which dash
    draws on the nearer horizontal side (:func:`_dash_textbox_place`),
    keeps its place: twoway's span moves it along the plot's height only
    (BUGS.md "A spanned title is placed on the plot region")."""
    o = opts or {}
    if ("span" in o and side in ("above", "below")
            and clock not in (2, 3, 4, 8, 9, 10)):
        _dash_span(fig, model, "title", side,
                   str(getattr(model, "align", "") or "left"),
                   getattr(model, "offset", 0.0) or 0.0)


def _dash_scheme_chrome(scheme):
    """The legend's chrome and default placement from *scheme*, for both
    modes: the saved renderer's ``_rebuild_legend`` and the served app
    pass this dict to ``_dash_apply_legend``.

    The keys are Stata's legend box: ``color legend`` and ``color
    legend_line`` for the box, the ``key_label`` textbox's size and colour
    for the labels (not ``gsize text``, which the box used to take), and
    ``clockdir legend_position`` / ``numstyle legend_cols`` /
    ``numstyle legend_rows`` / ``gridringstyle legend_ring`` for where it
    sits when the user says nothing, and the key geometry (WP-31 D4).
    """
    return {
        "legend_bg_color": scheme.legend_bg_color,
        # None: the scheme draws no outline (meta, WP-32).
        "legend_border_color": (scheme.legend_border_color
                                if getattr(scheme, "legend_outline", True)
                                else None),
        "label_text_font_size": scheme.key_label_font_size,
        "label_text_color": scheme.key_label_color,
        "legend_position": getattr(scheme, "legend_position", None),
        "legend_cols": getattr(scheme, "legend_cols", None) or 0,
        "legend_rows": getattr(scheme, "legend_rows", 0) or 0,
        # WP-31 D4: the key geometry (relative units), the box's inner
        # and outer margins (px), the ring and the column-first switch.
        "legend_key_xsize": getattr(scheme, "legend_key_xsize", 13.0),
        "legend_key_ysize": getattr(scheme, "legend_key_ysize", 3.4722),
        "legend_key_gap": getattr(scheme, "legend_key_gap", 2.0833),
        "legend_row_gap": getattr(scheme, "legend_row_gap", 1.3888),
        "legend_col_gap": getattr(scheme, "legend_col_gap", 4.8611),
        "legend_margin": getattr(scheme, "legend_margin", 5),
        "legend_boxmargin": getattr(scheme, "legend_boxmargin", 5),
        "legend_ring": getattr(scheme, "legend_ring", 3),
        "legend_col_first": getattr(scheme, "legend_col_first", False),
        # WP-32: `yesno legend_span', legend(span)'s default.
        "legend_span": bool(getattr(scheme, "legend_span", False)),
    }


#: region()'s sub-options of legend() dash draws, and their twoway
#: minimum abbreviations (areastyle's options).
_DASH_LEGEND_REGION_NAMES = (("fcolor", "fc"), ("lcolor", "lc"),
                             ("lwidth", "lw"), ("lpattern", "lp"),
                             ("color", "color"), ("margin", "margin"))


def _dash_legend_margin_px(arg):
    """A marginstyle (a name or up to four numbers) as whole pixels, the
    largest side (Bokeh's ``padding`` and ``margin`` are one Int), or
    None for a value twoway would note (WP-31 D4)."""
    a = str(arg or "").strip().lower()
    if not a or len(a) > 64:
        return None
    sides = SchemeParser._MARGINSTYLES.get(a)
    if sides is not None:
        vals = []
        for v in sides:
            if isinstance(v, tuple):
                vals.append(float(v[1]))
            elif isinstance(v, str):
                vals.append(float(SchemeParser._MARGIN_LADDER.get(v, 0.0))
                            * OptionTranslator.PT_PER_RS)
            else:
                vals.append(float(v) * OptionTranslator.PT_PER_RS)
    else:
        nums = [OptionTranslator.stata_number(t) for t in a.split()]
        if not nums or len(nums) > 4 or any(n is None for n in nums):
            return None
        vals = [n * OptionTranslator.PT_PER_RS for n in nums]
    return max(0, min(500, int(round(max(vals) * OptionTranslator.PX_PER_PT))))


def _dash_legend_box(legend, calls, words):
    """legend()'s box and text sub-options on the series *legend* (WP-31
    D4): region() -> the border and fill, nobox -> neither, bmargin() ->
    Bokeh's ``margin``, region(margin()) -> ``padding``, color() -> the
    key text's colour, textwidth() -> ``label_width``, title() -> the
    legend's title above the keys.  Colours through Stata's colour
    grammar, sizes through ``OptionTranslator.resolve_size``; text stays
    a DOM text node (test_label_sinks.py)."""
    T = OptionTranslator

    def _note(where, value, what, using="the scheme's default"):
        # _dash_style_note's wording, nested one level deeper:
        # legend(region(lwidth(bogus))).
        shown = _dash_display(value)
        head = ("legend(%s(%s)))" % (where[:-1], shown)
                if where.endswith(")") else "legend(%s(%s))" % (where, shown))
        _dash_warn_once(("dash", "legend", where, str(value), what),
                        f"dash: {head} is not a recognised {what}; "
                        f"using {using}.")

    def _colour(raw, option):
        r = str(raw or "").strip()
        if T._means_no_color(r.lower()):
            return "none"
        hx, _a = T.parse_color_alpha(r, option)
        return hx

    for name, arg, typed in calls:
        if name == "region":
            for tok in _dash_by_tokens(str(arg or "").strip()):
                if "(" not in tok:
                    _dash_report_suboptions("legend(region)", [tok])
                    continue
                nm, inner = tok.split("(", 1)
                inner = inner[:-1] if inner.endswith(")") else inner
                nm = nm.strip().lower()
                full = next((f for f, mn in _DASH_LEGEND_REGION_NAMES
                             if f.startswith(nm) and len(nm) >= len(mn)),
                            None)
                where = "region(%s)" % nm
                if full in ("lcolor", "fcolor", "color"):
                    c = _colour(inner, "legend(%s)" % where)
                    if c is None:
                        continue
                    if full in ("lcolor", "color"):
                        legend.border_line_color = None if c == "none" else c
                    if full in ("fcolor", "color"):
                        legend.background_fill_color = (None if c == "none"
                                                        else c)
                elif full == "lwidth":
                    try:
                        legend.border_line_width = T.line_px(T.resolve_size(
                            inner, "line", 0.0))
                    except (ValueError, TypeError):
                        _note(where, inner, "line width")
                elif full == "lpattern":
                    try:
                        legend.border_line_dash = T.translate_lpattern(inner)
                    except (ValueError, TypeError):
                        _note(where, inner, "line pattern")
                elif full == "margin":
                    px = _dash_legend_margin_px(inner)
                    if px is None:
                        _note(where, inner, "margin")
                    else:
                        legend.padding = px
                else:
                    _dash_report_suboptions("legend(region)", [tok])
        elif name == "bmargin":
            px = _dash_legend_margin_px(arg)
            if px is None:
                _note(typed, arg, "margin")
            else:
                legend.margin = px
        elif name == "color":
            c = _colour(arg, "legend(%s)" % typed)
            if c and c != "none":
                legend.label_text_color = c
        elif name == "textwidth":
            try:
                legend.label_width = max(0, min(2000, int(round(
                    T.resolve_size(arg, "gap", 0.0) * T.PX_PER_PT))))
            except (ValueError, TypeError):
                _note(typed, arg, "size")
        elif name == "title":
            text, _sub = _parse_textbox_opt(str(arg or ""))
            lines = _textbox_lines(text)
            legend.title = "\n".join(lines)[:2000]
            legend.title_location = "above"
            legend.title_text_font_style = "normal"
            legend.title_text_font_size = legend.label_text_font_size
            legend.title_text_color = legend.label_text_color
            # The title's own color() and size(), as twoway draws them; a
            # name it does not know is noted and the default kept (WP-31
            # D16, tabs_legend_edges_truth.json nested.title_*).
            if _sub.get("color"):
                c = _colour(_sub["color"], "legend(title(color))")
                if c and c != "none":
                    legend.title_text_color = c
            if _sub.get("size"):
                try:
                    _base = float(str(legend.label_text_font_size)[:-2])
                except (TypeError, ValueError):
                    _base = 10.0
                try:
                    _pt = T.resolve_size(str(_sub["size"]), "text", _base)
                    if not 0 < _pt <= 1000:
                        raise ValueError("not a size")
                    legend.title_text_font_size = f"{round(_pt, 3):g}pt"
                except (ValueError, TypeError):
                    _note("title(size)", _sub["size"], "size")
    # The legend's own subtitle(): twoway draws it centred above the keys,
    # under the title (WP-31 D4b, legend_remainder_truth.json lsubtitle,
    # lall); a line of the title, in its style.
    for name, arg, typed in calls:
        if name != "subtitle":
            continue
        text, _sub = _parse_textbox_opt(str(arg or ""))
        lines = _textbox_lines(text)
        if not any(lines):
            continue
        head = str(legend.title or "")
        legend.title = ((head + "\n") if head else "") + "\n".join(lines)
        legend.title = legend.title[:2000]
        if not head:
            legend.title_location = "above"
            legend.title_text_font_style = "normal"
            legend.title_text_font_size = legend.label_text_font_size
            legend.title_text_color = legend.label_text_color
    if "nobox" in words and "box" not in words:
        legend.border_line_color = None
        legend.background_fill_color = None


def _dash_apply_legend(fig, plot_renderers, legend_opt, var_labels=None,
                       default_level=None, chrome=None, seen=None, key=""):
    """Stata's keys, Stata's drawing rule, and every legend() sub-option.

    ``twoway`` draws a legend if and only if the graph has two or more keys;
    ``legend(on)`` forces one, ``legend(off)`` removes it, and position(),
    ring(0), order(), size(), label(), lastlabel(), cols() and rows() are
    all documented in dash.sthlp.  Keys are Stata's plot numbers; order()
    text and label() resolve by number before order() selects, and
    lastlabel() applies last by drawn position (steps 1-2).  The saved renderer honoured all of them; the generated
    app had its own block that knew off, four bare keywords, label()
    and cols()/rows(), hard-coded a clickable legend and escaped the keys
    as HTML.  Measured: position(6) was below and horizontal when saved,
    top-right and vertical when served; order(2 1) did nothing served;
    size(small) was 7px saved and 11pt served; a one-series legend(on) was
    visible saved and hidden served.

    click_policy is deliberately left at Bokeh's default: nothing in the
    help promises a clickable legend, and Stata's legend is static.

    Args:
        fig:            The figure, every glyph already added.
        plot_renderers: ``[(plot_spec, [renderer, ...]), ...]`` in draw order.
        legend_opt:     The graph's legend() text, '' when absent.
        var_labels:     ``{varname: label}`` for the series keys.
        default_level:  The dashboard's level(), for a band's key.
        chrome:         ``_dash_scheme_chrome(scheme)``: the box colours,
                        the key_label size and colour, and the scheme's
                        default placement (clock, cols, rows), which
                        applies only when the user gave no position()
                        or ring().
    """
    from bokeh.models import LegendItem
    legend_opt = str(legend_opt or "")
    chrome = chrome or {}
    if default_level is None:
        default_level = _DEFAULT_LEVEL
    # Before the early return: a sub-option dash has no reading for is
    # dropped whether or not this figure has a legend to apply it to.
    _dash_report_suboptions("legend", _dash_legend_unsupported(legend_opt),
                            seen, key)
    if not fig.legend:
        # The mapper made none (a layer that drew nothing): there is
        # nothing to key.
        return

    # A discrete colorvar() builds its colour key as a Legend too.  It is
    # not a series key -- Stata suppresses it with clegend(), not legend()
    # -- so it is kept out of the rebuild and stays visible.
    cv_legends = [lg for lg in fig.legend
                  if str(getattr(lg, "name", "") or "") == _COLORVAR_LEGEND_NAME]
    plot_legends = [lg for lg in fig.legend if lg not in cv_legends]
    legend = plot_legends[0] if plot_legends else None

    # The sub-options, read as sub-options: never out of a quoted label.
    _words, _calls = _dash_legend_parts(legend_opt)

    # 1-2. The keys, rebuilt IN PLACE on the mapper's own legend, by
    #    Stata's plot number (a ci layer is two keys, band then line, and a
    #    layer that drew nothing still takes its number: _dash_legend_keys).
    #    Each key's text is resolved before anything is selected or moved
    #    (legend_options.sthlp:216-314): the default, then every
    #    label(# ...) by NUMBER (the last per number wins), then the text
    #    after a number in the LAST order().  order() then selects, repeats
    #    and orders the keys and inserts its `-' rows as LegendItems with no
    #    renderers; a repeated number shares one LegendItem.  lastlabel()
    #    is applied last, by the row's DRAWN position with a `-' row
    #    counting (text_truth.json l_lastlabel_pos, l_lastlabel_all and
    #    l_lastlabel_dash, measured 30sep2026), on a fresh LegendItem so a
    #    shared one is not renamed elsewhere.  A number that is no key is
    #    ignored, as twoway ignores it.  GAPS2 B5: order() was read as
    #    displayed positions with its text dropped, label() applied by
    #    position after the reorder, `-' rows dropped and lastlabel() only
    #    named.  Raw text: a LegendItem label is a DOM text node in
    #    BokehJS (test_label_sinks.py), never HTML.
    n_keys = None
    if legend is not None and plot_renderers:
        live = [(plot, [r for r in rends if r in fig.renderers])
                for plot, rends in plot_renderers]
        keys = _dash_legend_keys(live, var_labels or {}, default_level)
        # WP-31 C13: twoway's legend_g draws the keys of two plots that
        # look the same, neither given a style option of its own,
        # as ONE key, the first's, its text the plots' distinct texts
        # joined by "/" -- and a graph of one key draws no legend.  Two
        # histograms are one "Density" key in the one histogram colour, so
        # they draw none; color(red) on one keeps two keys; scatters of mpg
        # and price with pstyle(p1) are one key "Mileage (mpg)/Price"; an
        # explicit mcolor(red) on both, or msize(medium) on one, keeps two,
        # while mlabel() does not (legend_geometry_truth.json hist_only,
        # hist_color, hist_scales, merge_pstyle, merge_text, merge_override,
        # merge_default_value, merge_mlabel); an lfitci band and a qfitci
        # or lpolyci band are one "95% CI" key (series_label_truth.json
        # L02, F31).  The folded number is no
        # key: label(2 "B") changes nothing and order(2) draws none
        # (merge_lab2_on, merge_order2).  The merged item holds both
        # renderer lists, its numbers in its tags ("dash_key_numbers", ...).
        _folded = {}
        if keys:
            _plot_of, _pn = {}, 1
            for _pl, _r in live:
                _plot_of[_pn] = _pl
                # A nofit ci layer is one plot (WP-34 PIC-3).
                if _dash_ci_plot_count(_pl) == 2:
                    _plot_of[_pn + 1] = _pl
                    _pn += 2
                else:
                    _pn += 1
            _first, _kept, _ktexts = {}, [], {}
            for _n, _t, _rends in keys:
                _pl = _plot_of.get(_n) or {}
                _o = _pl.get("options") if isinstance(_pl.get("options"),
                                                      dict) else {}
                if any(str(_k).lower() in _DASH_KEY_STYLE_OPTS
                       and str(_v).strip() for _k, _v in _o.items()):
                    _kept.append((_n, _t, list(_rends)))
                    continue
                _sig = _dash_key_signature(_rends)
                if _sig in _first:
                    _k = _first[_sig]
                    _n0, _t0, _r0 = _kept[_k]
                    if _t not in _ktexts[_k]:
                        _ktexts[_k].append(_t)
                    _kept[_k] = (_n0, "/".join(_ktexts[_k]),
                                 list(_r0) + list(_rends))
                    _folded.setdefault(_n0, []).append(_n)
                    continue
                _first[_sig] = len(_kept)
                _ktexts[len(_kept)] = [_t]
                _kept.append((_n, _t, list(_rends)))
            keys = _kept
        if keys:
            n_keys = len(keys)
            texts = {n: [t] for n, t, _ in keys}
            for _name, _arg, *_ in _calls:
                if _name != "label":
                    continue
                lm = _DASH_LEGEND_LABEL_RE.fullmatch(_arg)
                if lm and int(lm.group(1)) in texts:
                    # label(1) with no text: twoway draws key 1's symbol
                    # with no text (WP-31 D4, legend_geometry_truth.json
                    # label_blank).
                    texts[int(lm.group(1))] = (
                        _textbox_lines(lm.group(2))
                        if lm.group(2) is not None else [""])
            _order = None
            for _name, _arg, *_ in _calls:
                if _name == "order":
                    _order = _arg
            entries = _dash_parse_legend_order(_order)
            for k, lines in entries:
                if k != "-" and k in texts and lines:
                    texts[k] = list(lines)
            items_by_n = {n: LegendItem(label={"value": "\n".join(texts[n])},
                                        renderers=rends)
                          for n, _, rends in keys}
            for _n, _more in _folded.items():
                items_by_n[_n].tags = ["dash_key_numbers"] + [
                    str(x) for x in [_n] + _more]
            if not entries:
                seq = [items_by_n[n] for n, _, _ in keys]
            else:
                seq = []
                for k, lines in entries:
                    if k == "-":
                        if lines:
                            seq.append(LegendItem(
                                label={"value": "\n".join(lines)},
                                renderers=[]))
                    elif k in items_by_n:
                        seq.append(items_by_n[k])
            for _name, _arg, *_ in _calls:
                if _name != "lastlabel":
                    continue
                lm = _DASH_LEGEND_LABEL_RE.fullmatch(_arg)
                if not lm or lm.group(2) is None:
                    continue
                pos = int(lm.group(1)) - 1
                if 0 <= pos < len(seq):
                    seq[pos] = LegendItem(
                        label={"value": "\n".join(
                            _textbox_lines(lm.group(2)))},
                        renderers=list(seq[pos].renderers))
            # holes(numlist): a blank key at each 1-based position of the
            # final sequence, counted with the holes before it (twoway's
            # legend_g counts holes among the n keys); a position past the
            # end is ignored, as twoway ignores holes(9) on three keys
            # (WP-31 D4, legend_geometry_truth.json holes, holes_big).
            # Each hole is a LegendItem with no renderers (S39 reads them).
            _holes = _dash_legend_arg(_calls, ("holes",))
            if _holes:
                try:
                    _hv, _hmany, _hbad = _dash_expand_numlist(
                        _holes.split(), limit=300)
                except (ValueError, TypeError, OverflowError):
                    _hv, _hmany, _hbad = [], True, True
                if not _hmany and not _hbad:
                    for _p in sorted({int(v) for v in _hv
                                      if math.isfinite(v) and v == int(v)
                                      and v > 0}):
                        if _p <= len(seq) + 1:
                            seq.insert(_p - 1, LegendItem(
                                label={"value": ""}, renderers=[]))
            legend.items = seq

    # 3. The scheme's chrome on EVERY legend, before the user's options so
    #    an explicit size() still wins.
    for lg in fig.legend:
        if chrome.get("legend_bg_color"):
            lg.background_fill_color = chrome["legend_bg_color"]
        if "legend_border_color" in chrome:
            # None: the scheme draws no outline (meta, WP-32).
            lg.border_line_color = chrome["legend_border_color"]
        # The key_label textbox's size and colour ("text_font_size" is the
        # older name of the same slot, kept for a caller-built dict).
        _lsize = (chrome.get("label_text_font_size")
                  or chrome.get("text_font_size"))
        if _lsize:
            lg.label_text_font_size = _lsize
        if chrome.get("label_text_color"):
            lg.label_text_color = chrome["label_text_color"]

    # 3b. The key geometry (WP-31 D4): the scheme's legend_key_xsize,
    #     legend_key_ysize, legend_key_gap and legend_row_gap (Stata's
    #     relative units, 2.88 pt each, 4/3 px per pt) and its box margins,
    #     then symxsize(), symysize(), keygap() and rowgap() (an unknown
    #     size is twoway's medium, with its note: legend_geometry_truth.json
    #     symx_bogus).  Every key box is twoway's key size, symxsize() by
    #     symysize(), a marker key's too (D39 D-31.a: the box no longer
    #     grows to 2.5 times the marker; Bokeh draws a legend marker at 0.4
    #     of the box, twoway at the marker's own size), so forcesize and
    #     noforcesize draw the same box (legend_options.sthlp).
    _T = OptionTranslator
    _lref = _T.size_ref_of(fig)

    def _px_units(units):
        try:
            u = float(units)
        except (TypeError, ValueError):
            u = 0.0
        if not math.isfinite(u):
            u = 0.0
        return max(0, int(round(u * _T.PT_PER_RS * _T.PX_PER_PT)))

    _geom = {}
    for _gname, _ckey, _dflt in (("symxsize", "legend_key_xsize", 13.0),
                                 ("symysize", "legend_key_ysize", 3.4722),
                                 ("keygap", "legend_key_gap", 2.0833),
                                 ("rowgap", "legend_row_gap", 1.3888),
                                 ("colgap", "legend_col_gap", 4.8611)):
        _units = chrome.get(_ckey, _dflt)
        _given = _dash_legend_arg(_calls, (_gname,))
        if _given:
            _typed = next((t for n, _a, t in _calls if n == _gname), _gname)
            try:
                _pt = _T.resolve_size(_given, "gap",
                                      float(_units) * _T.PT_PER_RS, _lref)
                _geom[_gname] = max(0, int(round(_pt * _T.PX_PER_PT)))
            except (ValueError, TypeError):
                _dash_style_note("legend(%s)" % _typed, _given, "size",
                                 "medium")
                _geom[_gname] = _px_units(3.8194)
        else:
            _geom[_gname] = _px_units(_units)
    for lg in plot_legends:
        _w, _h = _geom["symxsize"], _geom["symysize"]
        lg.glyph_width = max(1, _w)
        lg.glyph_height = max(1, _h)
        lg.label_standoff = _geom["keygap"]
        lg.spacing = _geom["rowgap"]
        try:
            lg.padding = int(chrome.get("legend_margin", 5))
            lg.margin = int(chrome.get("legend_boxmargin", 5))
        except (TypeError, ValueError):
            pass

    # 4. Placement (WP-31 D4): twoway's clock table and ring.  The clock is
    #    position(), else the scheme's `clockdir legend_position'; the ring
    #    ring(), else `gridringstyle legend_ring' (3).  position(0) is the
    #    centre of the plot region; ring(0) is inside the plot at the
    #    clock's inside location (s2color's 6: bottom_center); otherwise the
    #    legend goes to the clock's side panel, a corner clock at that end
    #    of the side (_DASH_CLOCK_PANEL_LOCATION), or where bplacement()
    #    puts it (legend_geometry_truth.json clock_0..clock_12,
    #    ring0_default, bplacement).  The bare words top, bottom, left and
    #    right are not placements: twoway refuses them, and so does
    #    dash.ado; one in a spec is named above, as a sub-option dash does
    #    not implement.  twoway's clockdir names are 0..12 as written: 13,
    #    06 and 3.0 draw the default (Stata prints twoway's note).
    m_pos = _dash_legend_arg(_calls, ("position",), r"([0-9]|1[0-2])")
    m_ring = _dash_legend_arg(_calls, ("ring",), r"(\d+)")
    try:
        _sclock = int(chrome.get("legend_position"))
    except (TypeError, ValueError):
        _sclock = None
    clock = int(m_pos.group(1)) if m_pos else (
        _sclock if _sclock is not None else 6)
    try:
        ring = (int(m_ring.group(1)) if m_ring
                else int(chrome.get("legend_ring", 3)))
    except (TypeError, ValueError):
        ring = 3
    _bp = _dash_legend_arg(_calls, ("bplacement",))
    _bploc = None
    if _bp:
        _bploc = _DASH_BPLACEMENT_LOCATION.get(_bp.strip().lower())
        if _bploc is None:
            _typed = next((t for n, _a, t in _calls if n == "bplacement"),
                          "bplacement")
            _dash_style_note("legend(%s)" % _typed, _bp, "compass direction",
                             "the default")
    colfirst = ("nocolfirst" not in _words
                and ("colfirst" in _words
                     or bool(chrome.get("legend_col_first"))))
    if legend is not None and (m_pos or m_ring or _sclock is not None):
        if m_pos and clock == 0:
            _dash_move_legend(fig, legend, "center", "center")
        elif ring == 0:
            _dash_move_legend(fig, legend, "center",
                              _DASH_CLOCK_INSIDE.get(clock, "bottom_center"))
        else:
            side = _DASH_CLOCK_SIDE.get(clock, "below")
            _dash_move_legend(
                fig, legend, side,
                _bploc or _DASH_CLOCK_PANEL_LOCATION.get(clock, "center"),
                ring)

    # 5. label(N "text") is applied by key number in step 1-2.  Raw: a
    #    LegendItem label is a DOM text node in BokehJS (legend.js:
    #    `div({class: label}, `${label}`)'), so escaping it only showed the
    #    entities (`R&amp;D'); the security of the whole legend rests on
    #    that text rendering, pinned in test_label_sinks.py.  The text after
    #    the key number is read with _textbox_lines: a compound string
    #    keeps the quotes it holds, each string is a line (the key's CSS is
    #    white-space: pre, so a newline breaks it), and bare words are one
    #    line (test_textbox_multiline.py TestALegendLabelIsReadAsStataReadsIt).

    # 6. The grid (WP-31 D4; legend_g.class:274-285): n keys (holes
    #    counted); rows() gives cols = 1 + int((n-1)/rows), cols() gives
    #    cols, neither the scheme's `numstyle legend_cols' (rows from
    #    `legend_rows' when only that is set, else 2 columns); then
    #    rows = 1 + int((n-1)/cols).  Both are set, as Bokeh takes them.
    #    rows() wins over cols() as twoway's does (WP-30 P1.19); each is a
    #    numlist of one positive integer (cols(2/2), cols(+2)).  The
    #    scheme's columns hold whatever the position (cols_with_pos: pos(3)
    #    keeps s2color's two columns).
    def _one_count(name):
        arg = _dash_legend_arg(_calls, (name,))
        if arg is None:
            return None
        try:
            vals, too_many, bad = _dash_expand_numlist(arg.split(), limit=2)
        except (ValueError, TypeError, OverflowError):
            return None  # twoway refuses it; dash.ado does (Stata side)
        if (not too_many and not bad and len(vals) == 1
                and math.isfinite(vals[0]) and float(vals[0]) == int(vals[0])
                and int(vals[0]) > 0):
            return int(vals[0])
        return None

    n_cols, n_rows = _one_count("cols"), _one_count("rows")
    try:
        _scols = int(chrome.get("legend_cols") or 0)
        _srows = int(chrome.get("legend_rows") or 0)
    except (TypeError, ValueError):
        _scols, _srows = 0, 0
    _n = len(legend.items) if legend is not None else 0
    if legend is not None and _n > 0 and (
            n_rows or n_cols or _scols or _srows or chrome):
        if n_rows:
            _gc = 1 + (_n - 1) // n_rows
        elif n_cols:
            _gc = n_cols
        elif _scols > 0:
            _gc = _scols
        elif _srows > 0:
            _gc = 1 + (_n - 1) // _srows
        else:
            _gc = 2
        _gc = max(1, min(_gc, 1000))
        legend.ncols = _gc
        legend.nrows = 1 + (_n - 1) // _gc
        # twoway fills its grid row by row, or column by column under
        # colfirst (legend_geometry_truth.json colfirst); Bokeh fills
        # row-first when horizontal and column-first when vertical, and a
        # one-column grid is the same either way.
        legend.orientation = ("vertical" if colfirst or _gc == 1
                              else "horizontal")
        # colgap() is the gap between columns (WP-31 D4b,
        # legend_remainder_truth.json colgap_zero): the keys of one row are
        # spaced by it.  A grid of rows and columns has one Bokeh spacing,
        # the row gap.
        if legend.nrows == 1 and _gc > 1 and _n > 1:
            legend.spacing = _geom["colgap"]
    elif legend is not None and colfirst:
        legend.orientation = "vertical"
    for lg in cv_legends:
        # A colour key keeps the rule it had: the one the user gave.
        try:
            if n_rows is not None:
                lg.nrows = n_rows
                lg.ncols = "auto"
            elif n_cols is not None:
                lg.ncols = n_cols
                lg.nrows = "auto"
        except (ValueError, AttributeError):
            pass

    # 7. size() on every legend, including a colour key: the user asked
    #    for a legend text size, not a plot-legend text size.
    m_size = _dash_legend_arg(_calls, ("size",), r"([^)]+?)")
    _size_typed = next((t for n, _a, t in _calls if n == "size"), "size")
    if m_size:
        # Stata's text units per legend (WP-30 P1.12a): *# multiplies each
        # legend's own size; an unknown name draws medium on every legend,
        # with the note, as twoway does.
        T = OptionTranslator
        _lref = T.size_ref_of(fig)
        _bad = False
        for lg in fig.legend:
            try:
                lg.label_text_font_size = T.css_pt(T.resolve_size(
                    m_size.group(1), "text",
                    T.css_to_pt(lg.label_text_font_size)
                    or T.size_medium_pt("text"), _lref))
            except (ValueError, TypeError):
                _bad = True
                lg.label_text_font_size = T.css_pt(T.size_medium_pt("text"))
        if not _bad and not list(fig.legend):
            try:
                T.resolve_size(m_size.group(1), "text",
                               T.size_medium_pt("text"), _lref)
            except (ValueError, TypeError):
                _bad = True
        if _bad:
            _dash_style_note("legend(%s)" % _size_typed, m_size.group(1),
                             "size",
                             "medium")

    # 7b. The box and its text (WP-31 D4): region(lcolor() fcolor()
    #     color() lwidth() lpattern() margin()), nobox/box, bmargin(),
    #     color(), textwidth() and title() on the series legend
    #     (legend_geometry_truth.json region, nobox, title).
    #     forcesize's partner noforcesize, bexpand and their no-forms are
    #     taken in silence.
    if legend is not None:
        _dash_legend_box(legend, _calls, _words)

    # 7c. span (WP-32): legend(span), else the scheme's `yesno
    #     legend_span' unless legend(nospan) undoes it; span beside
    #     nospan spans, in either order (measured 19oct2026).  A side-panel
    #     legend is placed along its side on the whole graph instead of
    #     the plot region (_DASH_SPAN_JS; measured 19oct2026: 6 and 12
    #     centred on the graph's width, 3 and 9 on its height, a corner at
    #     the graph's end); inside the plot (ring(0), position(0)) span
    #     changes nothing, as in twoway.  by() drops it (_dash_by_keys).
    if legend is not None:
        _side = next((s for s in ("below", "above", "left", "right")
                      if legend in list(getattr(fig, s))), None)
        _span = ("span" in _words
                 or ("nospan" not in _words
                     and bool(chrome.get("legend_span"))))
        if _span and _side is not None and isinstance(legend.location, str):
            _dash_span(fig, legend, "legend", _side, legend.location)
        else:
            _dash_span(fig, legend)

    # 8. Stata's rule governs the SERIES key; `off' is a bare word, so
    #    legend(pos(6) off) hides it and label(1 "Turned off") does not.
    #    A colour key stays visible.  The keys are counted before order():
    #    twoway draws legend(order(1)) on a two-key graph with its one row
    #    (axis_truth.json c_order1, text_truth.json l_order_beats_label)
    #    and no legend for order(1 - "Only") on a one-key graph (l_one_dash).
    forced_on = "on" in _words
    turned_off = "off" in _words and "on" not in _words  # on wins
    if n_keys is None:
        n_keys = len(legend.items) if legend is not None else 0
    show = not (turned_off or (n_keys < 2 and not forced_on))
    for lg in plot_legends:
        lg.visible = show
    for lg in cv_legends:
        lg.visible = True


# ---- Axis titles, ticks and secondary axes -----------------------------------

#: Stata's y-axis title for each histogram scale, measured by exporting
#: `twoway histogram mpg[, percent|frequency|fraction]' to SVG.
_DASH_HIST_YTITLES = {"density": "Density", "fraction": "Fraction",
                      "frequency": "Frequency", "percent": "Percent"}


def _dash_histogram_ymode(options):
    """The scale a histogram draws on: the first of Stata's four flags set,
    density when none is.  One rule for the bars AND the y title."""
    for flag in ("frequency", "percent", "fraction", "density"):
        if str((options or {}).get(flag, "")).strip():
            return flag
    return "density"


def _dash_axis_default_titles(plots, var_labels=None, yaxis=1, xaxis=1,
                              default_level=None):
    """``(x_title, y_title)``: the titles twoway draws by default on y axis
    *yaxis* and x axis *xaxis* (WP-30 P1.16).

    twoway titles an axis with the label of the first series drawn on it
    when the last series drawn on it has the same label, whatever lies
    between, and draws no title otherwise (measured: K01-K11 of
    test/fixtures/series_label_truth.json).  Each layer's series come from
    :func:`_dash_layer_series` (a ci fit is two, band then line); a layer
    counts on an axis when that axis's number is among its ``yaxis()`` /
    ``xaxis()`` numbers (1 when it names none).  Raw text, compared raw.
    Total: anything in *plots* that is not a dict is skipped.
    """
    ys, xs = [], []
    for plot in plots or ():
        if not isinstance(plot, dict):
            continue
        opts = (plot.get("options") if isinstance(plot.get("options"), dict)
                else {})
        series = _dash_layer_series(plot, var_labels, default_level)
        if _dash_is_horizontal(plot):
            # Each series read through its orientation (WP-30 P1.9a).
            series = [(s[1], s[0]) + tuple(s[2:]) for s in series]
        if str(yaxis) in (str(opts.get("yaxis", "1") or "1").split()
                          or ["1"]):
            ys.extend(s[0] for s in series)
        if str(xaxis) in (str(opts.get("xaxis", "1") or "1").split()
                          or ["1"]):
            xs.extend(s[1] for s in series)
    x = xs[0] if xs and xs[0] == xs[-1] else ""
    y = ys[0] if ys and ys[0] == ys[-1] else ""
    return x, y


def _dash_axis_labels(plots, graph_opts, var_labels, seen=None, key=""):
    """``(x_label, y_label)``: xtitle()/ytitle() first, else twoway's default.

    The default is twoway's first-equals-last rule over the series drawn on
    the first axes (:func:`_dash_axis_default_titles`, WP-30 P1.16), not
    the first layer's label: the label of the first series when the last
    series has the same label, else no title.  A histogram's y series is
    its scale word and a kdensity's ``kdensity <var>`` over ``x``.

    Canvas text, never html.escape'd: Bokeh draws an axis title as a glyph,
    so escaping made xtitle("R&D spend") read "R&amp;D spend" when served.
    """
    go, vl = graph_opts or {}, var_labels or {}
    x_default, y_default = _dash_axis_default_titles(plots, vl)
    # The text, split from its sub-options: xtitle("Weight", size(large))
    # used to title the axis "Weight, size(large)".  size() and color()
    # are applied by _dash_style_axis_titles; the rest is named.
    def _label(opt, default):
        # A typed "" removes the title (WP-28 B6); an option that gives only
        # sub-options -- ytitle(, size(large)), ytitle(,) -- keeps the
        # default and is styled by them, as twoway draws it (WP-29 P0.4);
        # suffix/prefix add lines to the default (WP-28 B3).
        return _dash_textbox_or_default(go.get(opt, ""), opt, default,
                                        seen, key)[0]

    return _label("xtitle", x_default), _label("ytitle", y_default)


def _dash_axis_tokens(head):
    """The tokens of one axis-label head: ``(kind, text)`` pairs in order
    (TR-14.2, WP-28 S14).

    ``"str"`` for a plain or compound string (:func:`_textbox_string_end`;
    an unclosed string runs to the end), *text* its content without
    quotes.  Everything else is split at a blank or a comma outside a
    string -- both are separators, so ``"2000,3000"`` and ``"2000 3000"``
    tokenize alike -- into ``"bare"`` tokens; a run with no separator
    inside it, ``"1(2)10"`` or the parenthesised piece of
    ``"2000 (500) 4000"``, survives as one longer token.

    Args:
        head: The numlist portion of an axis-label option (its leading
            rule and its sub-options already removed).

    Returns:
        A list of ``(kind, text)`` tuples.
    """
    out = []
    i, n = 0, len(head)
    while i < n:
        ch = head[i]
        if ch in " \t,":
            i += 1
            continue
        if ch == '"' or head.startswith('`"', i):
            start, end, after = _textbox_string_end(head, i)
            out.append(("str", head[start:end]))
            i = after
            continue
        j = i
        while j < n and head[j] not in " \t,\"" and not head.startswith('`"', j):
            j += 1
        if j == i:
            # A lone quote character _textbox_string_end did not open (an
            # unmatched backtick with no following '"'): one character, so
            # the scan always advances.
            j = i + 1
        out.append(("bare", head[i:j]))
        i = j
    return out


def _dash_axis_head_split(text):
    """``(head, tail)`` of one axis-label option's full raw value, split at
    the first comma outside a string that is followed by optional blanks
    and a letter or underscore -- Stata also accepts a comma inside the
    numlist itself, so only a comma that INTRODUCES A SUB-OPTION NAME
    separates (TR-14.2, WP-28 S14; the quote-aware twin of the regex the
    old parser used, which cut ``xlabel(1 "a, b" 2 "c")`` inside the
    string).

    Args:
        text: The option's whole raw value.

    Returns:
        ``(head, tail)``; *tail* is ``""`` when there is none, else keeps
        its own leading comma.
    """
    i, n = 0, len(text)
    while i < n:
        ch = text[i]
        if ch == '"' or text.startswith('`"', i):
            i = _textbox_string_end(text, i)[2]
            continue
        if ch == ",":
            j = i + 1
            while j < n and text[j] in " \t":
                j += 1
            if j < n and (text[j].isalpha() or text[j] == "_"):
                return text[:i], text[i:]
        i += 1
    return text, ""


#: a(b)c / a[b]c: the increment form, whitespace tolerated around the
#: parentheses (measured 25sep2026: twoway draws "2000 (500) 4000" and
#: "2000(500)4000" alike).
_DASH_AXIS_NUM = r"(-?(?:\d+\.?\d*|\.\d+)(?:[eE][-+]?\d+)?)"
_DASH_AXIS_INCR_RE = re.compile(
    r"\A" + _DASH_AXIS_NUM + r"\s*[(\[]\s*" + _DASH_AXIS_NUM
    + r"\s*[)\]]\s*" + _DASH_AXIS_NUM + r"\Z")
#: a/b: step +-1 toward b, inclusive.
_DASH_AXIS_SLASH_RE = re.compile(
    r"\A" + _DASH_AXIS_NUM + "/" + _DASH_AXIS_NUM + r"\Z")
#: a lone "y:z" token (the step comes from the value immediately before it).
_DASH_AXIS_COLON_RE = re.compile(
    r"\A" + _DASH_AXIS_NUM + ":" + _DASH_AXIS_NUM + r"\Z")


#: WP-34 DG-3: numlist's relative tolerance, 100 DBL_EPSILON (measured
#: 20oct2026 and 24oct2026, test/fixtures/numlist_truth.json).
_DASH_NUMLIST_TOL = 100.0 * 2.220446049250313e-16


def _dash_numlist_value(v):
    """The double Stata's numlist writes for *v* (WP-34 DG-3): the value
    as %15.0g text, read back (measured, numlist_truth.json): the fixed
    form for a decimal exponent e of -5 to 13, with 13 decimals when
    e < 0 and 12 - e (none past 12) otherwise; else the exponent form,
    8 mantissa decimals, 7 when |e| >= 100.  A value that is no finite
    number is returned as it is; -0 is 0."""
    try:
        v = float(v)
    except (TypeError, ValueError, OverflowError):
        return v
    if not math.isfinite(v):
        return v
    if v == 0.0:
        return 0.0
    e = int(("%.16e" % abs(v)).split("e")[1])
    if -5 <= e <= 13:
        d = 13 if e < 0 else max(0, 12 - e)
        return float("%.*f" % (d, v)) or 0.0
    return float(("%.8e" if abs(e) < 100 else "%.7e") % v)


def _dash_numlist_step(start, step, k):
    """``start + k*step`` as numlist makes it (WP-34 DG-3): 0 when its
    magnitude is below ``_DASH_NUMLIST_TOL * |start|`` (measured:
    -1(.250000000000002)1 writes 0), then :func:`_dash_numlist_value`."""
    v = start + step * k
    if abs(v) < _DASH_NUMLIST_TOL * abs(start):
        v = 0.0
    return _dash_numlist_value(v)


def _dash_expand_numlist(tokens, limit=None):
    """Expand one run of bare axis-label tokens by Stata's numlist forms
    ([U] 11.1.8; TR-14.1, WP-28 S14): a plain number; ``a/b`` (step +-1
    toward b, inclusive); ``a(b)c``/``a[b]c`` (from a by b while <= c for
    b > 0, >= c for b < 0, ``a + i*b`` never accumulated, inclusive within
    100 DBL_EPSILON of the count, as numlist counts); ``x y to z``/``x y:z``
    (also ``x y : z`` and ``y:z`` split from one token): step = y - x from
    the two values immediately before the word.  Each value is the double
    Stata's numlist makes (:func:`_dash_numlist_step`,
    :func:`_dash_numlist_value`; WP-34 DG-3), so a rule crossing zero
    makes exactly 0.

    Every count is found before any value of that span is made, and the
    whole run stops with *too_many* set the moment the running total
    would pass *limit* -- so ``0(0.000001)1000000`` costs one arithmetic
    check, never ten billion floats.  A zero step, a non-finite endpoint,
    a ``to``/``:`` with fewer than two values before it, or any other
    token goes to *bad*.

    Args:
        tokens: The run's bare token texts, in order (no blanks or commas
            inside any one of them: :func:`_dash_axis_tokens` already cut
            those).
        limit: The most ticks the whole run may produce; defaults to
            :data:`_MAX_AXIS_TICKS`.

    Returns:
        ``(values, too_many, bad)``: *values* a flat list of floats (not
        deduplicated or sorted), *bad* the tokens this run could not read.
        When *too_many* is true, *values* is empty: the caller keeps the
        axis's default ticks.
    """
    if limit is None:
        limit = _MAX_AXIS_TICKS
    # "2000 (500) 4000": blanks around the step (measured 25sep2026, probe
    # a1_spaces_incr: twoway draws it as 2000(500)4000) -- rejoin the
    # three tokens the blank-splitting tokenizer made.
    tokens = list(tokens)
    _j = 1
    while _j < len(tokens) - 1:
        _t = tokens[_j]
        if (len(_t) >= 3 and _t[0] in "([" and _t[-1] in ")]"
                and _t[0] + _t[-1] in ("()", "[]")):
            tokens[_j - 1:_j + 2] = [tokens[_j - 1] + _t + tokens[_j + 1]]
        else:
            _j += 1
    values = []
    bad = []
    too_many = False
    i, n = 0, len(tokens)

    def _reserve(count):
        nonlocal too_many
        if too_many or count < 0 or not math.isfinite(count):
            return False
        if len(values) + count > limit:
            too_many = True
            return False
        return True

    while i < n and not too_many:
        tok = tokens[i]
        if tok in ("to", ":"):
            if i + 1 >= n or len(values) < 2:
                bad.append(tok)
                i += 1
                continue
            try:
                z = float(tokens[i + 1])
            except (TypeError, ValueError):
                bad.append(tok)
                i += 1
                continue
            if not math.isfinite(z):
                bad.append(tok)
                i += 1
                continue
            y = values.pop()
            x = values.pop()
            step = y - x
            if step == 0 or not math.isfinite(step):
                values.extend([x, y])
                bad.append(tok)
                i += 2
                continue
            span = (z - y) / step * (1.0 + _DASH_NUMLIST_TOL)
            if not math.isfinite(span):
                values.extend([x, y])
                bad.append(tok)
                i += 2
                continue
            n_steps = max(0, int(math.floor(span)))
            if not _reserve(n_steps):
                values.extend([x, y])
                i += 2
                continue
            values.append(_dash_numlist_value(x))
            values.append(_dash_numlist_value(y))
            values.extend(_dash_numlist_step(y, step, k)
                          for k in range(1, n_steps + 1))
            i += 2
            continue
        m = _DASH_AXIS_INCR_RE.match(tok)
        if m:
            try:
                a, b, c = (float(m.group(1)), float(m.group(2)),
                           float(m.group(3)))
            except ValueError:
                bad.append(tok)
                i += 1
                continue
            if b == 0 or not all(math.isfinite(v) for v in (a, b, c)):
                bad.append(tok)
                i += 1
                continue
            span = (c - a) / b * (1.0 + _DASH_NUMLIST_TOL)
            if not math.isfinite(span):
                bad.append(tok)
                i += 1
                continue
            n_steps = max(0, int(math.floor(span)))
            if not _reserve(n_steps + 1):
                i += 1
                continue
            values.extend(_dash_numlist_step(a, b, k)
                          for k in range(n_steps + 1))
            i += 1
            continue
        m = _DASH_AXIS_SLASH_RE.match(tok)
        if m:
            try:
                a, b = float(m.group(1)), float(m.group(2))
            except ValueError:
                bad.append(tok)
                i += 1
                continue
            if not (math.isfinite(a) and math.isfinite(b)):
                bad.append(tok)
                i += 1
                continue
            step = 1.0 if b >= a else -1.0
            n_steps = int(math.floor(abs(b - a) + 1e-9))
            if not _reserve(n_steps + 1):
                i += 1
                continue
            values.extend(_dash_numlist_step(a, step, k)
                          for k in range(n_steps + 1))
            i += 1
            continue
        m = _DASH_AXIS_COLON_RE.match(tok)
        if m and values:
            x = values[-1]
            y, z = float(m.group(1)), float(m.group(2))
            step = y - x
            if step == 0 or not math.isfinite(step):
                bad.append(tok)
                i += 1
                continue
            span = (z - y) / step * (1.0 + _DASH_NUMLIST_TOL)
            if not math.isfinite(span):
                bad.append(tok)
                i += 1
                continue
            n_steps = max(0, int(math.floor(span)))
            if not _reserve(n_steps + 1):
                i += 1
                continue
            values.extend(_dash_numlist_step(y, step, k)
                          for k in range(n_steps + 1))
            i += 1
            continue
        try:
            v = float(tok)
        except (TypeError, ValueError):
            bad.append(tok)
            i += 1
            continue
        if not math.isfinite(v):
            bad.append(tok)
            i += 1
            continue
        if not _reserve(1):
            i += 1
            continue
        values.append(_dash_numlist_value(v))
        i += 1

    if too_many:
        return [], True, bad
    return values, False, bad


def _dash_parse_axis_label_opt(raw, unsupported=None):
    """Parse the numlist form of xlabel()/ylabel() (rebuilt on
    :func:`_dash_axis_tokens`/:func:`_dash_expand_numlist`, TR-14.3,
    WP-28 S14).

    A run of bare tokens between strings is expanded by
    :func:`_dash_expand_numlist`; a ``str`` token labels the last value
    that run produced, and a further consecutive ``str`` token joins it
    with ``"\\n"``; a string before any value is dropped and reported
    through *unsupported* (the caller's, e.g. :func:`_dash_parse_axis_spec`'s
    -- this function's own return stays ``(ticks, labels)``, so a caller
    that does not pass one, as the pinned unit tests do, sees only that).

    Supports a pure numeric list, ``"0 2 4 6"``, a labelled list,
    ``'0 "Zero" 5 "Five"'``, and every numlist form (``a/b``, ``a(b)c``,
    ``x y to z``, ``x y:z``, mixed, comma-separated).

    Args:
        raw: The numlist portion of the option.
        unsupported: An optional list a bad token, a too-many run (as its
            whole text) or a premature string is appended to.

    Returns:
        ``(ticks, labels)``: a sorted list of floats and a dict mapping
        ``str(float)`` to its label (empty when none were given).
    """
    if unsupported is None:
        unsupported = []
    ticks = []
    labels = {}
    run = []

    def _flush():
        if not run:
            return
        vals, too_many, bad = _dash_expand_numlist(run)
        unsupported.extend(bad)
        if too_many:
            unsupported.append(" ".join(run))
        else:
            ticks.extend(vals)
        run.clear()

    for kind, text in _dash_axis_tokens(str(raw or "")):
        if kind == "str":
            _flush()
            if not ticks:
                unsupported.append(text)
                continue
            key = str(ticks[-1])
            labels[key] = (labels[key] + "\n" + text) if key in labels else text
            continue
        run.append(text)
    _flush()
    return sorted(ticks), labels


def _dash_axis_too_many(head):
    """True when *head*'s numlist tokens would expand past
    :data:`_MAX_AXIS_TICKS` (TR-14.4, WP-28 S14): the same run-by-run
    reservation :func:`_dash_expand_numlist` makes, called ahead of
    :func:`_dash_parse_axis_label_opt` so the axis's default ticks are
    kept and the warning is issued the moment any one run would pass the
    bound, without materialising it."""
    run = []
    for kind, text in _dash_axis_tokens(str(head or "")):
        if kind == "str":
            if run:
                _, too_many, _ = _dash_expand_numlist(run)
                if too_many:
                    return True
                run = []
            continue
        run.append(text)
    if run:
        _, too_many, _ = _dash_expand_numlist(run)
        if too_many:
            return True
    return False


#: The most ticks one axis label option may ask for.  The ``a(b)c`` form
#: expanded every tick into a list: 10**7 ticks took 0.8 s and 1 GB, and
#: ``xlabel(0(0.000001)1000000)`` -- 10**12 -- never finished (measured
#: 23sep2026, WP-20).  Two thousand labels on one axis is past legible.
_MAX_AXIS_TICKS = 2000

#: WP-32 (BUGS.md "Found by the move-parity extension: axes of degenerate or
#: emptied layers after a move"): the extent of an axis whose layers draw
#: nothing, by scale kind, in the build, the served re-finish and the saved
#: page's finish (dash_axis_compute) alike, with no tick.  twoway draws such
#: a scale empty (measured 18oct2026: `twoway (lfit mpg weight if foreign
#: == 0) if price >= 10000' gives .xscale.curmin 1e300, curmax -1e300 and no
#: tick), which no Bokeh range can hold; a Range1d is used because the
#: saved page can write one in place after a move but cannot swap it for a
#: DataRange1d.  Nothing is drawn on it, so the numbers are never seen.
_DASH_EMPTY_SCALE = {"linear": (0.0, 1.0), "log": (1.0, 10.0)}


def _dash_hide_empty_axes(fig):
    """Hide every axis and grid of a figure that draws no plot.

    ``twoway, title(T)`` draws the plot region and the title and no axis,
    tick, label or grid (WP-35 plot:PT-4; command_grammar_truth.json
    empty.svg.title: no <line>, the text T alone); dash drew two black
    axes.  Called on the figure of a graph with no plot by both renderers
    (copied into the served app).
    """
    for model in (list(fig.axis) + list(fig.grid) + list(fig.xgrid)
                  + list(fig.ygrid)):
        model.visible = False

#: twoway's #N rule, as dash reproduces it (_dash_natscale_ticks).  An
#: uncovered stretch of data beyond the outermost tick costs twice a
#: stretch of axis beyond the data; a tick fewer or more than N costs
#: 0.37/N of the range; neither end's tick may leave more than 0.455 of a
#: step of data uncovered; two ticks must span the data; and at most N+1
#: ticks are drawn.  Fitted to test/fixtures/natscale_truth.json.
_DASH_NATSCALE_UNCOVERED = 2.0
_DASH_NATSCALE_DENSITY = 0.37
_DASH_NATSCALE_SIDE = 0.455
#: natscale's step counter is a 32-bit integer (_dash_natscale_ticks).
_DASH_NATSCALE_INT_LIMIT = 2.0 ** 31
#: The tag an axis's placeholder ticker carries while its #N ticks wait for
#: the drawn layers (_dash_finish_count_ticks); the count follows it.
_DASH_COUNT_TAG = "dash_count:"
#: WP-30 P1.3a: the second tag of the placeholder a DEFAULT axis carries
#: (_dash_default_ticker) -- an axis with no xlabel()/ylabel() rule, ticked
#: as twoway ticks it, ``#N`` for the scheme's numticks.
_DASH_DEFAULT_TAG = "dash_default"
#: WP-30 P1.3a: twoway's plot-region margin, ``margin twoway <style>``, in
#: relative units (% of min(W, H)): s2color's ``gsize *margin`` ladder,
#: which every shipped scheme inherits (scheme-s2color.scheme:195-204).
_DASH_MARGIN_RS = {"zero": 0.0, "tiny": 0.3, "vsmall": 0.6, "small": 1.2,
                   "medsmall": 2.2, "medium": 3.5, "medlarge": 5.0,
                   "large": 8.0, "vlarge": 12.0}
#: WP-30 P1.3a: by()'s size multiplier, grid.class ``scale_gmetric`` with
#: s2color's ``special by_knot1 3``, ``by_slope1 .3`` and ``by_slope2 1``
#: (knot, slope1, slope2): f(2) = f(3) = .85, f(6) = .8, f(10) = .6.
_DASH_BY_GMETRIC = (3.0, 0.3, 1.0)


def _dash_natscale_ticks(lo, hi, n):
    """The ticks twoway draws for ``#n`` over data running *lo* to *hi*.

    BUGS.md "ylabel(#N) and xlabel(#N) ticks fall where Bokeh puts them,
    not where twoway does": dash handed #N to Bokeh as desired_num_ticks,
    and ``ylabel(#5)`` on auto's mpg drew 15(5)40 where twoway draws
    10(10)40.  twoway's rule is tickset_g.class's ``set_ticks``: the
    builtin ``natscale`` over the axis's data minimum and maximum (the
    graph's own record equals ``_natscale min max N`` in all 264 axes
    measured), ticks from its minimum in steps of 1, 2 or 5 times a power
    of ten; ``#1`` is the minimum and the maximum; a range of one value
    gets that value less and plus one.  natscale is compiled and
    undocumented, so this is a model of it fitted to Stata's own answers
    (test/fixtures/natscale_truth.json): of all the candidate steps and
    end ticks, the one of least cost under the ``_DASH_NATSCALE_*`` terms.
    It agrees with 261 of the 264 drawn axes and 98.3% of 2,878 random
    ranges; where it differs, it is one tick more or fewer at an end.
    Where natscale's 32-bit step count overflows (data far from zero on a
    narrow range: 1e9 to 1e9+1) twoway draws the data's ends less and
    plus one, as here (72 of 72 measured cases).

    Returns a list of at most ``_MAX_AXIS_TICKS + 1`` floats, or None for
    a non-finite range or count.  Pure arithmetic: nothing here reads text.
    """
    try:
        lo, hi, n = float(lo), float(hi), int(n)
    except (TypeError, ValueError, OverflowError):
        return None
    if not (math.isfinite(lo) and math.isfinite(hi)):
        return None
    n = max(1, min(n, _MAX_AXIS_TICKS))
    if hi < lo:
        lo, hi = hi, lo
    if hi == lo:
        return [lo - 1.0, lo + 1.0]
    if n == 1:
        return [lo, hi]
    rng = hi - lo
    if not math.isfinite(rng) or rng <= 0:
        return [lo, hi]
    tol = 1e-9
    best = None
    z_lo = math.floor(math.log10(rng / (n + 2))) - 1
    z_hi = math.ceil(math.log10(rng)) + 1
    for z in range(z_lo, z_hi + 1):
        for m in (1, 2, 5):
            d = m * 10.0 ** z
            if not math.isfinite(d) or d <= 0:
                continue
            fl, fh = lo / d, hi / d
            if not (math.isfinite(fl) and math.isfinite(fh)):
                continue
            for j0 in sorted({math.floor(fl + tol), math.ceil(fl - tol)}):
                for j1 in sorted({math.floor(fh + tol), math.ceil(fh - tol)}):
                    k = j1 - j0 + 1
                    if k < 2 or k > n + 1:
                        continue
                    t0, t1 = j0 * d, j1 * d
                    ulo, uhi = max(0.0, t0 - lo), max(0.0, hi - t1)
                    if max(ulo, uhi) >= _DASH_NATSCALE_SIDE * d:
                        continue
                    if k == 2 and ulo + uhi > tol * rng:
                        continue
                    wide = max(0.0, lo - t0) + max(0.0, t1 - hi)
                    cost = ((_DASH_NATSCALE_UNCOVERED * (ulo + uhi) + wide)
                            / rng + _DASH_NATSCALE_DENSITY * abs(k - n) / n)
                    if best is None or cost < best[0] - 1e-12:
                        best = (cost, j0, j1, m, z)
    if best is None:
        return [lo, hi]
    _, j0, j1, m, z = best
    # natscale counts in 32-bit steps: past 2^31 steps of the power of ten
    # below its step from zero it overflows ("natscale fooled",
    # tickset_g.class), and twoway draws the data's ends less and plus
    # one -- `ylabel(#3)' over 1e9 and 1e9+1 is 999999999 and 1000000002
    # (72 cases measured 24sep2026, test/fixtures/natscale_axes_truth.json).
    _p = 10.0 ** z
    if _p > 0 and max(abs(lo), abs(hi)) >= _DASH_NATSCALE_INT_LIMIT * _p:
        return [lo - 1.0, hi + 1.0]
    scale = 10.0 ** z if z >= 0 else None
    out = []
    for j in range(j0, j1 + 1):
        # j*m/10**-z, not j*m*0.1**-z: 3*0.1 is 0.30000000000000004.
        v = j * m * scale if scale is not None else j * m / 10.0 ** (-z)
        out.append(float("%.15g" % v))
    return out


def _dash_count_ticker(count):
    """The placeholder ticker an axis with ``#count`` carries until
    :func:`_dash_finish_count_ticks` replaces it with twoway's ticks: Bokeh's
    choice of about *count*, which is what a figure never finished shows."""
    from bokeh.models.tickers import BasicTicker
    return BasicTicker(desired_num_ticks=int(count),
                       tags=[_DASH_COUNT_TAG + str(int(count))])


def _dash_default_ticker(count):
    """The placeholder a DEFAULT axis carries (WP-30 P1.3a): a FixedTicker
    with no ticks and no minor ticks, tagged as a ``#count`` placeholder
    (:func:`_dash_count_of` reads it) and as a default.  Its ticks are
    written in place by :func:`_dash_place_count_ticks` -- twoway's
    natscale ticks over every drawn layer -- at build and after every
    filter move.  *count* is clamped to 1.._MAX_AXIS_TICKS."""
    from bokeh.models.tickers import FixedTicker
    try:
        n = int(count)
    except (TypeError, ValueError, OverflowError):
        n = 5
    n = max(1, min(n, _MAX_AXIS_TICKS))
    return FixedTicker(ticks=[], minor_ticks=[],
                       tags=[_DASH_COUNT_TAG + str(n), _DASH_DEFAULT_TAG])


def _dash_margin_sides(text, start, scheme=None, short_in=4.0):
    """One ``margin()`` text applied over *start*, twoway's marginstyle
    grammar (WP-30 P1.20b; marginstyle.sthlp, style/margin-*.style).

    *start* is the current ``[left, right, bottom, top]`` in relative units
    (% of min(W, H)); returns ``(sides, noted)``.  The forms read: a style
    name (the 28 of ``SchemeParser._MARGINSTYLES``, through *scheme*'s
    ladder; ``#-pt`` sides are points over *short_in* inches); any other
    single word with no ``+ - =`` (``bogus``, ``l5``) gives zeros and
    *noted*, the text as typed (twoway's note; it draws such a text as
    zero, measured ``margin(bogus)``), a bare number the left side; and
    every other text is read token by token as margin.class reads it
    (WP-31 D11, below): numbers set left, right, bottom, top in turn
    (``1 2 3`` keeps the top, a fifth number is the left again), terms
    ``{l|r|b|t}{+|-|=}#`` edit a side in order (``l+5 l+5`` is
    ``l+10``), and ``L+10`` is ``L`` -- an unknown gsize, medium, with
    twoway's gsize note -- on the left and +10 on the right (measured).
    A term whose number is not one (dash.ado refuses it first, as twoway
    does, r(7)), a non-finite number or a text over 2,000 characters
    gives zeros and *noted*.  Linear in the text; only
    floats come out."""
    num = r"[0-9]*\.?[0-9]+(?:[eE][+-]?[0-9]{1,4})?"
    cur = [float(v) for v in start]
    raw = str(text if text is not None else "")
    t = raw.strip()
    if not t:
        return cur, None
    if len(t) > 2000:
        return [0.0] * 4, raw[:80]
    sch = scheme if scheme is not None else SchemeParser.fallback()
    named = sch.margin_sides(t) if hasattr(sch, "margin_sides") else None
    try:
        ref_pt = max(float(short_in), 1e-6) * 72.0
    except (TypeError, ValueError):
        ref_pt = 288.0
    if named is not None:
        return [v[1] / ref_pt * 100.0 if isinstance(v, tuple) else v
                for v in named], None
    words = t.split()
    if len(words) == 1 and not any(c in t for c in "+-="):
        # One word with no + - = is a style name to margin.class's
        # setstyle; a bare number stays dash's reading, the left side.
        if re.fullmatch(num, t) and math.isfinite(float(t)):
            cur[0] = float(t)
            return cur, None
        return [0.0] * 4, t[:80]
    # WP-31 D11: anything else as margin.class's setstyle reads it
    # (StataNow 19.5): the units rs pt in cm are hidden from the parse
    # characters; the text is split at blanks and at each of l r t b + -;
    # a side letter picks the side, + or - an operation, = clears it; a
    # value is set on the side (the side's value op # under an
    # operation) and the side moves on through left right bottom top,
    # then stays left.  A value without an operation is a gsize: a
    # number, a gsize name, or -- a name gsize does not know -- medium,
    # with twoway's note (measured: L+10 is left 3.8194, right +10).
    units = (("rs", "w"), ("pt", "x"), ("in", "y"), ("cm", "z"))
    s = t
    for u, ch in units:
        s = s.replace(u, ch)
    toks = [x for x in re.split(r"([ lrtb+\-])", s) if x and x != " "]
    letters = {"l": 0, "r": 1, "b": 2, "t": 3}
    side, ct, op = 0, 1, None

    def _split(tok):
        m = re.fullmatch("(" + num + ")([wxyz]?)", tok)
        return None if m is None else (float(m.group(1)), m.group(2))

    def _units_of(v, unit):
        # margin.class writes `=side op #'<unit>, the sum in the unit.
        per_in = {"x": 1.0 / 72.0, "y": 1.0, "z": 1.0 / 2.54}.get(unit)
        return v if per_in is None else v * per_in * 72.0 / ref_pt * 100.0

    for tok in toks:
        if tok in letters:
            side = letters[tok]
            continue
        if tok in ("+", "-", "="):
            op = None if tok == "=" else tok
            continue
        word = tok[1:] if (op is None and tok.startswith("=")) else tok
        sp = _split(word)
        if sp is not None and not math.isfinite(sp[0]):
            # WP-31 D11b: a number past double precision is Stata's
            # missing.  After + or - the side's sum is ".", a gsize twoway
            # does not know: medium, with its note; set alone it is zero,
            # silently (measured: region_remainder_truth.json
            # gmargin.l+1e400, gmargin.zero_l+1e400, gmargin.l=1e400).
            if op is not None:
                _dash_warn_once(
                    ("margin-gsize", "."),
                    "dash: named style . not found in class gsize, "
                    "default attributes used")
                cur[side] = (float(SchemeParser._GSIZE_PT["medium"][:-2])
                             / OptionTranslator.PT_PER_RS)
            else:
                cur[side] = 0.0
            op = None
            ct += 1
            side = ct - 1 if ct <= 4 else 0
            continue
        if op is not None:
            if sp is None:
                return [0.0] * 4, t[:80]
            n = cur[side] + sp[0] if op == "+" else cur[side] - sp[0]
            cur[side] = _units_of(n, sp[1])
        else:
            v = None if sp is None else _units_of(*sp)
            if v is None:
                for u, ch in units:
                    word = word.replace(ch, u)
                pt = SchemeParser._GSIZE_PT.get(word)
                if pt is None:
                    shown = _dash_display(word)
                    _dash_warn_once(
                        ("margin-gsize", shown),
                        f"dash: named style {shown} not found in class "
                        "gsize, default attributes used")
                    pt = SchemeParser._GSIZE_PT["medium"]
                v = float(pt[:-2]) / OptionTranslator.PT_PER_RS
            cur[side] = v
        op = None
        ct += 1
        side = ct - 1 if ct <= 4 else 0
    return cur, None


def _dash_plot_margin(scheme, graph_opts, panels=1, mult=None):
    """twoway's plot-region margin as fractions of the frame, per side:
    ``{"x": (left, right), "y": (bottom, top)}`` (WP-30 P1.3a, D1 b;
    per side since P1.20b, D-47a).

    twoway leaves r x min(W, H) between the plot region's edge and its
    scale on each side, r the scheme's ``margin twoway`` (2.2%; 0.6% in
    economist) edited by each ``plotregion(margin())`` copy in order
    (:func:`_dash_margin_sides`; an unknown text is noted once and drawn
    as zero, as twoway draws it), all times by()'s size multiplier
    f(*panels*) (grid.class ``scale_gmetric``; measured: ``by(foreign)
    plotregion(margin(b+10))`` draws (2.2 + 10)% x .85).  W and H are
    xsize()/ysize(), else the scheme's graphsize, else 5.5 x 4.  As
    fractions of the frame, x sides are r min(W,H)/W and y sides
    r min(W,H)/H, each clamped to [-0.45, 0.45] with an axis's two sides
    summing to at most 0.9 (D-47b): fixed at build, so a page drawn at
    another size is off twoway's by up to about 0.8% of its width (A6).
    Pure apart from the note: it reads no figure.

    WP-31 D10 (D-36.e): *mult*, when given, is by()'s whole multiplier
    -- f(k) x iscale(), :func:`_dash_by_size_mult` -- and replaces
    f(*panels*) (measured: by(g4, iscale(.5)) draws 2.2% x .50;
    by_remainder_truth.json ``margin_*``)."""
    go = graph_opts or {}
    sizes = []
    for raw in (go.get("xsize"), go.get("ysize"),
                getattr(scheme, "graphsize_x", None),
                getattr(scheme, "graphsize_y", None)):
        try:
            v = float(str(raw).strip()[:64]) if raw not in (None, "") \
                else None
        except (TypeError, ValueError, OverflowError):
            v = None
        sizes.append(v if v is not None and math.isfinite(v) and v > 0
                     else None)
    w = sizes[0] or sizes[2] or 5.5
    h = sizes[1] or sizes[3] or 4.0
    short = min(w, h)
    sides = getattr(scheme, "plot_margin_sides", None)
    if not sides:
        rs = getattr(scheme, "plot_margin_rs", 2.2)
        try:
            rs = float(rs)
        except (TypeError, ValueError):
            rs = 2.2
        if not math.isfinite(rs) or rs < 0:
            rs = 2.2
        sides = [rs] * 4
    sides = [float(v) for v in sides]
    raw_pr = str(go.get("plotregion") or "")
    if "m" in raw_pr.lower():
        table = _dash_region_table()
        for tok in _dash_by_tokens(_dash_by_tokens_commas(raw_pr)[0]):
            if "(" not in tok or _dash_subopt_canon(
                    tok.split("(", 1)[0].strip(), table) != "margin":
                continue
            arg = _dash_unquoted(_dash_subopt_arg(tok))
            sides, noted = _dash_margin_sides(arg, sides, scheme, short)
            if noted is not None:
                shown = _dash_display(noted)
                _dash_warn_once(
                    ("plot-margin", shown),
                    f"dash: named style {shown} not found in class margin, "
                    "default attributes used")
    try:
        g = max(1, int(panels))
    except (TypeError, ValueError, OverflowError):
        g = 1
    k1, b1, b2 = _DASH_BY_GMETRIC
    n = math.ceil(math.sqrt(g))
    f = 1.0 - (n - 1.0) / n * b1
    if n > k1:
        f -= (b2 - b1) * (n - k1) / n
    f = max(0.0, f)
    if mult is not None:
        try:
            m = float(mult)
        except (TypeError, ValueError, OverflowError):
            m = None
        if m is not None and math.isfinite(m) and m >= 0:
            f = m
    out = {}
    for letter, extent, pair in (("x", w, sides[0:2]), ("y", h, sides[2:4])):
        vs = []
        for rs in pair:
            v = rs / 100.0 * f * short / extent
            if math.isnan(v):
                v = 0.0
            vs.append(max(-0.45, min(0.45, v)))
        tot = vs[0] + vs[1]
        if tot > 0.9:
            vs = [v * 0.9 / tot for v in vs]
        out[letter] = (vs[0], vs[1])
    return out


def _dash_graph_margin(fig, scheme, graph_opts):
    """graphregion(margin()) as additions to *fig*'s ``min_border_*``
    (WP-31 D11, D-37.a): every copy's margin() read over the scheme's
    ``margin graph`` sides (:attr:`SchemeParser.graph_margin_sides`,
    medium) through :func:`_dash_margin_sides`, in relative units of
    min(W, H); each side's change from the scheme's is added in px of
    min(``fig.width``, ``fig.height``) at build (measured: twoway's plot
    box moves by the change times min(W, H), whatever xsize()/ysize()).
    Bokeh has no outer margin but ``min_border``, and the axis labels sit
    inside it, as inside twoway's graph region margin.  Adds, never
    assigns (S32's sizing and S33's outergap() share the borders); a side
    never goes below 0.  A graph without margin(), and every side it
    leaves, keeps ``min_border_* is None`` -- Bokeh's inherit-from-
    ``min_border`` state (DECISIONS A18).  A by() graph is left alone:
    its graph region holds the array, not one panel.  An unknown text is
    noted once and drawn as zero, as twoway draws it."""
    go = graph_opts or {}
    raw = str(go.get("graphregion") or "")
    if "m" not in raw.lower() or str(go.get("by") or "").strip():
        return
    sch = scheme if scheme is not None else SchemeParser.fallback()
    start = [float(v) for v in sch.graph_margin_sides]
    sides = list(start)
    table = _dash_region_table()
    short_in = OptionTranslator.size_ref_of(fig)
    for tok in _dash_by_tokens(_dash_by_tokens_commas(raw)[0]):
        if "(" not in tok or _dash_subopt_canon(
                tok.split("(", 1)[0].strip(), table) != "margin":
            continue
        arg = _dash_unquoted(_dash_subopt_arg(tok))
        sides, noted = _dash_margin_sides(arg, sides, sch, short_in)
        _dash_span_sides(fig, sides)
        if noted is not None:
            shown = _dash_display(noted)
            _dash_warn_once(
                ("graph-margin", shown),
                f"dash: named style {shown} not found in class margin, "
                "default attributes used")
    if sides == start:
        return  # no margin() change: every min_border_* stays (A18)
    w = getattr(fig, "width", None) or 0
    h = getattr(fig, "height", None) or 0
    short = float(min(w, h)) if w and h else 0.0
    if short <= 0:
        return
    follow = []
    for name, i in (("min_border_left", 0), ("min_border_right", 1),
                    ("min_border_bottom", 2), ("min_border_top", 3)):
        rel = sides[i] - start[i]
        add = rel / 100.0 * short
        if not math.isfinite(add) or abs(add) < 1e-9:
            continue  # an untouched side keeps None (inherits min_border)
        cur = getattr(fig, name)
        if cur is None:
            cur = fig.min_border or 0  # None until set (Bokeh 3.8)
        new = max(0, int(round(cur + add)))
        setattr(fig, name, new)
        follow.append([name, float(rel), int(new - cur)])
    if follow:
        # D39 D-37.a: the side follows a resize of the page -- twoway's
        # margin is the change times min(W, H) at any size -- through the
        # figure's drawn size (outer_width/outer_height, which BokehJS sets).
        from bokeh.models import CustomJS
        cb = CustomJS(args={"fig": fig, "sides": follow},
                      code=_DASH_GRAPH_MARGIN_JS)
        fig.js_on_change("outer_width", cb)
        fig.js_on_change("outer_height", cb)


#: graphregion(margin()) after a resize (D39 D-37.a): each side in *sides*
#: is ``[border name, change in relative units, px added so far]``; the
#: side takes the change times min(outer W, outer H) / 100 in place of what
#: was added before, so what other passes added to the border stays.
_DASH_GRAPH_MARGIN_JS = """
const w = fig.outer_width, h = fig.outer_height;
if (!(w > 0) || !(h > 0)) { return; }
const unit = Math.min(w, h) / 100;
for (const side of sides) {
  const want = Math.round(side[1] * unit);
  if (!isFinite(want) || want === side[2]) { continue; }
  const cur = fig[side[0]] == null ? 0 : fig[side[0]];
  const next = Math.max(0, cur - side[2] + want);
  side[2] = want;
  fig[side[0]] = next;
}
"""

def _dash_inner_box(fig):
    """The plot region's inner box on *fig* (WP-30 P1.20b), as twoway
    draws ``plotregion(istyle() icolor() ifcolor() ilstyle() ilcolor()
    ilwidth() ilpattern())``: one ``BoxAnnotation`` (tag
    ``dash_inner_box``, underlay) over the axes' hulls -- the scale before
    the margin, data and ticks (measured: ``plotregion(ifcolor(red))``
    fills 1760-5000 x 10-41 on auto's weight and mpg) -- styled by S38's
    region reader with each inner name read as its outer one, over the
    inner base: no fill, and the scheme's background colour at ``thin``
    for the outline (measured: ``ifcolor(red)`` alone outlines in s2color's
    #eaf2f3; ``ilcolor()`` alone draws no fill).  Created once, its edges
    rewritten from ``fig._dash_hull_entries`` each time
    :func:`_dash_hull_ranges` runs (build, by() sharing, the served
    re-finish); an axis with no hull keeps its edge.  Without an inner
    sub-option nothing is added and None is returned."""
    from bokeh.models import BoxAnnotation
    box = getattr(fig, "_dash_inner_box_model", None)
    if box is None:
        args = getattr(fig, "_dash_margin_args", None)
        go = (args[1] if args else None) or {}
        raw = str(go.get("plotregion") or "")
        if "i" not in raw.lower():
            return None
        inner = {"istyle": "style", "icolor": "color", "ifcolor": "fcolor",
                 "ilstyle": "lstyle", "ilcolor": "lcolor",
                 "ilwidth": "lwidth", "ilpattern": "lpattern"}
        table = _dash_region_table()
        mapped = []
        toks = _dash_by_tokens(_dash_by_tokens_commas(raw)[0])
        # WP-31 D11: marginonly posts none of the copy's box edits, the
        # inner box's included (measured: ifcolor(red) marginonly draws no
        # inner box); dash.ado cuts each copy that holds it before copies
        # merge, so here it is the one copy's.
        if any("(" not in t and _dash_subopt_canon(t.strip(), table)
               == "marginonly" for t in toks):
            return None
        for tok in toks:
            if "(" not in tok:
                continue
            full = _dash_subopt_canon(tok.split("(", 1)[0].strip(), table)
            arg = _dash_subopt_arg(tok)
            # istyle(none) leaves the inner box as it is (measured: with
            # ifcolor(red) it is filled and outlined as without it).
            if full == "istyle" and _dash_unquoted(arg).strip() == "none":
                continue
            if full in inner:
                mapped.append("%s(%s)" % (inner[full], arg))
        if not mapped and "istyle" not in raw.lower():
            return None
        T = OptionTranslator
        scheme = args[0] if args else None
        sch = scheme if scheme is not None else SchemeParser.fallback()
        ref_in = T.size_ref_of(fig)
        st, _named = _dash_region_spec(" ".join(mapped), "plotregion", {
            "fill": None, "fill_alpha": 1.0, "line": sch.background_color,
            "line_alpha": 1.0,
            "line_width": T.translate_lwidth("thin", ref_in=ref_in),
            "line_dash": []}, scheme, ref_in)
        box = BoxAnnotation(
            level="underlay", tags=["dash_inner_box"],
            fill_color=st["fill"] or "#ffffff",
            fill_alpha=(0.0 if st["fill"] is None else
                        float(1.0 if st["fill_alpha"] is None
                              else st["fill_alpha"])),
            line_color=st["line"] or "#ffffff",
            line_alpha=(0.0 if st["line"] is None else
                        float(1.0 if st["line_alpha"] is None
                              else st["line_alpha"])),
            line_width=float(st["line_width"] or 0.0),
            line_dash=list(st["line_dash"] or []),
            left=None, right=None, bottom=None, top=None)
        fig.add_layout(box)
        fig._dash_inner_box_model = box
    for h in getattr(fig, "_dash_hull_entries", None) or ():
        if h.get("name") != "default":
            continue
        lo, hi = float(h["lo"]), float(h["hi"])
        if not (math.isfinite(lo) and math.isfinite(hi)):
            continue
        for attr, v in ((("left", lo), ("right", hi)) if h["letter"] == "x"
                        else (("bottom", lo), ("top", hi))):
            if getattr(box, attr) != v:
                setattr(box, attr, v)
    return box


def _dash_by_numticks(scheme, graph_opts):
    """The default tick count of a graph's axes, ``{"x": n, "y": n}``
    (WP-30 P1.3a): the scheme's ``numticks_g`` (5 in every shipped
    scheme), one fewer on the first x and y axes of a by() graph's panels,
    as twoway's by() styles set them (bygraphstyle-default, -compact,
    -altleg and -econ.style: ``xlabels #4``, ``ylabels #4``; WP-34 AX-2:
    by_scales_truth.json x01-x05, ``scatter mpg length, by(foreign)``
    draws x 150 200 250, #4, where #5 is 140(20)240) -- fitted to twoway's
    own drawings (c02, c04, f01: by(foreign, yrescale) draws 10(10)40 on
    panels whose data run 12-34 and 14-41, where #5 is 10(5)35 and
    15(5)40 and #4 is 10(10)40 on both; f02's x2 is #5's 140(20)240,
    c17's y2 #5's 4000(2000)14000: the second axes keep the scheme's
    count, ``"x2"``/``"y2"``).  An explicit ``#N`` is N either way
    (c28)."""
    nx = getattr(scheme, "numticks_x", 5) or 5
    ny = getattr(scheme, "numticks_y", 5) or 5
    out = {"x": nx, "y": ny, "x2": nx, "y2": ny}
    if str((graph_opts or {}).get("by", "") or "").strip():
        out["x"] = max(1, nx - 1)
        out["y"] = max(1, ny - 1)
    return out


def _dash_count_of(ticker):
    """The count a placeholder from :func:`_dash_count_ticker` carries, or
    None.  Only a whole number of at most nine digits is read."""
    for t in (getattr(ticker, "tags", None) or ()):
        if isinstance(t, str) and t.startswith(_DASH_COUNT_TAG):
            digits = t[len(_DASH_COUNT_TAG):]
            if digits.isascii() and digits.isdigit() and len(digits) <= 9:
                return int(digits)
    return None


#: The Stata date kinds whose #N ticks come from _tsnatscale, and its unit
#: option for each (tickset_g.class set_ticks: d, w, m, q, h and y; %tc
#: and %tC take natscale).
_DASH_TS_UNITS = {"td": "d", "tw": "w", "tm": "m", "tq": "q", "th": "h",
                  "ty": "y"}


def _dash_unix_ms_to_unit(ms, unit):
    """The value of epoch milliseconds *ms* in a Stata date *unit* ("d",
    "w", "m", "q", "h" or "y"), with the fraction of the period elapsed;
    None outside Stata's dates."""
    try:
        ms = float(ms)
    except (TypeError, ValueError, OverflowError):
        return None
    if not (math.isfinite(ms) and _STATA_MS_MIN + _STATA_EPOCH_UNIX_MS
            <= ms <= _STATA_MS_MAX + _STATA_EPOCH_UNIX_MS):
        return None
    if unit == "d":
        return (ms - _STATA_EPOCH_UNIX_MS) / 86_400_000.0
    day = math.floor(ms / 86_400_000.0)
    frac_day = ms / 86_400_000.0 - day
    d64 = np.datetime64(int(day), "D")
    m64 = d64.astype("datetime64[M]")
    y = int(m64.astype("datetime64[Y]").astype(np.int64)) + 1970
    mon = int(m64.astype(np.int64)) - (y - 1970) * 12       # 0..11
    first = int(m64.astype("datetime64[D]").astype(np.int64))
    nxt = int((m64 + 1).astype("datetime64[D]").astype(np.int64))
