            "                        + list(getattr(_rr, '_dash_contour_sources', []))):",
            "                if _rs is not None and all(_rs is not _s for _s in _srcs):",
            "                    _srcs.append(_rs)",
            "        return _ly_src, _srcs",
            "",
            "    def _dash_table_copy(gname, frame, cols):",
            "        # A source of a data table's text over *frame*'s rows the",
            "        # document holds, with their labels (WP-31 H2t).",
            "        _f = frame[frame.index.isin(_EMBED_GROWS.get(gname, frame.index[0:0]))]",
            "        _d = {_DASH_TABLE_PREFIX + _v: _dash_column_values(",
            "                  _dash_embed_values(_f[_DASH_TABLE_PREFIX + _v],",
            "                                     _EMBED['need'].get(_DASH_TABLE_PREFIX + _v)))",
            "              for _v, _t in cols}",
            "        _d['index'] = list(_f.index)",
            "        return ColumnDataSource(_d)",
            "",
            "    def _dash_table_cols(g):",
            "        # [(var, title)] for a graph's data table (WP-31 H2t).",
            "        return [(_v, var_labels.get(_v) or _v) for _v in _dash_table_vars(g)",
            "                if _DASH_TABLE_PREFIX + _v in df.columns]",
            "",
            "    def _hover_cols_of(gname):",
            "        # The columns the tooltip reads -- the first layer's",
            "        # variables, which _dash_build_hover names, and the ones",
            "        # hover() asks for -- carried into every layer source.  The",
            "        # saved page draws every layer from one source holding every",
            "        # variable, so a layer of price on weight beside a scatter",
            "        # of mpg carried mpg there and not here, and the two modes",
            "        # gave the layer different tooltips.",
            "        for _gx in graphs:",
            "            if _gx.get('graph_options', {}).get('name', '') == gname.split('__by__')[0]:",
            "                _raw = (_gx.get('graph_options', {}).get('hover', '') or '').strip()",
            "                _p0 = (_gx.get('plots') or [{}])[0] or {}",
            "                _tip = [_p0.get(_k, '') for _k in ('xvar', 'yvar', 'yvar1', 'yvar2', 'zvar')]",
            "                # A data table's text columns ride along (WP-31 H2t).",
            "                _tbl = ([_DASH_TABLE_PREFIX + _v for _v in _dash_table_vars(_gx)]",
            "                        if str(_gx.get('graph_options', {}).get('table', '') or '').strip()",
            "                        else [])",
            "                return [_c for _c in dict.fromkeys(_tip + _raw.split() + _tbl)",
            "                        if _c and _c in df.columns]",
            "        return []",
            "",
            "    def _dash_redraw_for(g, plot, pi, gname, cv_domain=None):",
            '        """A closure that redraws one layer from a frame the callback hands it.',

            "        The frame arrives filtered and, for a by() panel, masked to",
            "        the panel's group.  The layer's own if()/in() is applied",
            "        here, so a qualified fit stays qualified after a filter",
            "        move.  Drawn on a throwaway figure with no linking, because",
            "        only the DATA the mapper produces is wanted.",
            '        """',
            "        _go = g.get('graph_options', {})",
            "        _g_if = (_go.get('if_expr') or g.get('if_expr') or '').strip()",
            "        _g_in = (_go.get('in_expr') or g.get('in_expr') or '').strip()",
            "        _p_if = (plot.get('if_expr') or '').strip()",
            "        _p_in = (plot.get('in_expr') or '').strip()",
            "        # The columns Stata filled, in a spec dash.ado wrote.",
            "        _g_qc = str(g.get('qual_col') or '')",
            "        _p_qc = str(plot.get('qual_col') or '')",
            "        _g_q = _dash_qual_mask(g, _qual_masks)",
            "        _p_q = _dash_qual_mask(plot, _qual_masks)",
            "        _sidx = _dash_plot_style_indices(",
            "            g.get('plots', []),",
            "            _dash_pcycle(g.get('graph_options', {})))[pi]",
            "        # The literal family draws from its own values, which no",
            "        # qualifier reaches, as in twoway and the live figure.",
            "        _p_lit = (str(plot.get('type', '') or '').lower()",
            "                  in _DASH_LITERAL_TYPES)",
            "        # WP-29 P0.16: the build's colour rows, so a redrawn copy",
            "        # keeps the key's bins (BR-07.4), never the moved frame's.",
            "        _cv_dom = cv_domain",
            "        # The live figure's axis kinds, by the same calls it made",
            "        # (WP-29 P0.8): a date layer on a mixed numeric axis redraws",
            "        # in Stata units, one on a date axis at its dates.",
            "        _rax = _dash_axis_vars(g.get('plots', []))",
            "        _rax2 = _dash_axis_vars(g.get('plots', []), axis_no=2)",
            "        _rkinds = (_dash_figure_date_kind(g.get('plots', []), 'xvar',",
            "                                          _rax[0], _date_vars),",
            "                   _dash_figure_date_kind(g.get('plots', []), 'yvar',",
            "                                          _rax[1], _date_vars),",
            "                   _dash_figure_date_kind(g.get('plots', []), 'xvar',",
            "                                          _rax2[0], _date_vars, 2),",
            "                   _dash_figure_date_kind(g.get('plots', []), 'yvar',",
            "                                          _rax2[1], _date_vars, 2))",
            "        def _qual(frame):",
            "            # The graph's qualifier, then the layer's own where it",
            "            # differs -- the same two steps the live figure took.",
            "            # An `in' counts the dataset's observations, never the",
            "            # rows a filter or the graph's qualifier left in frame.",
            "            _fr = _dash_layer_frame(df, frame, _g_if, _g_in,",
            "                                    'graph %r' % gname, qual=_g_q)",
