            "                    (_p_if and _p_if != _g_if) or (_p_in and _p_in != _g_in)",
            "                    or (_p_qc and _p_qc != _g_qc)):",
            "                _fr = _dash_layer_frame(df, _fr, _p_if, _p_in,",
            "                                        'graph %r plot %d' % (gname, pi + 1),",
            "                                        qual=_p_q)",
            "            return _fr",
            "        # WP-41 BY-28: a by() contour panel, cut after a move at the",
            "        # first panel's kept range (_dash_by_first_zranges); the cuts",
            "        # then follow the kept rows, so Stata's build cuts are dropped.",
            "        def _redraw(frame, zrange=None):",
            "            _fr = _qual(frame)",
            "            _plot_d = plot",
            "            _po = plot.get('options') or {}",
            "            if isinstance(_po, dict) and (zrange is not None or any(",
            "                    _k in _po for _k in ('_dash_by_zrange', '_dash_by_zcuts'))):",
            "                _o = {_k: _v for _k, _v in _po.items()",
            "                      if _k not in ('_dash_by_zrange', '_dash_by_zcuts')}",
            "                if isinstance(zrange, (list, tuple)) and len(zrange) == 2:",
            "                    _o['_dash_by_zrange'] = list(zrange)",
            "                _plot_d = dict(plot, options=_o)",
            "            _tfig = bokeh_figure()",
            "            _dash_mark_date_axes(_tfig, *_rkinds)",
            "            _n_obs0 = getattr(_dash_cur_mapper(), 'n_obs', None)",
            "            _dash_cur_mapper()._set_graph_n_obs(g)",
            "            _ly, _srcs = _dash_draw_layer(_tfig, _fr, _plot_d, pi, gname,",
            "                                          set(), None, None, sidx=_sidx,",
            "                                          cv_domain=_cv_dom)",
            "            _dash_cur_mapper().n_obs = _n_obs0",
            "            _out = [_s for _s in _srcs if _s is not _ly]",
            "            # WP-31 D5: the weighted sizes at the graph's scale().",
            "            _dash_scale_columns(_out, _dash_scale_factor(_go))",
            "            # WP-31 B4d: a contour's redrawn levels and its key's",
            "            # ticks ride on the first source, for the live key.",
            "            for _rr in _tfig.renderers:",
            "                if _out and hasattr(_rr, '_dash_contour_sources'):",
            "                    _kb = getattr(_rr, '_dash_contour_bar', None)",
            "                    _out[0]._dash_ckey = (",
            "                        list(_rr.levels),",
            "                        list(getattr(_kb.ticker, 'ticks', None) or [])",
            "                        if _kb is not None else [],",
            "                        dict(_kb.major_label_overrides or {})",
            "                        if _kb is not None else {})",
            "            # WP-32: a fit drawn from Stata's points over fewer rows",
            "            # than Stata's sample is stale; the page says so.",
            "            if _out:",
            "                _out[0]._dash_points_stale = any(",
            "                    getattr(_rr, '_dash_points_stale', False)",
            "                    for _rr in _tfig.renderers)",
            "                # WP-32: what the layer evaluates, for the live hull.",
            "                _evs = [getattr(_rr, '_dash_eval_extent', None)",
            "                        for _rr in _tfig.renderers]",
            "                _evs = [_e for _e in _evs if isinstance(_e, dict)]",
            "                _out[0]._dash_eval_v = (list(_evs[0]['source'].data.get('v', []))",
            "                                        if _evs else [])",
            "            return _out",
            "        def _redraw_one(frame, zrange=None):",
            "            return _dash_under_graph_scheme(g, _redraw, frame, zrange)",
            "        def _zrange_of(frame):",
            "            # The layer's qualified rows, as the redraw reads them; a",
            "            # qualifier's notes are the redraw's own.",
            "            with warnings.catch_warnings():",
            "                warnings.simplefilter('ignore')",
            "                return _dash_contour_zrange_of(_qual(frame), plot, _date_vars)",
            "        _redraw_one.zrange = _zrange_of",
            "        return _redraw_one",
            "",
            "    def _dash_figure_for(g, gname, g_df, _fac_label=None,",
            "                         _rescale=frozenset()):",
            '        """Build one figure: a graph, or one by() panel of it.',

            "        This is the body of what used to be the per-graph loop.",
            "        The by() panels used to be drawn by two REDUCED copies",
            "        of it -- eighteen plot types, hardcoded marker sizes,",
            "        no hover, Bokeh's default legend -- and the other twenty",
            "        types fell off the end of them and drew nothing.  One",
            "        body, called once per panel, is the only way the panels",
            "        can be the graph.",
            '        """',
            "        go = g.get('graph_options', {})",
            "        # zlabel()/ztitle()/zscale() (GAPS2 X2): read once per",
            "        # figure so _apply_colorvar draws them on this graph's",
            "        # colour key; reset after the layer loop below.",
            "        _dash_cur_mapper().z_options = {k: go.get(k, '')",
            "                                  for k in ('zlabel', 'ztitle', 'zscale',",
            "                                            'clegend', 'plegend')}",
            "        _dash_cur_mapper().z_context = (_reported_subopts, gname)",
            "        _dash_cur_mapper()._set_graph_n_obs(g)",
            "        _src_list = graph_sources.get(gname)",
            "        src = (_src_list[-1] if isinstance(_src_list, list) and _src_list else _shared_of.get(gname))",
            "        # ---- Per-graph if_expr / in_expr filtering ----",
            "        # Read from graph_options first; fall back to top-level graph key",
            "        # so that qualifiers set by dash.ado at the graph level are honoured.",
            "        _g_if = (go.get('if_expr') or g.get('if_expr') or '').strip()",
            "        _g_in = (go.get('in_expr') or g.get('in_expr') or '').strip()",
            "        # g_df arrives QUALIFIED from the caller: the graph's own",
            "        # rows, or one by() panel's share of them.  It is not",
            "        # re-qualified here -- `in 3/5' is not idempotent.",
            "        # The graph's own rows, before any per-LAYER qualifier",
            "        # narrows them further.  Each layer starts from here.",
            "        _g_df_graph = g_df",
            "",
            "        plots = g.get('plots', [])",
            "        _pstyle_idx = _dash_plot_style_indices(plots, _dash_pcycle(go))",
            "        xv = plots[0].get('xvar', '') if plots else ''",
            "        yv = plots[0].get('yvar', '') if plots else ''",
            "        # The axes' variables: a univariate first layer's is on x",
            "        # (WP-29 P0.8), as the saved renderer reads them.",
            "        _xa, _ya = _dash_axis_vars(plots)",
            "        _xa2, _ya2 = _dash_axis_vars(plots, axis_no=2)",
            "        # Canvas text, through the helper the saved renderer runs:",
            "        # this used to html.escape the user's title and to title a",
            "        # histogram's y axis with the variable, where the saved",
            "        # figure titled it nothing and Stata writes 'Density'.",
            "        x_label, y_label = _dash_axis_labels(plots, go, var_labels,",
            "                                             _reported_subopts, gname)",
            "",
            "        # The rows this figure draws, not the dataset's (WP-36 DG-14).",
            "        n_rows = len(g_df)",
            "        backend = 'webgl' if n_rows > _WEBGL_THRESHOLD else 'canvas'",
            "        _fig_kw = dict(",
            "            title=_parse_textbox_opt(go.get('title', '') or '')[0],",
            "            x_axis_label=x_label,",
            "            y_axis_label=y_label,",
            "            tools=_DASH_FIGURE_TOOLS,",
            "            sizing_mode='stretch_width',",
            "            output_backend=backend,",
            "        )",
            "        # xsize()/ysize()/aspectratio(): the helper the saved",
            "        # renderer runs.  This read aspectratio() alone, uninverted,",
            "        # and said nothing for a bad value the saved renderer named.",
            "        # With none given, the scheme's own graphsize ratio, as the",
            "        # saved figure (_resolve_aspect_ratio) -- a served figure",
            "        # used to ignore the scheme's proportions entirely -- held",
            "        # to the same height bounds so a wide page stays scrollable.",
            "        _ar = _dash_figure_aspect(go, _SCHEME_GRAPHSIZE_X, _SCHEME_GRAPHSIZE_Y)",
            "        if _ar is None and _SCHEME_GRAPHSIZE_X and _SCHEME_GRAPHSIZE_Y:",
            "            _ar = float(_SCHEME_GRAPHSIZE_X) / float(_SCHEME_GRAPHSIZE_Y)",
            "        if _ar is not None:",
            "            _fig_kw['aspect_ratio'] = _ar",
            "            _fig_kw['max_height'] = _MAX_FIGURE_HEIGHT",
            "            _fig_kw['min_height'] = _MIN_FIGURE_HEIGHT",
            "        _xsc = _dash_scale_spec(go.get('xscale', ''), 'xscale', _reported_subopts, gname)",
            "        _ysc = _dash_scale_spec(go.get('yscale', ''), 'yscale', _reported_subopts, gname)",
            "        # A date axis, by the saved renderer's rule and in its words:",
            "        # every layer's x (or y) a date variable of one kind.  The",
            "        # served figure used to draw every date on a numeric axis.",
            "        _x_date = _dash_figure_date_kind(plots, 'xvar', _xa, _date_vars)",
            "        _y_date = _dash_figure_date_kind(plots, 'yvar', _ya, _date_vars)",
            "        _x2_date = _dash_figure_date_kind(plots, 'xvar', _xa2, _date_vars, 2)",
            "        _y2_date = _dash_figure_date_kind(plots, 'yvar', _ya2, _date_vars, 2)",
            "        _xs_log, _ys_log = _xsc['log'], _ysc['log']",
            "        if _x_date and _xs_log:",
            "            warnings.warn(",
            "                f\"dash: xscale(log) is meaningless for the date variable \"",
            "                f\"'{_xa}'; drawing a date axis instead.\",",
            "                UserWarning,",
            "            )",
            "            _xs_log = False",
            "        if _y_date and _ys_log:",
            "            warnings.warn(",
            "                f\"dash: yscale(log) is meaningless for the date variable \"",
            "                f\"'{_ya}'; drawing a date axis instead.\",",
            "                UserWarning,",
            "            )",
            "            _ys_log = False",
            "        if _x_date: _fig_kw['x_axis_type'] = 'datetime'",
            "        elif _xs_log: _fig_kw['x_axis_type'] = 'log'",
            "        if _y_date: _fig_kw['y_axis_type'] = 'datetime'",
            "        elif _ys_log: _fig_kw['y_axis_type'] = 'log'",
            "        fig = bokeh_figure(**_fig_kw)",
            "        # WP-31 K6: the figure's host is an image named from its graph.",
            "        _dash_name_figure(fig, go, plots)",
            "        # WP-34 AX-3: the page's Stata table, stamped before the layers so the colour keys read it (A-16).",
            "        fig._dash_stata_ticks = getattr(_dash_cur_mapper(), '_dash_stata_ticks', None)",
            "        # WP-30 P1.3a: twoway's margin and the scheme's tick counts.",
            "        fig._dash_margin = _dash_plot_margin(_dash_cur_scheme(), go)",
            "        fig._dash_margin_args = (_dash_cur_scheme(), go)",
            "        fig._dash_numticks = _dash_by_numticks(_dash_cur_scheme(), go)",
            "        fig._dash_by_graph = bool(str((go or {}).get('by', '') or '').strip())",
            "        _dash_mark_date_axes(fig, _x_date, _y_date, _x2_date, _y2_date)",
            "        for _axis, _kind, _avar in ((fig.xaxis, _x_date, _xa),",
            "                                    (fig.yaxis, _y_date, _ya)):",
            "            if _kind:",
            "                _axis.formatter = _dash_date_axis_formatter(",
            "                    _dash_date_fmt(_FORMATS.get(_avar), _kind), '',",
            "                    _fmt_cache)",
            "        # Scheme first, so an explicit graph option still wins --",
            "        # through the SchemeParser method the saved figure uses,",
            "        # not a hand-copied rendering of it.",
            "        _dash_cur_scheme().apply_to_figure(fig)",
            "        # yaxis(2)/xaxis(2): the second axis, from the rows this",
            "        # figure draws.  There used to be none when served.",
            "        _dash_add_secondary_axes(fig, plots, go, g_df,",
            "                                 _reported_subopts, gname,",
            "                                 var_labels, _dash_cur_scheme(),",
            "                                 date_axes={_nm: (_v, _dash_date_fmt(",
            "                                     _FORMATS.get(_v), _k))",
            "                                     for _nm, _v, _k in (",
            "                                         ('y2', _ya2, _y2_date),",
            "                                         ('x2', _xa2, _x2_date)) if _k}",
            "                                 # WP-31 C10e: axes 3-9 of dates too.",
            "                                 | _dash_extra_date_axes(plots, _date_vars,",
            "                                                         _FORMATS, 3),",
            "                                 fmt_cache=_fmt_cache)",
            "        # title(), xtitle()/ytitle() sub-options, after the scheme so",
            "        # the user's size() and color() win; the rest named.",
            "        _dash_figure_title(fig, go, _reported_subopts, gname)",
            "        _dash_style_axis_titles(fig, go, _reported_subopts, gname)",
            "        # Initialised with the figure, not with the plot loop: a",
            "        # faceted graph never enters that loop and would reach the",
            "        # legend block with the name unbound.",
            "        _leg_bounds = []",
            "        # range() and reverse are applied by _dash_apply_scale_ranges,",
            "        # after the region colours below, as the saved figure does.",
            "        # plotregion(), graphregion(), bgcolor(), plotbgcolor(): the",
            "        # saved figure's one reader (WP-30 P1.20a).",
            "        _dash_apply_regions(fig, go, _dash_cur_scheme(), _reported_subopts, gname)",
            "        _dash_apply_scale_ranges(fig, _xsc, _ysc, g_df, xv, yv,",
            "                                 rescale=_rescale)",
            "        # note(), caption(), subtitle(): the helper the saved renderer",
            "        # runs, at the scheme's text-box sizes and colours.",
            "        _dash_text_annotations(fig, go, _reported_subopts, gname, _dash_cur_scheme())",
