            "            ftype, fvar, _dash_filter_frame_column(df, fvar, _frame_cols, _EMBED['graph_rows'])[_EMBED['filter_rows'][_fi].to_numpy(dtype=bool)],",
            "            _ftitle, vlabels,",
            "            date_kind=_date_vars.get(fvar, ''),",
            "            max_options=_dash_lim['filter_options'],",
            "            fmt=_FORMATS.get(fvar, ''),",
            "            storage=_storage_types.get(fvar, ''),",
            "            fmt_cache=_fmt_cache,",
            "            direction=fspec.get('direction') or 'ltr')",
            "        if widget is None:",
            "            if ftype not in _DASH_FILTER_TYPES:",
            "                _dash_warn_filter_type(fvar, ftype)",
            "            elif ftype in ('range', 'slider'):",
            "                warnings.warn(",
            "                    f\"dash: filter '{fvar}' type '{ftype}' requires numeric \"",
            "                    f\"data; skipping widget (use type(dropdown) for string \"",
            "                    f\"columns).\",",
            "                    stacklevel=2,",
            "                )",
            "            continue",
            "        widget._dash_var = fvar",
            "        widget._dash_exclude = fexcl",
            "        filter_widgets.append(widget)",
            "        filter_var_widgets[fvar] = widget",
            "",
            "    # ---- Wire filter callbacks ----",
            "    # Snapshot original (pre-filter) data for every raw source so that",
            "    # derived columns that are not in _df_ref (e.g. __dash_xjit/__dash_yjit from",
            "    # jitter()) can be correctly filtered by row index instead of being",
            "    # blanked with [] after each filter interaction.",
            "    _orig_src_data: dict = {}",
            "    for _gs_list in graph_sources.values():",
            "        for _s in (_gs_list if isinstance(_gs_list, list) else [_gs_list]):",
            "            _orig_src_data[id(_s)] = {c: list(v) for c, v in _s.data.items()}",
            "",
            "    # The rows a brushed source counts when nothing is selected, by",
            "    # id(): its graph's or panel's rows, and for the link group's",
            "    # source every row -- the rows the saved page's source holds,",
            "    # whose brush script counts that source whole (_BRUSH_JS).  A",
            "    # move writes them afresh before it clears the selection; only",
            "    # when a card follows the brush, since nothing else reads them.",
            "    _brush_on = _brush_filter or any(",
            "        k.get('update', 'filter') in ('brush', 'both') for k in kpi_defs)",
            "    _brush_rows: dict = {}",
            "    for _bgn, _bsl in graph_sources.items():",
            "        for _bs in (_bsl if isinstance(_bsl, list) else [_bsl]):",
            "            if _bgn in _owner_rows:",
            "                # The rows the graph draws (WP-29 P0.11), as the",
            "                # saved page's source holds them.",
            "                _brush_rows[id(_bs)] = _owner_rows[_bgn].intersection(",
            "                    _EMBED_GROWS.get(_facet_to_orig.get(_bgn, _bgn), df.index))",
            "    for _k, _ss in enumerate(_shared_sources):",
            "        _brush_rows[id(_ss)] = df.index[_EMBED_LINKS[_k]]",
            "",
            "    # The views over the link group's ONE source, with the rows each",
            "    # owns -- a by() panel's, a qualified graph's or layer's -- read",
            "    # now, while the source holds every row.  A move writes the",
            "    # source once and recounts each view (_dash_refresh_linked).",
            "    _linked_views = {id(_ss): _dash_linked_views(figures.values(), _ss)",
