            "            for _g in _groups:",
            "                for _s in _g:",
            "                    if _s is not None and id(_s) not in _seen:",
            "                        _seen.add(id(_s))",
            "                        _out.append(_s)",
            "            return _out",
            "        def _dash_move_plan(worker=False):",
            "            \"\"\"Loop thread (WP-30 P1.31b): read every widget once.",
            "",
            "            Every target's own mask, from a mask cache of this plan's",
            "            own, so a plan waiting for the worker is never changed by",
            "            a later move; with *worker*, the mapper copy and scheme",
            "            the worker draws with (_dash_plan_mapper), taken here, on",
            "            the loop, where no build is part-way through.",
            "            \"\"\"",
            "            _masks = {}",
            "            _tm = {}",
            "            for gname in _all_sources:",
            "                _tm[gname] = _mask_for(gname, _masks=_masks)",
            "            for _sid, _sm in _shared_members.items():",
            "                if _sm:",
            "                    _tm[('link', _sid)] = _mask_for(None, _sm, _masks=_masks)",
            "            for key in _agg_srcs:",
            "                _tm[key[0]] = _mask_for(key[0], _masks=_masks)",
            "            for kpi in _kpi_defs:",
