            "                    _tm[kpi.get('name', '')] = _mask_for(kpi.get('name', ''),",
            "                                                         _masks=_masks)",
            "            plan = {'masks': _tm, 'gen': None, 'loop': None,",
            "                    'mapper': None, 'scheme': None,",
            "                    # WP-32: each source's selection now, so a brush",
            "                    # made while the move waits is told apart.",
            "                    'sel': _dash_sel_snapshot(_dash_move_srcs())}",
            "            # The document's own mapper and scheme (WP-32): a build",
            "            # off the loop drew with a copy of its own.",
            "            if worker or _doc_mapper is not _DASH_MAPPER:",
            "                plan['scheme'] = _doc_scheme",
            "                plan['mapper'] = _dash_plan_mapper(_doc_mapper, _doc_scheme)",
            "            return plan",
            "        _df_ref_all = _df_ref",
            "        def _dash_agg_frame(plan, key):",
            "            # The rows one aggregated layer redraws from (worker or loop).",
            "            gname = key[0]",
            "            # This layer's OWN mask (GAPS2 E2), not every widget's.",
            "            mask = plan['masks'][gname]",
            "            # The graph's own frame's columns (WP-33 33-07).",
            "            _df_ref = _dash_frame_rows(_gfac_to_orig.get(gname, gname), _df_ref_all)",
            "            fdf = _df_ref[mask]",
            "            # Derive per-facet data frame analogously to raw source update.",
            "            # Faceted aggregates must recompute from the facet's subgroup,",
            "            # not from global fdf, to stay in sync after filter changes.",
            "            if gname in _fgvals:",
            "                _bvs_a, _gkey_a = _fgvals[gname]",
            "                if _gkey_a is None:",
            "                    # The Total panel: its own rows the move",
            "                    # keeps.  fdf holds a missing by() value,",
            "                    # which Total never draws (by(), missing",
            "                    # aside): a Total lfit after a move was",
            "                    # fitted on it, 29.4709 at weight 1800",
            "                    # where Stata's regress on the panel's 5",
            "                    # rows and the saved page give 29.5622",
            "                    # (measured 24sep2026).",
            "                    _own_a = _owner_rows.get(gname)",
            "                    agg_fdf = (fdf if _own_a is None",
            "                               else fdf[fdf.index.isin(_own_a)])",
            "                else:",
            "                    _fmask_a = mask.copy()",
            "                    if len(_bvs_a) == 1:",
