            "    _brush_tables: list = []",
            "    if _brush_filter:",
            "        from bokeh.models import AllIndices, IndexFilter, IntersectionFilter",
            "        for _bf_fig in figures.values():",
            "            _bk = getattr(_bf_fig, '_dash_link_group', None)",
            "            if _bk is None:",
            "                continue",
            "            for _bf_r in getattr(_bf_fig, 'renderers', []) or []:",
