            "                    continue",
            "                _brush_wired.add(id(_bds))",
            "                _bds.selected.on_change('indices', _dash_event_throttle(",
            "                    doc, _dash_touch(_make_brush_cb(kpi_divs, kpi_defs, df, _bds,",
            "                                                    _raw=_braw))))",
            "",
            "    # ---- CSV download (WP-21) ----",
            "    # Opt-in (dash build, csv).  The server masks its frame with",
            "    # the filters' own rule and puts the rows in a source; then it",
            "    # bumps the button's tags, which fires the page, where the",
            "    # saved page's formatter writes them -- a new tag each click,",
            "    # so the same rows twice are two files.  The source rides in",
            "    # that callback's args, which is what makes it part of the",
            "    # document: one referenced by nothing on the page would never",
            "    # reach the browser.  A token bucket holds a session to two",
            "    # downloads at once and one every five seconds after.",
            "    if _dash_csv_wanted(bo):",
            "        _csv_meta = _dash_csv_meta(",
            "            list(df.columns), bo.get('formats', {}) or {},",
            "            meta.get('type_is_str', {}) or {}, val_labels,",
            "            val_label_names, storage_types=_storage_types,",
            "            display_names=dict({k: v['expr'] for k, v in",
            "                                (meta.get('tsop_cols') or {}).items()},",
            "                               **{e['col']: '%s [frame %s]' % (v, e['frame'])",
            "                                  for m in _frame_cols.values() for v, e in m.items()}))",
            "        _csv_src = ColumnDataSource(data={})",
            "        _csv_btn = _DashButton(label='Download CSV',",
            "                               name='dash_csv_download',",
            "                               width=_DASH_CSV_BUTTON_WIDTH)",
            "        _csv_btn.js_on_change('tags', _DashCustomJS(",
            "            args={'src': _csv_src, 'meta_json': json.dumps(_csv_meta)},",
            "            code=_DASH_CSV_SERVED_JS))",
            "        _csv_widgets = list(filter_widgets)",
            "        _csv_seq = [0]",
            "        def _send_csv(attr, old, new):",
            "            _csv_rows = df[_dash_frame_filter_mask(df, _csv_widgets)]",
            "            _csv_seq[0] += 1",
            "            _csv_src.data = _dash_csv_payload(_csv_rows, _csv_meta)",
            "            _csv_btn.tags = [_csv_seq[0]]",
            "        _csv_send = _dash_event_throttle(doc, _dash_touch(_send_csv),",
            "                                         rate=_DASH_CSV_RATE,",
            "                                         burst=_DASH_CSV_BURST)",
            "        _csv_btn.on_click(lambda event: _csv_send('clicks', None, None))",
            "        # After the filters in their bar or sidebar; a dashboard with",
            "        # no filter gets a bar of its own.  A new list: the recompute",
            "        # callbacks keep the filters' own.",
            "        filter_widgets = list(filter_widgets) + [_csv_btn]",
            "    # WP-32: the stale cue's status line, before the reset button",
            "    # as on the saved page, for a fit drawn from Stata's points.",
            "    _stale_status = _dash_points_stale_models(agg_sources)",
            "    if _stale_status is not None and filter_widgets:",
            "        filter_widgets = list(filter_widgets) + [_stale_status]",
            "    # The row ends in Reset filters (WP-31 H2f), as the saved one does.",
            "    if _reset_btn is not None:",
            "        filter_widgets = list(filter_widgets) + [_reset_btn]",
            "",
            "    # The recompute cue (WP-30 P1.31b): a served session's move waits",
            "    # for the worker with its drawing kept, and says so.  Constant text,",
            "    # no style and no script (the page's policy); a document with no",
            "    # server session recomputes inline and gets none.",
            "    if _dash_worker_wanted(doc) and any(hasattr(_w, '_dash_var') for _w in filter_widgets):",
            "        _slot.cue = Div(text='Updating...', name='dash_updating', visible=False,",
            "                        html_attributes={'role': 'status', 'aria-live': 'polite'})",
            "        filter_widgets = list(filter_widgets) + [_slot.cue]",
            '    # ---- Assemble grid layout ----',
            '    #',
            '    # layout(), tabs(), filterposition() and subtitle() used to be read by',
            '    # nothing here: the grid came from len(all_names) alone and the other',
            '    # three keys were decoded out of the spec and dropped.  Two apps whose',
            '    # specs differed only in these were byte-identical.',
            "    layout_opt = (bo.get('layout', '') or 'auto').strip()",
            "    tabs_opt = bo.get('tabs', '') or ''",
            "    filter_position = (bo.get('filter_position', '') or 'top').strip().lower()",
            "    # Raw: the header builder escapes it exactly once.",
            "    subtitle_text = bo.get('subtitle', '') or ''",
            '',
            "    registry = bo.get('registry', '') or ''",
            "    # The registry as typed, graphs and KPI cards alike -- the",
            "    # saved renderer's rule as well now.",
            "    all_names = _dash_layout_order(registry, graphs,",
            "                                   kpi_defs + (spec.get('images') or []))",
            '',
            '    def _gopts_of(name):',
            '        return _dash_graph_options_of(graphs, name)',
            '',
            '    def _dash_cell(name):',
            '        """The renderable for one registered name, or None -- the',
