            '    doc.add_root(layout)',
            "    # The stacked view of every by() grid (WP-30 P1.15c).",
            "    _by_hooks = (_dash_by_stack_hooks([layout])",
            "                 + _dash_arrow_head_hooks([layout]))",
            "    # WP-31 H1: the served app logs a script error server-side;",
